window.WF_GAME_UPDATES = {"source":"https://www.warframe.com/en/patch-notes","note":"Parsed from the official Warframe patch notes. TL;DR = DE section headings plus item counts; mentions = names from the calculator data found in the notes.","parser":1,"checkedAt":"2026-10-16T01:42:11.394Z","releases":[{"slug":"44-1-2","version":"44.1.2","kind":"hotfix","title":"Iceblade of Narin: The Icebind: Hotfix 44.1.2 + 2.1","url":"https://www.warframe.com/en/patch-notes/pc/44-1-2","forum":"https://forums.warframe.com/topic/1528620-iceblade-of-narin-the-icebind-hotfix-4412-2/","date":"2026-10-15","dateSource":"patch notes","tldr":"Tau Prologue Quest Series; Epoch Operation: Taubound; The Icebind. 31 fixes, 4 other changes.","fixes":31,"changes":4,"highlights":["Tau Prologue Quest Series","Epoch Operation: Taubound","The Icebind"],"mentions":[{"name":"Ash","kind":"Warframe","n":1},{"name":"Bronco Prime","kind":"Weapon","n":1},{"name":"Chroma","kind":"Warframe","n":1},{"name":"Citrine Prime","kind":"Warframe","n":1},{"name":"Harrow","kind":"Warframe","n":1},{"name":"Inaros","kind":"Warframe","n":1},{"name":"Jade","kind":"Warframe","n":1},{"name":"Mirage","kind":"Warframe","n":1},{"name":"Nova","kind":"Warframe","n":1},{"name":"Saryn","kind":"Warframe","n":1},{"name":"Secondary Enervate","kind":"Arcane","n":1},{"name":"Uriel","kind":"Warframe","n":1},{"name":"Volt Prime","kind":"Warframe","n":1},{"name":"Zephyr","kind":"Warframe","n":1}],"parts":[{"title":"Iceblade of Narin: The Icebind: Hotfix 44.1.2.1","sections":[{"title":"Fixes","items":["Fixed crashing and/or severe performance issues when entering The Dark Refractory as part of the Lua quest in the Prologue to Tau.",{"p":"For a list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1523875-known-issues-iceblade-of-narin/"}]}]},{"title":"Iceblade of Narin: The Icebind: Hotfix 44.1.2","sections":[{"title":"Tau Prologue Quest Series","items":[{"p":"A series of new Prologue Quests are available in the Codex!"},{"p":"These short Prologue Quests set the stage for the start of our journey. Players who have completed both The Hex and The Old Peace quests will see the Tau Prologue Series in their Codex upon login."},{"p":"These Prologue Chapters are a permanent addition to the Main Story, and are replayable."},{"p":"The road to Tau is long, Tenno. But together, we're finally going!"}]},{"title":"Epoch Operation: Taubound - Begins at 11:00 AM ET!","items":[{"p":"Launching alongside this hotfix is a new once in a Star Chart Operation, Epoch Operation: Taubound. This community event forms part of the preparation for us to make the journey to Tau."},{"p":"For a full breakdown of the event and what to expect please read our dedicated post here: https://forums.warframe.com/topic/1528603-epoch-operation-taubound/."}]},{"title":"Changes","items":["Added a shortcut to the Riven Splicing menu while on the Riven Cycling screen.","Updated the on-hover Lock Riven Trait description to specify that Locking a trait also locks the number of positive and negative traits when cycling.","Reduced the Bronco Prime Barrel's Ducat price from 45 to 25 due to changes in its rarity from Void Relics."]},{"title":"The Icebind Changes & Fixes","items":["Added SFX to various elements in The Icebind, including SFX for connecting and reconnecting a Signal Bridge, and more.","Fixed cases of returning players from a Host Migration not being transported to the treasure room if the mission objective was completed and extraction was paused due to an active Side Objective.",{"t":"Now, the active Side Objective will be cancelled for returning players so they can properly extract.","d":1},{"t":"Also fixed cases of returning hosts loading into a mission by themselves instead of the treasure room with the rest of their squad.","d":1},"Fixed certain Mars Excavation Cryobells resulting in players not being teleported to The Icebind's treasure room if the final Side Objective was Cryothermia.","Fixed issues with the \"Take Cryobell\" context action."]},{"title":"Top Fixes","items":["Fixed Ash marking enemies with Bladestorm and then using Transference causing the marks to remain, but Bladestorm not being performed on them.","Fixed Client Chroma's Elemental Ward element always being Heat, regardless of emissive tint.","Fixed Nova's Wormhole spawning far from her if it's aimed directly upwards.","Fixed Secondary Enervate being able to proc infinitely off of Zephyr's Tornados."]},{"title":"Fixes","items":["Fixed Uriel's Infernum Augment using the incorrect SFX for the explosion sounds.","Fixed a [PH] appearing next to Slam Damage in the Riven Splicing menu.","Fixes towards the desaturated areas on the Saryn Velenosa Skin becoming vibrant following our metal shader changes.","Fixed Citrine Prime's shoulder attachment offsets being asymmetrical.","Fixed material issues on the Harrow Profitas Helmet.","Fixed being able to own multiple copies of the Kyzen and Karotic Signas.","This offered no benefit to players, other than cluttering their list of Signas in customization menus!","Fixed the glass in the Personal Quarters appearing almost white on lower spec devices.","Fixed Commandeered Volt Prime's electrical beam VFX not being removed after the ability ends.","Fixed an additional rare case of Inaros being revived with function loss if he died at the start of casting Sandstorm with an item (ex: Power Cell) in his hands.","Fixed a map hole in the Yuvan Peak Captura Scene.","Fixed various blocking volumes appearing in The War Within Choice Captura scene.","Fixed the Circuit \"Choose Your Path\" screen overlapping the friends menu if you join a Friend's Circuit session in progress without yet having chosen your weekly path.","Fixed opening a Chatlinked item while in the \"Ring a Cryobell\" screen causing the menus to overlap.",{"p":"Script Error Fixes:"},{"p":"Script errors mean that something went wrong when the game client was executing a script, which can have various outcomes. Usually it means the related content didn't function properly under specific circumstances - often we don't actually know what the error outcome was, so we list it as a Script Error fix to indicate it was addressing an unintended behaviour."},"Fixed a script error caused by resource containers exploding from Mirage's Sleight of Hand while she is dead.","Fixed a script error caused by Jade's Symphony of Mercy going on cooldown (ex: in a Sanctuary Onslaught mission).","Fixed a script error when hovering over pop-ups.","Fixed a script crash at the end of the Surge Eximus' speed ability.","Fixed a script error in the Operator/Drifter loadout menu.","Fixed a script error in a Warframe's Configuration screen in Teshin's Cave in Duviri.","Fixed a script error when backing out of a menu.","Fixed a script error related to buff notifications.","Fixed a script error when hovering over different categories in the Railjack menu.",{"p":"For a list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1523875-known-issues-iceblade-of-narin/"}]}]}]},{"slug":"44-1-1","version":"44.1.1","kind":"hotfix","title":"Iceblade of Narin: The Icebind: Hotfix 44.1.1","url":"https://www.warframe.com/en/patch-notes/pc/44-1-1","forum":"https://forums.warframe.com/topic/1527669-iceblade-of-narin-the-icebind-hotfix-4411/","date":"2026-10-08","dateSource":"patch notes","tldr":"The Icebind; Riven Splicing. 39 fixes, 4 other changes.","fixes":39,"changes":4,"highlights":["The Icebind","Riven Splicing"],"mentions":[{"name":"Sirius & Orion","kind":"Warframe","n":2},{"name":"Banshee","kind":"Warframe","n":1},{"name":"Cascadia Empowered","kind":"Arcane","n":1},{"name":"Kullervo","kind":"Warframe","n":1},{"name":"Protea","kind":"Warframe","n":1}],"parts":[{"title":"Iceblade of Narin: The Icebind: Hotfix 44.1.1","sections":[{"title":"The Icebind Changes & Fixes","items":["The Icebind's voting timer no longer starts immediately once all players have selected a Cryobell. Now, the Host will have the option to start the timer, so players can discuss and strategize with the Cryobells available to them.",{"t":"Additionally, the timer will begin automatically if 3 players have voted on a Cryobell.","d":1},"Removed the ability to throw the Cryo Core as it was causing cases of function loss.","Tweaked the VFX of the damaging zone around the Entropy Orb.","Fixed Orokin Vaults being able to spawn in The Icebind missions, which sometimes would have Side Objectives spawning inside them.","Fixed losing a squad member resulting in the mission being progression stopped if a Side Objective was started before they left.","Fixed enemy spawning issues when attempting to complete a Side Objective after the mission completion requirements have been met, notably in Excavation missions.","Fixed the Indomitable Ice side objective's collision remaining after it disappears.",{"t":"Also fixed cases of players getting stuck in the side objective when it spawns in.","d":1},"Fixed various edge cases of invulnerability states negating Cryo Core health damage.","Fixed only Arson Eximus being able to spawn if the Inferno Mission Bind was active.",{"t":"Now other Eximus units can spawn, just at a lower rate.","d":1},"Fixed being able to equip multiple of the same Warframe in The Icebind by changing loadouts during the mission countdown.","Fixed certain voice lines in the Glacial Laboratory being incorrectly attributed to Cephalon Melica, instead of another figure.",{"t":"Also fixed the data pads using the wrong name for the context action.","d":1},"Fixed squadmates being able to interact with Log Data Pads in the Glacial Laboratory before they have unlocked them.","Fixed being able to fall through the map into the Glacial Laboratory (treasure room) by using /unstuck.","Fixed cases of item priority sorting not applying to rewards from The Icebind in the End of Mission screen.","Fixed letting a random Cryobell be selected in the vote (ie. no one voted) resulting in squadmates seeing different Cryobells selected.","Fixed the red border remaining around the Cryobell key if a player equipped and then unequipped a duplicate Warframe in the mission start menu."]},{"title":"Riven Splicing Changes & Fixes","items":["Players can now hover over Rivens with no compatible traits in the Riven Splicing screen to see their traits.","Fixed Weak Point Damage Spliced Traits not applying the bonus damage.","Fixed Rivens with a Spliced Trait incorrectly doubling the Kuva cost when Cycled.",{"t":"We'll be running a script to refund the missing Kuva, as early as tomorrow.","d":1},"Fixed the selected Riven not remaining selected when entering the Riven Splicing menu.","Fixed cases of Riven Mods with spliced traits being cut off when swapping between the Splicing and Fusion menus."]},{"title":"Other Fixes","items":["Fixed being able to take 6 player squads into non-Icebind missions.","Fixed Security Bypass pathing not always picking the closest Terminal.","Fixed Banshee becoming permanently invulnerable due to an interaction with Gaseous Quake.","Fixed The Icebind and Archimedea modifiers only applying to the Primary Son when using Sirius & Orion.","Fixed reviving as Sirius & Orion resulting in them falling through the map.","Fixed the skin on the Amir Gemini Skin appearing overly green.","Fixes towards the Cryobell Sumdali being blindingly bright in the Drifter Camp.","Fixed a crash related to the No Pets modifier in Archimedea missions.","Fixed being unable to skip The Hex kissing cutscenes."]},{"title":"Script Error Fixes","items":[{"p":"Script errors mean that something went wrong when the game client was executing a script, which can have various outcomes. Usually it means the related content didn't function properly under specific circumstances - often we don't actually know what the error outcome was, so we list it as a Script Error fix to indicate it was addressing an unintended behaviour."},"Fixed a script error related to revival Tombstones in The Icebind.","Fixed various script errors related to The Icebind mission start screen (including countdowns, and more).","Fixed a script error when opening a chest in The Icebind.","Fixed a script error related to Entropic Crystals caused by the Entropic Overload Bind.","Fixed a script error related to the Entropy Orb side objective in The Icebind.","Fixed a script error related to the Parasitic Light tactical bind in The Icebind.","Fixed a script error related to the Signal Chain side objective in The Icebind.","Fixed a script error related to a Flare KIM conversation in the POM-2.","Fixed a script error if Protea died while ragdolling during Temporal Anchor if an Entropic Overload bind was active in The Icebind.","Fixed a script error related to Summulysts.","Fixed a script error related to Cascadia Empowered.","Fixed a script error caused by an interaction between Kullervo's Collective Curse and certain Duviri Decrees.","Fixed a script error when hovering over Abilities and cycling through tabs quickly.",{"p":"For a list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1523875-known-issues-iceblade-of-narin/"}]}]}]},{"slug":"44-1-0","version":"44.1.0","kind":"update","title":"Update 44.1.0: Iceblade of Narin: The Icebind","url":"https://www.warframe.com/en/patch-notes/pc/44-1-0","forum":"https://forums.warframe.com/topic/1527298-update-4410-iceblade-of-narin-the-icebind/","date":"2026-10-07","dateSource":"patch notes","tldr":"New Gamemode: The Icebind; Selecting a Cryobell; Voting on a Cryobell; Standard Mission Traits. 40 fixes, 123 other changes.","fixes":40,"changes":123,"highlights":["New Gamemode: The Icebind","Selecting a Cryobell","Voting on a Cryobell","Standard Mission Traits","How to Start an Optional Squad Side Objective","Melica's Glacial Laboratory","Riven Expansion: Riven Splicing"],"mentions":[{"name":"Narin","kind":"Warframe","n":9},{"name":"Uriel","kind":"Warframe","n":4},{"name":"Jade","kind":"Warframe","n":3},{"name":"Caliban","kind":"Warframe","n":2},{"name":"Hikou","kind":"Weapon","n":2},{"name":"Oberon","kind":"Warframe","n":2},{"name":"Rhino","kind":"Warframe","n":2},{"name":"Volt","kind":"Warframe","n":2},{"name":"Wisp","kind":"Warframe","n":2},{"name":"Aksondol","kind":"Weapon","n":1},{"name":"Azima","kind":"Weapon","n":1},{"name":"Baruuk","kind":"Warframe","n":1},{"name":"Excalibur","kind":"Warframe","n":1},{"name":"Frost","kind":"Warframe","n":1},{"name":"Grendel","kind":"Warframe","n":1}],"parts":[{"title":"Update 44.1.0: Iceblade of Narin: The Icebind","sections":[{"title":"","items":[{"p":"Image Description: Six Warframes stand poised for battle within a frosty cave with the Warframe logo and The Icebind: New 6 Player Missions in the foreground. From left to right we can see: Wisp, Rhino, Volt, Excalibur, Mesa, and Mag."},{"p":"Time for an experiment, students! What happens if you ring that bell?"},{"p":"Our newest gamemode has arrived! The Icebind is an experiment for both us making Warframe, and for those playing it. This new mode aims to give players space to push their loadout and tackle cooperative objectives - as the community rings their Cryobells, we'll be watching for feedback as we continue to iterate on this project in phases."}]},{"title":"NEW GAMEMODE: THE ICEBIND","items":[{"p":"The Icebind is manifested through the Cryobell ceremony. High upon Yuvan Peak, Cryobells have formed, drawn out by Narin's influence. Each bell's tone leads to a time and place where a dark influence has taken hold. Six warriors must gather to ring the bell. Together they must overcome the Binds of a force not of this plane."}]},{"title":"General Overview for The Icebind","items":[{"p":"Players can ring a Cryobell to take them to The Icebind, a new mission type with these key characteristics:"},"Six player squads, where there can be no more than one of each Warframe.",{"t":"(i.e. no six man Pink Rhino Squads this time, sorry!)","d":1},"Approximately 10-15 minute long missions.","Level 999+ Enemies.","Each Cryobell (mission key) comes with a randomized mission type, enemy, location, and modifiers - the squad votes on which one to play!","Various mission restrictions, including No Self Revives, Gear Cooldown Increase, Empowered Enemies, and more.","Guaranteed Riven Splicer upon completion, plus an additional reward from the reward pool.","Bonus rewards for each Squad Side Objective completed (up to 3 per mission).","Players can complete these missions three times a week.*",{"t":"* players can stockpile up to six mission keys if they do not use them all each week.","d":1},{"p":"To access The Icebind, players must have completed the following:"},"Completed both the Angels of the Zariman and Whispers in the Walls quests","Unlocked (but not necessarily completed) either Elite Temporal Archimedea or Elite Deep Archimedea"]},{"title":"The Core Icebind Loop","items":[{"p":"The Icebind is different each time a player steps into it, beholden to the randomized traits of the Cryobell. Before we explain the various Binds (i.e. modifiers) introduced by the Cryobells, it's important to understand the core gameplay loop. This section explains the overarching structure of playing The Icebind, and the section following will outline the various Binds that can affect it."}]},{"title":"Starting The Icebind","items":[{"p":"This new mission can be started from Yuvan Peak, where players need to perform two important steps:"},"First, claim their Cryobells from the ice pillar atop Yuvan Peak.",{"t":"Three Cryobells form each week, following weekly reset at Midnight UTC on Sundays.","d":1},{"t":"Players can stockpile up to six Cryobells if they did not use them all in one week.","d":1},"Second, with Cryobells in-hand, speak to Cephalon Melica and select \"Ring a Cyrobell\"",{"p":"Doing so will open The Icebind party creation screen, where you can invite players to form your squad. The host can only form a six player squad using the \"Ring the Cryobell\" screen. With its launch, The Icebind does not have public matchmaking as these missions require more cooperation than traditional Warframe missions (which we'll cover a little more in the Squad Side Objective section)."}]},{"title":"SELECTING A CRYOBELL","items":[{"p":"Players who are invited to a Squad will be summoned to Yuvan Peak, where they can then gather their Cryobells and proceed to Cephalon Melica. All players must speak to Cephalon Melica and select \"Ring a Cryobell\" to start the mission."},{"p":"In this screen, players can edit their loadout and select which Cryobell they wish to ring. Your choice of Cryobell matters, because it determines your Personal Bind (which is a guaranteed personal modifier for the mission, regardless of which Cryobell is chosen by the squad) and which version of The Icebind players will vote on (including the mission type, enemy type, and modifiers)."},{"p":"Image Description: Screenshot of the Select Cryobell UI showing three Cryobells and some of their traits. From left to right we see: a Disruption on Earth against the Corpus, a Mobile Defense on Ceres against The Murmur, and an Excavation on Pluto against the Orokin."},{"p":"When selecting a Cryobell, you'll be able to see each of the traits it will give to your mission:"},"Mission Type","Planet","Enemy Type","Mission Bind","Tactical Bind","Personal Bind",{"p":"We'll go over all of these randomized traits in the \"Cryobells and their Binds\" section of this Dev Workshop."},{"p":"After all players have selected a Cryobell, the entire squad can vote on which one to play!"}]},{"title":"VOTING ON A CRYOBELL","items":[{"p":"Once all players have selected a Cryobell, a 60 second voting countdown begins. Players can review all of the available mission options available to them, and vote on which one to play! If no votes are cast, a random Cryobell is chosen; in the case of a tie, the Host's vote is the deciding choice."},{"p":"Image Description: Screenshot of The Icebind UI after each player has selected their Cryobell and are voting on the mission. From left to right we can see your current loadout and each players' Cryobell traits. Underneath we see icons for Standard Mission Traits, the mission start timer, your Personal Bind, and the option to view Rewards."},{"p":"Once voting concludes, players have an additional 10 second countdown to review the selected Cryobell before the mission begins."},{"p":"While Cryobells are consumable mission keys, rest assured Cryobells are not spent until players have successfully extracted from The Icebind."}]},{"title":"Playing The Icebind","items":[{"p":"Entering the Icebind, you'll be starting a mission as you normally would - as normal as it can be, considering randomized Binds of a Cryobell. Players will be presented with either a Survival, Mobile Defense, Excavation, or Disruption mission depending on the chosen Cryobell. At the beginning, you'll be prompted to start your objective and aim to complete it successfully, with bonus Squad Side Objectives spawning in at regular intervals to keep things interesting. We'll get to those in a bit!"},{"p":"While many elements of The Icebind are random, there are guaranteed elements you can expect each time you play."}]},{"title":"STANDARD MISSION TRAITS","items":["Enemy Level: 999+","Guaranteed Reward: Riven Splicer (plus Kuva and an additional reward from the Reward Pool after opening a Crested Frozen Chest)","No Duplicate Warframes: Only one of each Warframe can enter the mission.","Mission Restrictions:",{"t":"Empowered Enemies: Enemy Health and Shields and Armor increased by 200% and an additional 100% for each squad member, stacking to a maximum of 800%. Increased chance of Eximus.","d":1},{"t":"No Self Revive: After a Tenno has bled-out, a Tombstone will appear where they fell. At least 3 surviving Tenno must sacrifice part of their health temporarily to bring the Tenno back into the action. If fewer than 3 Tenno are still standing then all of them must make the sacrifice to revive others.","d":1},{"t":"Last Gasp Penalty: Activating the Last Gasp focus ability reduces the timer by 2 seconds.","d":1},{"t":"Bleedout Shortens: The bleedout timer shortens after each revive, to a minimum of 5 seconds.","d":1},{"t":"Frozen Keys: After being dead for 3 minutes you will not obtain any Frozen Keys that the squad acquires from completing objectives while you are dead.","d":1},{"t":"Cooldown Increase: Each type of Restore has a 3 minute cooldown timer applied.","d":1},{"t":"Fatigued Companions: Companion Recovery timer increased by 100%.","d":1},{"t":"Stunted Shields: Full Shield Gate immunity duration reduced by 50%.","d":1},{"p":"As the mission progresses, Squad Side Objectives begin to spawn for a total of 3 per mission."},{"p":"Look for the purple waypoint on your minimap indicating a Squad Side Objective is available. These side objectives are optional, but completing them gives the squad extra rewards!"}]},{"title":"HOW TO START AN OPTIONAL SQUAD SIDE OBJECTIVE","items":[{"p":"Depending on the objective, a certain number of Squad members are required to be nearby before it can be even started. This is important, because failing a Squad Side Objective will fail your mission and require you to start again. Choosing to do Side Squad Objectives is a matter of risk vs reward - do you trust your squad to succeed, and in return earn a Frozen Key to unlock more rewards? Or will you decide to not start the Squad Side Objectives and just earn the guaranteed Riven Splicer and completion reward upon mission success?"},{"p":"To ensure these are not started until players are ready, the Side Objective must be activated via a \"Start\" prompt, which then updates the objective description to indicate how many players need to be nearby. Once enough players are in the area, the objective will begin! Through teamwork, you all must work together to complete your task within the allotted time."},{"p":"With The Icebind's launch, there are 5 Squad Side Objectives to master:"},"Lockbox: collect Cyphers from fallen enemies and bring them to the Lockbox to unlock it.","Cryothermia: neutralize a Cryo Core by holding it while it deals escalating damage to player health.","Indomitable Ice: charge ice crystals with concentrated fire.","Entropy Orb: gather around the orb and avoid its damaging pulses.","Signal Chain: connect a beam of energy between one point to another using your Warframes.",{"p":"Successfully completing a Squad Side Objective rewards all squad members with a Frozen Key, which can be used to unlock rewards in a special treasure room upon mission completion."},{"p":"Since players can try to tackle 3 of these objectives in one mission, time management is another factor to master! Rest assured, if you are rushing to complete your final Squad Side Objective before the mission ends, the mission will not extract players if there is an active Squad Side Objective*. Once that is complete, you'll be whisked away to the end of mission screen (whether that's a mission fail or mission success is up to your performance)."},{"p":"* Specifically, if the Squad Side Objective has had the \"Start\" input pressed - not just the waypoint appearing on the map."}]},{"title":"MELICA'S GLACIAL LABORATORY","items":[{"p":"The Icebind doesn't end with the usual race towards extraction. Instead, once the mission is complete, players will be immediately transported to Melica's Glacial Laboratory. Here, they can use their earned Keys to unlock chests and collect what was earned. Players are also rewarded a guaranteed Riven Splicer upon mission completion! Learn more about Riven Splicing in our dedicated section below."},{"p":"There are two different Keys that are earned in The Icebind:"},"Crested Frozen Key - guaranteed reward for completing the mission","Frozen Key - earned by completing Squad Side Objectives, up to 3 can be obtained per mission",{"p":"Crested Frozen Keys open Crested Frozen Chests, which appear at the center of the map. Full drop rates can be found on our official Droptable Site."}]},{"title":"Crested Frozen Key Rewards","items":["Guaranteed Kuva:",{"t":"7,500 Kuva","d":1},{"t":"17,500 Kuva","d":1},{"t":"100,000 Kuva","d":1},"Additional Reward Table:",{"t":"Riven Transmuter","d":1},{"t":"Veiled Riven Cipher","d":1},{"t":"Omni Forma","d":1},{"t":"Forma Bundle","d":1},{"t":"Melee Riven Mod","d":1},{"t":"Pistol Riven Mod","d":1},{"t":"Rifle Riven Mod","d":1},{"t":"Shotgun Riven","d":1},{"t":"Archgun Riven Mod","d":1},{"t":"Companion Weapon Riven Mod","d":1},{"t":"Azure Archon Shard","d":1},{"t":"Crimson Archon Shard","d":1},{"t":"Amber Archon Shard","d":1},{"p":"Frozen Keys open Frozen Chests, which can be found on the outside edges of the map. Full drop rates can be found on our official Droptable Site."}]},{"title":"Frozen Key Rewards","items":["Guaranteed Kuva:",{"t":"1,750 Kuva","d":1},{"t":"3,500 Kuva","d":1},{"t":"7,500 Kuva","d":1},"Additional Reward Table:",{"t":"Forma","d":1},{"t":"200 Vosfor","d":1},{"t":"3 Day Affinity Booster","d":1},{"t":"3 Day Resource Drop Chance Booster","d":1},{"t":"3 Day Resource Booster","d":1},{"t":"3 Day Credit Booster","d":1},{"t":"Melee Riven Mod","d":1},{"t":"Pistol Riven Mod","d":1},{"t":"Rifle Riven Mod","d":1},{"t":"Shotgun Riven","d":1},{"t":"Azure Archon Shard","d":1},{"t":"Crimson Archon Shard","d":1},{"t":"Amber Archon Shard","d":1},{"p":"Once you've unlocked your Chests, you can proceed to the marked extraction point. That said, there are more than just rewards to be found in Melica's Glacial Laboratory - curious Tenno may wish to search the room for fragments from the distant past."}]},{"title":"First-Time Completion Reward","items":[{"p":"Completing The Icebind for the first time also rewards players with a Cryobell Sumdali, as proof that they have overcome the Binds of a force not of this plane."}]},{"title":"Cryobells and their Binds","items":[{"p":"Now that you should have a basic understanding of the core loop when playing The Icebind, it's time to talk about the Cryobells. Formed through Narin's influence on Yuvan Peak, each bell's tone leads to a time and place where a dark influence has taken hold, manifesting as different Binds that alter the player's experience."},{"p":"Bound to each Cryobell is a randomized set of traits, which determines the mission it will take you to:"},"Mission Type","Mission Location","Enemy Type","Personal Bind","Mission Bind","Tactical Bind",{"p":"Let's go over what each of these can be!"}]},{"title":"Mission Type","items":["Survival (10 Minutes)","Mobile Defense (3 Terminals of 3 minutes each)","Excavation (600 Cryotic)","Disruption (8 Conduits)"]},{"title":"Mission Location","items":["Any Planet in the Origin System, excluding Duviri, The Dark Refractory, and Höllvania."]},{"title":"Enemy Type","items":["Grineer","Corpus","Infested","The Murmur","Orokin"]},{"title":"Personal Bind","items":[{"p":"Your Cryobell's Personal Bind applies to you in-mission, regardless of what Cryobell was chosen by the Squad."},"Abbreviated Abilities: Ability durations reduced by 50%.","Ability Overload: Using an ability opens a void rift nearby.","Ammo Deficit: Ammo restored by drops and gear is reduced by 75%","Constricted: Max energy reduced by 75%.","Dark Antimatter: Enemies slain by ability damage create a hostile antimatter drop that is attracted to you.","Dropped Guard: Warframe and ally Overguard* gain reduced by 75%.",{"t":"*Overguard gained from Allies, this Bind does not affect your squadmates' Overguard.","d":1},"Dull Blades: -50% melee combo chance.","Energy Exhaustion: Lose 2 Energy per second for each enemy within 10 meters of you.","Firewalker: For each meter travelled on foot, take increasing heat damage over time. Jumping or being airborne reduces it.","Flankable: Max shield capacity is reduced by 75%, but an impenetrable Volt shield is permanently in front of you.","Fractured Armor: Casting an ability reduces armor by 10% for 10s.","Framecurse Syndrome: Activating an Ability inflicts 50 health and 150 shield damage upon you.","Hypersensitive: Duration of negative Status Effects is tripled","Knifestep Syndrome: Lose 2 Health when moving. Jumping pauses the effect.","Lethargic Shields: Shield recharge delay increased 500%.","Performance Anxiety: A spotlight chases you. Killing enemies while illuminated inflicts damage on you that increases with each kill.","Permanent Injury: Max health reduced each time health damage is taken","Secondary Wounds: Gain 1 Puncture Status Effect every time you take damage.","Shocking Leaps: Jumping or Bullet Jumping generates a Shock Eximus orb that chases you.","Slam Spikes: Melee Slam Attacks cause damaging spikes to erupt from the ground for 2s after the slam.","Static Siphon: Casting abilities causes all enemies within 15m to emit damaging electrical chains back to the caster.","Undersupplied: Max ammo on all weapons reduced by 75%","Untreatable: Pickups do not heal, and Health Orbs cannot be picked up."]},{"title":"Mission Bind","items":[{"p":"A Mission Bind is a complication that alters the entire theme of the mission. These introduce gameplay elements to work around, and can affect what type of units spawn."},"Entropic Overload: Using abilities spawns Entropic Crystals on you and triggers Entropic Overload, causing enemies to self-revive as Leech Eximus and hostile Entropic Wisps appear. Getting hit by a Wisp causes stacked crystals to explode. Destroying Entropic Crystals and Wisps will decrease saturation.","Stone Soldiers: Enemies are hard as stone and hit even harder. Taking them by surprise is the best way to exploit weak points in their stony flesh. In addition, you will face hostile Tomb Guardians.","Miasmic Militia: Enemies slowly take damage, but are immune to Toxin, Gas, Viral, and Corrosive status effects. On death, a Gas cloud is released.","Thin Boundary: Void Tears rip into reality, growing with nearby ability use. Tears inflict Void Shackles, reducing ability stats and weapon combo durations, while draining energy, health, and Incarnon weapon energy.","Inferno: Heat Status present on players or enemies will feed the Inferno, drawing in Arson Eximus, Heat empowered enemies, and damaging anyone near active sources of Heat. Avoid inflicting Heat Status and killing hostile Heat sources to starve the Inferno."]},{"title":"Tactical Bind","items":[{"p":"A Tactical Bind is an additional complication that may affect your loadout or gameplay decisions."},"Antimatter Foes: Enemies killed by abilities spawn a hostile Antimatter Drop that tracks you.","Archaic Armor: Enemy armor is greatly increased and cannot be stripped normally. Each hit they take reduces their maximum armor by 1%.","Bruised Shields: Shields can only be restored via melee attacks.","Bolstered Belligerents: All enemies have Overguard equal to 50% of their max health.","Clumsy Munitions: When taking damage, a grenade may be dropped at your feet that explodes after a few seconds.","Cumulonimbus: Being airborne triggers cumulative electrical damage, which dissipates over time once on the ground.","Entanglement: Allies within 4m of slain enemies endure reduced Movement Speed and Parkour Velocity.","Heavy Warfare: Enemies take -90% less damage from non-heavy weapons. Enemies will drop heavy ammo packs and heavy weapon recall time reduced to 5 sec.","Jade Spirits: Jade Wisps haunt the region. If approached, they chase down the player responsible and transform into Jade Light beams.","Kela's Revenge: Missiles strike from above periodically.","Myopic Munitions: Enemies will only take damage if a player is within 15m of them.","Parasitic Light: The squad is given two parasitic lanterns which drain energy of those that carry them. Enemies outside the lanterns' light have massive damage reduction.","Postmortal Surges: Slain enemies explode with Void energy.","Toasty Toes: Grounded movement inflicts Heat damage over time. Airborne movement reduces it.",{"p":"How you choose to counteract these Binds is up to you, as The Icebind does not come with specific loadout restrictions."},{"p":"For feedback on The Icebind game mode, please use the dedicated The Icebind subforum."},{"p":"Image Description: An image of a Riven Splicer, which is a technological device. It is a trapezoidal shape, with three arms jutting off, which point to the center in the shape of a triangle. Each arm appears to be emitting a laser effect, which results in the shape of the Riven icon in between the three arms."}]},{"title":"RIVEN EXPANSION: RIVEN SPLICING","items":[{"p":"The second half of our Riven Expansion arrives: Riven Splicing!"},{"p":"With the use of Riven Splicers, obtained exclusively from The Icebind gamemode, specific traits can be combined to create all-new spliced traits! When selecting a Riven Mod, a new Riven Splicing menu will appear. Opening this menu will display all owned Rivens, detailing which Rivens have valid trait combinations."},{"p":"Select any lit up Riven Mod to see which traits can be spliced!"},{"p":"Spliced traits require a combination of two specific traits to splice together, with different combinations creating different outcomes! Combinations are pre-selected and confirmation is required before applying a spliced trait to your Riven. We have listed all combinations at the bottom of this section, and you can view the combinations possible on a specific Riven with the \"Show All Possible Splices\" option in the Riven Splicing menu. This means you'll always know what spliced trait you're about to receive before you make a decision."},{"p":"If multiple spliced traits are available from a single Riven Mod, a \"Change Selected Trait\" option appears, allowing you to choose which spliced trait you want!"},{"p":"As an example: A Riven Mod with +Heat Damage, +Cold Damage, and +Toxin damage will have 3 spliced traits to choose from: +Blast Damage, +Gas Damage, and +Viral Damage. Which spliced trait goes on the Riven Mod is your choice!"},{"p":"When traits are spliced, the two required traits are consumed, with the spliced trait AND a second random trait taking their place. The random trait is one you may receive from cycling normally, including one just used in making the spliced trait, with one change. If one of the consumed traits was a negative bonus, the random trait will also be a negative; if both consumed traits were positive, it will be a positive. This ensures your Riven keeps the same layout of positive and negative traits it has before combining!"},{"p":"After splicing, the total number of positive and negative traits will no longer change on the Riven Mod, no matter how many times it is cycled after the fact. This can be undone by removing the spliced trait from the Riven."},{"p":"Image: The end-result of a successful Riven Splicing. A Hikou Riven Mod is in the center of the screen, featuring the new +274.1% Weak Point Damage trait, as well as the random -188.3% Damage trait."},{"p":"Once a spliced trait is on your Riven, it's there to stay! It is locked, but is not considered a locked trait - meaning it will not double your Kuva cost. Should you ever decide to remove the trait, the lock can be removed and the spliced trait can be cycled off, allowing a new trait to be spliced on! Utilize both a spliced trait and trait locking to lock two traits at once, making cycling for the last trait or two you want even easier."},{"p":"As an example: Let's say you had a Riven Mod with 3 Positive Traits and 0 Negative traits, and chose a + Viral spliced trait. No matter how many times the Riven is cycled, it retains +Viral Damage and 2 other positive traits, with 0 negative traits. You could even lock one of the other traits, guaranteeing two traits and cycling for the perfect final trait!"},{"p":"Image Description: A view of the Riven Cycle screen displaying a Spliced Hikou Riven Mod. The Mod has two locked traits: one of them is the Spliced Trait (+274.1% Weak Point Damage), and another is a locked trait via the Trait Locking system (in this case, +164.3% Critical Chance). The cost to cycle this Riven is 7,000 Kuva, which is doubled as a result of the locked Critical Chance trait."},{"p":"The full list of spliced traits and which traits are needed to obtain them can be found below."}]},{"title":"Ranged Weapons (Rifle, Shotgun, Pistol, Kitgun, Archgun, Select Companion Rivens)","items":["Weakpoint Damage",{"t":"Damage & Zoom","d":1},{"t":"Damage & Multishot","d":1},"Weakpoint Critical Chance",{"t":"Critical Chance & Zoom","d":1},{"t":"Critical Chance & Multishot","d":1},"Ammo Efficiency",{"t":"Magazine Capacity & Reload Speed","d":1},{"t":"Weapon Recoil & Ammo Maximum","d":1},"Magazine Reload While Holstered",{"t":"Ammo Maximum & Reload Speed","d":1},{"t":"Ammo Maximum & Magazine Capacity","d":1},"Status Damage",{"t":"Damage & Status Chance","d":1}]},{"title":"Melee Weapons (Melee, Zaw, Select Companion Rivens)","items":["Heavy Attack Damage",{"t":"Heavy Attack Efficiency & Additional Combo Count Chance","d":1},"Heavy Attack Windup Speed",{"t":"Heavy Attack Efficiency & Combo Duration","d":1},"Parry Angle",{"t":"Attack Speed & Range","d":1},"Slam Damage",{"t":"Melee Damage & Attack Speed","d":1},"Status Damage",{"t":"Melee Damage & Status Chance","d":1}]},{"title":"All Rivens","items":["Gas Damage",{"t":"Toxin Damage & Heat Damage","d":1},"Corrosive Damage",{"t":"Toxin Damage & Electric Damage","d":1},"Viral Damage",{"t":"Toxin Damage & Cold Damage","d":1},"Radiation Damage",{"t":"Heat Damage & Electric Damage","d":1},"Blast Damage",{"t":"Heat Damage & Cold Damage","d":1},"Magnetic Damage",{"t":"Electric Damage & Cold Damage","d":1},"Damage vs Orokin",{"t":"Damage vs Corpus & Damage vs Grineer","d":1},"Damage vs Techrot",{"t":"Damage vs Corpus & Damage vs Infested","d":1},"Damage vs Scaldra",{"t":"Damage vs Infested & Damage vs Grineer","d":1},{"p":"For feedback on our Riven Splicing system, please use the dedicated Riven Expansion subforum."}]},{"title":"ADDITIONS","items":["Added the following items to Cephalon Melica's Classroom Supplies:",{"t":"Glacial Laboratory Captura Scene","d":1},{"t":"Tethyan Parchment Tatters decorations","d":1},{"t":"Each individual Tatter is available separately, ensuring you can obtain whichever Tatter(s) you want.","d":2},"Added the Complexion B-17 [Legacy] to the Drifter/Operation Complexion menu.",{"t":"This Complexion allows players to access the original implementation of Vitiligo, before its changes with the Iceblade of Narin.","d":1}]},{"title":"CHANGES","items":["Players can now purchase 1 Riven Slot for 20 Platinum (instead of 3 for 60).",{"t":"Previously, players could only purchase Riven Slots in bundles of 3. The 3 Riven Slot bundle has been removed and replaced with the single purchase option.","d":1},{"t":"Following a Nightwave issue last year, affected players received an extra Riven Slot, which meant they were prevented from reaching the Riven Slot cap. Now, players can purchase Riven Slots in whatever number they desire (unless that number exceeds the cap).","d":1},"Excavators and Defense Objectives (ex: Mobile Defense terminals, Defense Targets, etc.) now have a 90% damage reduction against Blitz Eximus shockwave attacks.",{"t":"Defense Objectives now also benefit from shieldgating (like Excavators, which received this change with The Shadowgrapher).","d":1},"Entropic Eximus can no longer spawn as Helions, as their flying behaviour can make them difficult to target with melee weapons.","Reduced the currency cost for Kuva bundles across various Vendors:",{"t":"Acrithis' Wares:","d":1},{"t":"Increased to 10,000 Kuva for 10 Pathos Clamps (was 5,000 for 10).","d":2},{"t":"Exchange Scuttler Husks (Acrithis):","d":1},{"t":"Increased to 14,000 Kuva for 25 Scuttler Husks (was 6,000 for 100).","d":2},{"t":"Also increased purchase limit from one to three per week.","d":2},{"t":"Flare's Memorabilia:","d":1},{"t":"Increased to 14,000 Kuva for 100 Heartstrings (was 6,000 for 100)","d":2},{"t":"Reduced purchase limit from seven to three times per week.","d":2},{"t":"Nightcap's Wares:","d":1},{"t":"Increased to 14,000 Kuva for 75 Fergolyte (was 7,000 for 75)","d":2},{"t":"Reduced purchase limit from six to three times per week.","d":2},{"t":"Hunhow's Keepsakes:","d":1},{"t":"Increased to 17,000 Kuva for 35 of both Emerald & Crimson Talents (was 7,000 for 35).","d":2},{"t":"Reduced purchase limit from seven to three per week.","d":2},"The Events tab in the Navigation menu now sorts recurring events by most recently started.","Reduced the amount of space the Thermia Fractures event takes up in the World State Window on the Navigation console.","Updated the Entropic Kuva's resource description to specify it drops from Entropic Eximus.","Added the Shedu Day of the Dead Skin to the Nightwave Cred Offerings rotation."]},{"title":"Performance and Optimizations","items":["Improved performance issues related to Oberon's Smite.","Improved performance issues related to Frost's Avalanche.","Fixed minor performance issues related to Last Gasp.","Optimized texture streaming memory usage."]},{"title":"TOP FIXES","items":["Metal Shader Fixes:",{"t":"Improvements and fixes towards our Metal Shaders are ongoing. For more information on the limitations related to updating Metal Shaders, please read our official post.","d":1},{"t":"Fixed metallics appearing plasticy for players with High Shader Quality toggled off.","d":1},{"t":"Fixes towards certain Warframe Skins appearing light gray when tinted black following our High Shader Quality changes.","d":1},"Fixed Oberon's Renewal no longer slowing bleedout timers.","Fixed not being able to use Loki's Switch Teleport on Hacked Drones in the Plains of Eidolon.","Fixed Balor Fomorian events not being scheduled properly, resulting in repeated Razorback Armadas.",{"t":"The pending Balor Fomorian will begin once the current Razorback Armada has concluded.","d":1},"Fixed Grendel's Gastropareisis causing Azima's alternate fire to stack Secondary Enervate infinitely.","Fixed the \"Hide Owned\" toggle hiding different items each time it was toggled on and off.","Fixed being unable to upgrade Companions via the Navigation Loadout bar if Orion is set as the Primary Son.","Fixed Shotgun Rivens being listed as \"Shotgun\" instead of the actual weapon when chatlinked.","Tentative fix towards cases of controller inputs not functioning correctly when using Steam Input."]},{"title":"Fixes","items":["Fixed the Aksondol and Nunchasa missing blueprint location descriptions in the Market.","Fixed moving very slowly resulting in Mining Deposits not updating properly when using Oxylus' Scan Matter precept.","Fixed the Caliban Scion Helmet's metallics and base color not matching base Caliban.","Fixed a duplicate Catenach appearing when using Uriel in Duviri.","Fixed the Operator being able to attempt to pull out the Iceblade of Narin.","Fixed camera flickering if a movement input is pressed when attempting to pull Narin's Iceblade free.","Fixed players in Yuvan Peak blocking the screen when attempting to pull out Narin's Iceblade.","Fixed Tauron Strike animations being broken if cast while Narin's Nuranarmin is active.","Fixed a texture issue on Yuvan Peak.","Fixed Uriel's Demons being doubled after using Transference.","Fixed duplicates of Uriel's Demons appearing in the Höllvania Central Mall Backrooms Scene if Uriel is also equipped on the Loadout Display.","Fixed having two full-body Sigils applied resulting in the Sigils' effects not applying to the head.","Fixed the Mission Tutorial Transmission toggle hiding introduction transmissions for the Temporal and Deep Archimedea missions.","Fixed Gemini Skin faces becoming distorted when swapping in and out of Duviri Navigation in the Navigation menu.","Fixed an unnecessary \"Mission 1\" appearing over the Hallowed Nightmares alert in the Navigation menu.","Fixed incorrect capitalization for Voidshell Materials in the Operator/Drifter customization screen.","Fixed a rare case of Inaros being revived with function loss if he died at the start of casting Sandstorm with an item (ex: power cell) in his hands.","Fixed a sound crash."]},{"title":"Script Error Fixes","items":[{"p":"Script errors mean that something went wrong when the game client was executing a script, which can have various outcomes. Usually it means the related content didn't function properly under specific circumstances - often we don't actually know what the error outcome was, so we list it as a Script Error fix to indicate it was addressing an unintended behaviour."},"Fixed a script error when attempting to destroy an Entropic Eximus' shield.","Fixed a script error related to Narin's Nuranarim.","Fixed a script error related to Nokko's Sporespring projectiles.","Fixed a script error related to the Unairu Tauron Strike.","Fixed a script error related to Nightwave Act popups when transitioning out of missions on the Zariman Ten Zero.","Fixed a script error related to the Panic Call Peely Pix in Temporal Archimedea.","Fixed a script error related to Narin's passive.","Fixed a script error related to Baruuk's Serene Storm.","Fixed a script error related to the Confront Kullervo objective in Duviri.","Fixed a script error related to Khora's Venari.","Fixed a script related to Arcane effects that trigger \"on Critical Hit\".","Fixed a script error related to Yareli's Sea Snares.",{"p":"For a list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1523875-known-issues-iceblade-of-narin/"}]}]}]},{"slug":"44-0-3","version":"44.0.3","kind":"hotfix","title":"Iceblade of Narin: Hotfix 44.0.3","url":"https://www.warframe.com/en/patch-notes/pc/44-0-3","forum":"https://forums.warframe.com/topic/1526292-iceblade-of-narin-hotfix-4403/","date":null,"dateSource":null,"tldr":"Narin. 30 fixes, 12 other changes.","fixes":30,"changes":12,"highlights":["Narin"],"mentions":[{"name":"Narin","kind":"Warframe","n":12},{"name":"Jade","kind":"Warframe","n":2},{"name":"Valkyr","kind":"Warframe","n":2},{"name":"Ash","kind":"Warframe","n":1},{"name":"Cyte-09","kind":"Warframe","n":1},{"name":"Grendel","kind":"Warframe","n":1},{"name":"Harrow","kind":"Warframe","n":1},{"name":"Hildryn","kind":"Warframe","n":1},{"name":"Koumei","kind":"Warframe","n":1},{"name":"Oraxia","kind":"Warframe","n":1},{"name":"Sevagoth","kind":"Warframe","n":1},{"name":"Sirius & Orion","kind":"Warframe","n":1},{"name":"Styanax Prime","kind":"Warframe","n":1},{"name":"Temple","kind":"Warframe","n":1}],"parts":[{"title":"Iceblade of Narin: Hotfix 44.0.3","sections":[{"title":"Narin Changes & Fixes","items":["Increased the duration of Cold Ammo Packs dropped by Narin from 10s to 15s.","Nurinarim Mark Changes & Fixes:",{"t":"Narin can now fire projectiles during Nurinarim at targets regardless of whether they are Marked or not.","d":1},{"t":"Attacks on Marked targets cost no Ice and do increased damage.","d":2},{"t":"Increased Nurinarim's duration from 15s to 20s.","d":1},{"t":"Narin can now use Transference during Nurinarim.","d":1},{"t":"Parkour Velocity and Dodge stats now apply to Narin during Nurinarim.","d":1},{"t":"Mark Changes:","d":1},{"t":"The initial Mark is now created immediately upon Nurinarim activation instead of having a delay.","d":2},{"t":"Reduced the time between Marks being generated.","d":2},{"t":"Increased the likelihood that targets closer to where you are currently aiming will be Marked during Nurinarim.","d":2},{"t":"Marks are now placed based on the target's height to improve readability.","d":2},{"t":"Added a pulse VFX to Narin's reticle when successfully hitting a Marked target during Nurinarim.","d":2},{"t":"Fixed Nurinarim's projectiles not targeting targets beyond 50m even if the target was already Marked.","d":1},{"t":"Fixed Nurinarim not dealing damage to The Severed Warden's arms.","d":1},{"t":"Fixed Nurinarim being able to target neutral units, like Conservation targets.","d":1},"Fixed Client Narins not gaining Ice when damaging enemies with Hakchum."]},{"title":"Changes","items":["Reduced the Blitz Eximus' shockwave attack's base damage from 250 to 100.",{"t":"This attack was a common mission killer at higher levels if it targeted an objective like a Defense Target or Mobile Defense Terminal. Now their attacks should be less likely to one-shot a defensible objective.","d":1},"The Iceblade of Narin blessing's VFX now only appears when players are in mission with a Melee weapon equipped.","Removed the ability for Entropic Eximus to spawn as Nullifier units.","Reverted the Research Point changes introduced to Archimedea missions with the Iceblade of Narin.",{"t":"Using a Warframe that matches those in the Individual Parameters rewards 1 Research Point once more.","d":1},{"t":"Restored the Research Point reward track to provide the Legendary Reward at 34 Research Points, and Vosfor or Pix Chips at 37 Research Points.","d":1},{"t":"This change had a mixed reception with players, and we ultimately decided to revert it so players didn't feel \"forced\" to match their Warframe due to the increased Research Points they offered.","d":1},{"t":"Note: the other changes to Archimedea missions introduced with Iceblade of Narin remain untouched.","d":1},"Players affected by the No Pets Allowed Personal Modifier in Archimedea missions now have an increased innate Vacuum range.","The \"Hide Owned\" toggle now hides Blueprints of crafted cosmetics in the Nightwave Cred Offerings since players can only own one copy of a cosmetic.","Removed muffled SFX when players are dead and spectating squadmates.","Restored Entropic Eximus bubble hit SFX as it no longer triggers squad-wide.","Reduced Grendel's Nourish SFX distance for squadmates, and slightly reduced its volume.","Rescue Target downed transmissions are no longer affected by the Mission Tutorial Transmissions toggle."]},{"title":"Top Fixes","items":["Fixes towards players losing function when swapping between Sirius & Orion.",{"t":"There were quite a few different cases causing this, and we hope to have addressed as many as we could find. We'll be keeping an eye out for reports if this issue persists after this hotfix!","d":1},"Fixed Ash Teleporting to Join the Fray resulting in future casts of Teleport being broken.","Fixed being unable to access Operator or Focus menus on Yuvan Peak.","Fixed the Energy tint channel not applying to the Opula Armor Set.","Fixed Hildryn's Balefire being able to bypass Entropic Eximus bubbles.","Fixed Valkyr's Rage VFX flashing on-screen every time a player Transferences back to Valkyr.","Fixed various offset issues on Styanax Prime.","Fixed Sevagoth's Shadow missing in the Arsenal when attempting to upgrade or customize him."]},{"title":"Fixes","items":["Fixed Temple's Exalted Solo breaking their ability to Wall Jump/Latch.","Fixed the Jade Aureolt Helmet not opening when toggling on Glory in the Arsenal.","Fixed the metallic elements on the Harrow Profitas Skin no longer appearing metallic.","Fixed overlapping Arcane and Exilus Slots when linking a Mod Config for an Exalted Primary or Secondary weapon.","Fixed various cases of Entropic Kuva pickup SFX not playing.","Fixed additional edge cases of players being able to Emote (and therefore fall out of the map) when attempting to pull Narin's Iceblade on Yuvan Peak.","Fixed Cephalon Melica playing a transmission about Narin's Iceblade now that players can successfully pull it from the ice.","Fixed suggested Polarity marker bleeding across Mod categories in the Railjack Plexus.","Fixed the Pause Menu dissolving if open while going through a Sanctuary Onslaught portal.","Fixed Mods popping into view if they are partially offscreen while scrolling through Mods in the Mod Bench.","Fixed performance issues caused by chatlinking a Riven if a chat filter is applied.","Fixed a filepath in the Headcracker Honoria description."]},{"title":"Script Errors","items":[{"p":"Script errors mean that something went wrong when the game client was executing a script, which can have various outcomes. Usually it means the related content didn't function properly under specific circumstances!"},"Fixed a script error in The Descendia.","Fixed a script error related to Narin's Neote.","Fixed a rare script error related to Duviri Decree generation.","Fixed a script error related to Koumei's Omamori.","Fixed a script error related to Oraxia's Scuttlers.","Fixed a script error related to Cephalon Simaris' ability restrictions in Sanctuary Onslaught.","Fixes towards clipping issues with Narin's skirt during animations.","Fixed a script error related to Sirius' Jade Stars.","Fixed a script error related to Cyte-09's Resupply.",{"p":"For a list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1523875-known-issues-iceblade-of-narin/"}]}]}]},{"slug":"44-0-2","version":"44.0.2","kind":"hotfix","title":"Iceblade of Narin: Hotfix 44.0.2","url":"https://www.warframe.com/en/patch-notes/pc/44-0-2","forum":"https://forums.warframe.com/topic/1525835-iceblade-of-narin-hotfix-4402/","date":null,"dateSource":null,"tldr":"32 fixes, 4 other changes.","fixes":32,"changes":4,"highlights":[],"mentions":[{"name":"Narin","kind":"Warframe","n":7},{"name":"Mirage","kind":"Warframe","n":3},{"name":"Banshee","kind":"Warframe","n":2},{"name":"Citrine Prime","kind":"Warframe","n":2},{"name":"Zymos","kind":"Weapon","n":2},{"name":"Aksondol","kind":"Weapon","n":1},{"name":"Atomos","kind":"Weapon","n":1},{"name":"Citrine","kind":"Warframe","n":1},{"name":"Dual Toxocyst","kind":"Weapon","n":1},{"name":"Galvanized Scope","kind":"Mod","n":1},{"name":"Gara","kind":"Warframe","n":1},{"name":"Latron","kind":"Weapon","n":1},{"name":"Okina","kind":"Weapon","n":1},{"name":"Sharpshooter","kind":"Mod","n":1},{"name":"Sirius & Orion","kind":"Warframe","n":1}],"parts":[{"title":"Iceblade of Narin: Hotfix 44.0.2","sections":[{"title":"Additions","items":["Citrine Prime's Adornments can now be unequipped as a new Auxiliary Attachment.",{"t":"With Iceblade of Narin's release, these pieces would be removed if Citrine Prime equipped a TennoGen or the Aphrodita helmet. We fixed that bug, but we have made their functionality permanent with this new Auxiliary!","d":1},"Added various Day of the Dead cosmetics from the Nightwave: Dreams of the Dead series to the Nightwave Offerings. These are permanent additions that will rotate in as the store refreshes each week!",{"t":"Note: We will also be adding these items to Daughter's Naberus wares when that event launches in October.","d":1},{"t":"Okina Day of the Dead Skin","d":1},{"t":"Atomos Day of the Dead Skin","d":1},{"t":"Taxon Day of the Dead Skin","d":1},{"t":"Skaut Day of the Dead Skin","d":1},{"t":"Kayota Day of the Dead Mask","d":1},{"t":"Monarcierro Day of the Dead Syandana","d":1},{"t":"Calaverita Sentinel Mask","d":1},{"t":"Calaverita Sentinel Tail","d":1},{"t":"Calaverita Sentinel Wing","d":1},{"t":"Nora Night Catrina Glyph","d":1}]},{"title":"Changes","items":["Shotgun Rivens can now roll Zoom stats in anticipation of the Riven Splicer system (which we hope to release soon).",{"t":"The Zoom stat is required to create specific Spliced Traits, as outlined in our Riven Splicer Dev Workshop.","d":1},"Adjusted the Deimos Genetrix's SFX to be quieter and to play at a shorter distance."]},{"title":"Top Fixes","items":["Fixed the Entropic Eximus' damage reduction being applied twice.","Fixed Entropic Eximus spawning in The Descendia missions.",{"t":"These specific Eximus only spawn in the Zariman for narrative reasons!","d":1},{"t":"Known Issue: Entropic Eximus can spawn in Sanctuary Onslaught.","d":1},"Fixed allied barriers (like Gara's Mass Vitrify) blocking line of sight checks for Narin's Neote.","Fixed the Galvanized Scope's description incorrectly stating \"On Weak Point Hit\" (instead of the intended \"On Weak Point Kill\").","More fixes towards golden decorations being too yellow.",{"t":"With our metal shader improvements in Iceblade of Narin we fixed the issue of \"gray cast\" on metals, which also applied to decorations and caused them to appear as a very saturated yellow instead of the familiar gold tone. The above fixes aim to return the gold closer to what it was before, while also taking advantage of the wider range of colors we now have at our disposal.","d":1},"Fixed Rivens with duplicate traits that were the result of a Riven Cycling bug immediately following Iceblade of Narin's release.",{"t":"Removed negatives from Rivens that had both a positive and negative value of the same trait. (ex: +80% Reload Speed and -17% Reload Speed)","d":1},{"t":"Any remaining Rivens with numerous negative traits have had the extra negative traits removed.","d":1},{"t":"Kuva Refund Script: Players who cycled Rivens and were presented with a broken option will have their Kuva refunded.","d":1},{"t":"Update 3:30pm ET - the script is complete, affected players should see their Kuva refunded!","d":2},"Fixed Narin and Uriel's passives granting permanent elemental buffs if applied without a weapon equipped."]},{"title":"Fixes","items":["Fixed Zymos' unique trait not triggering consistently.",{"t":"Known Issue: The seeking spore projectiles from the Zymos' unique trait are invisible.","d":1},"Fixed the Dual Toxocyst Incarnon's Neurotoxin evolution not adding Toxin damage.","Fixed Entropic Eximus killed by Mirage's Hall of Mirrors not dropping Entropic Kuva.",{"t":"This also fixes Eximus not dropping Riven Slivers if killed by Mirage's clones.","d":1},"Fixed the Archimedea bonus for Ability Strength applying Ability Duration instead.","Fixed various offsets for the Opula Shoulder Armor.","Fixed offsets for the Spinele Prime Accessories on the Drifter to match the Operator.","Fixed cases of the Kerulyst Sentinel Skin's attachments becoming detached when certain Sentinels perform attacks.","Fixed Voruna's growling SFX remaining after exiting Ulfrun's Descent, causing it to stack loudly after multiple casts.","Fixed placeholder text in the Sharpshooter Mod description.","Fixed an issue when attempting to use a Zipline.","Fixed a map hole in the mountain pass in The War Within quest.","Fixed chat being hidden when viewing a Profile.","Fixed being able to perform an Emote while pulling out Narin's Iceblade, causing players to fall through the map.","Fixed a rare crash when starting Zariman Ten Zero missions from the Chrysalith, and a squadmate attempts to enter the Dormizone elevator.","Fixed a rare in-game chat crash after toggling the Cross Platform Play setting."]},{"title":"Performance Fixes","items":["Fixed performance issues caused by the Latron's Incarnon Form projectiles if modded for a high fire rate while using Mirage's Hall of Mirrors.","Fixed performance issues caused by Banshee's Gaseous Quake.","Fixed performance issues caused by Aksondol."]},{"title":"Script Errors Fixes","items":[{"p":"Script errors mean that something went wrong when the game client was executing a script, which can have various outcomes. Usually it means the related content didn't function properly under specific circumstances!"},"Fixed script errors related to Sirius & Orion's Passive.","Fixed a script error related to Mining Lasers.","Fixed a script error related to Narin's Neote.","Fixed a script error related to Zenurik's Tauron Strike ability.","Fixed a script error related to Citrine's Crystalize.","Fixed a script error related to Banshee's Sound Quake.","Fixed a script error when chatlinking Mods.",{"p":"For list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1523875-known-issues-iceblade-of-narin/"}]}]}]},{"slug":"44-0-1","version":"44.0.1","kind":"hotfix","title":"Iceblade of Narin: Hotfix 44.0.1","url":"https://www.warframe.com/en/patch-notes/pc/44-0-1","forum":"https://forums.warframe.com/topic/1524660-iceblade-of-narin-hotfix-4401/","date":"2026-09-24","dateSource":"patch notes","tldr":"Some Clarifications from Iceblade of Narin Patch Notes; Archimedea Personal Modifier Groups; Entropic Eximus Clarifications; Necramech Slot Refund Script. 44 fixes, 34 other changes.","fixes":44,"changes":34,"highlights":["Some Clarifications from Iceblade of Narin Patch Notes","Archimedea Personal Modifier Groups","Entropic Eximus Clarifications","Necramech Slot Refund Script"],"mentions":[{"name":"Narin","kind":"Warframe","n":19},{"name":"Citrine Prime","kind":"Warframe","n":3},{"name":"Gyre Prime","kind":"Warframe","n":3},{"name":"Banshee","kind":"Warframe","n":2},{"name":"Gyre","kind":"Warframe","n":2},{"name":"Hydroid","kind":"Warframe","n":2},{"name":"Hydroid Prime","kind":"Warframe","n":2},{"name":"Aksondol","kind":"Weapon","n":1},{"name":"Dorrclave","kind":"Weapon","n":1},{"name":"Ember","kind":"Warframe","n":1},{"name":"Frost","kind":"Warframe","n":1},{"name":"Glaive","kind":"Weapon","n":1},{"name":"Ivara","kind":"Warframe","n":1},{"name":"Kullervo","kind":"Warframe","n":1},{"name":"Mirage","kind":"Warframe","n":1}],"parts":[{"title":"Iceblade of Narin: Hotfix 44.0.1","sections":[{"title":"","items":[{"p":"Hi Tenno!"},{"p":"It's been just over 24 hours since Iceblade of Narin launched, and we firstly want to thank you all for jumping into the update, and sharing your thoughts and fast bug reports with us!"},{"p":"Seeing you come together as a community and piece together the clues to fulfill the prophecy was really special, and we recognize that we have many learnings from it."},{"p":"The Iceblade of Narin update is a continuation of our attempts to try new things with Warframe. Not every Warframe will come with a Quest, therefore we must adapt. It's imperative that we experiment and get your feedback to educate us as we move forward to Tau and beyond. Warframe is a game built with our Community, and that Community ebbs and flows with differing desires and playstyles. We will continue to try new things in our updates, and we thank you again for helping us to shape this world together."},{"p":"You will see in this Hotfix that we are bringing deeper clarification to some of the hot topic changes, alongside changes/fixes to address critical feedback <3"}]},{"title":"Some Clarifications from Iceblade of Narin Patch Notes","items":[]},{"title":"Archimedea Personal Modifier Groups","items":[{"p":"This is a new system in Personal Modifier generation for Temporal and Deep Archimedea that was missed in our original patch notes. There are some weeks that can almost feel excessively punishing depending on which Personal Modifiers you receive - to avoid cases of this happening in the future, Personal Modifiers have been separated into four different Groups."},{"p":"Each week on reset, one Modifier from each Group will be randomly selected to help avoid overly difficult combinations. Due to Archimedea Modifiers being selected at the beginning of the week and Iceblade of Narin launching on a Wednesday, this is not currently live. That said, you will see the first installment of this updated system apply to Personal Modifiers after this upcoming weekly reset: September 28, 2026 at Midnight UTC."}]},{"title":"Group One","items":["Ability Overload","Dropped Guard","Dull Blades","Framecurse Syndrome","Hypersensitive","Knifestep Syndrome","Low Yield","Secondary Wounds","Undersupplied"]},{"title":"Group Two","items":["Abbreviated Abilities","Channeled Greed","Constricted","Energy Exhaustion","Powerless","Shortened Reach"]},{"title":"Group Three","items":["Ammo Deficit","Gear Embargo","No Pets Allowed","Transference Distortion"]},{"title":"Group Four","items":["Anemic Shields","Fractured Armor","Infected Wounds","Lethargic Shields","Permanent Injury","Untreatable",{"p":"If you have additional feedback about our Archimedea changes, please use the dedicated QOL Additions Feedback subforum."}]},{"title":"Entropic Eximus Clarifications","items":[{"p":"With the introduction of our new Entropic Eximus units, we kept our initial patch note description intentionally vague to encourage players to discover the best ways to take them down. An unintended result was player confusion about some of the mechanics and we apologize for any frustration this decision caused."},{"p":"To help you in your hunt for Entropic Eximus (and their Entropic Kuva), we're offering more information on how these enemies work so you can understand a) how to kill them and b) what behaviours are intended. We are also adding this information to the original Update Notes."},{"p":"Entropic Eximus have a resistance to non-melee attacks, forcing you to get in close and use your melee weapon. Breaking the bubble will enable abilities to target the Eximus, but will not change the Eximus's damage resistance."},"Damage from non-melee sources is reduced by 90%.",{"t":"For Operators, damage is instead reduced by 75%.","d":1},"Companions do not target Entropic Eximus",{"p":"Entropic Eximus bubbles prevent projectiles from entering, and prevent Warframe abilities from dealing damage to the Entropic Eximus, from both inside and outside the bubble! The bubble can be broken two ways:"},"Dealing melee damage with the Iceblade of Narin buff from Neote on Yuvan Peak will break the bubble if either the bubble or the Entropic Eximus is struck.","Tauron strikes will break the bubble upon contact.",{"p":"We hope this clears up confusion around how to best approach taking on Entropic Eximus. If you're hunting them down, don't forget to check Void Angels for a few guaranteed spawns! To provide us feedback on Entropic Eximus, please head over to our Update 44 Zariman Updates Feedback Forum."}]},{"title":"Necramech Slot Refund Script","items":[{"p":"As mentioned in the Iceblade of Narin update notes, we have removed the need for Necramech Slots. The script refunding purchases Necramech Slots has completed, and players should see any Platinum spent on these slots returned to them via inbox message!"}]},{"title":"Changes","items":["Doubled the weighting of Narin's Blueprint in Zariman Exterminate and Mobile Defense missions following community feedback.",{"t":"Exterminate and Mobile Defense missions are usually not the source of Warframe Blueprints, so we have increased the drop rate to be more forgiving.","d":1},"Narin can now walk on water during Nurinarim!","Updated Hydroid and Hydroid Prime's stats to properly swap Health and Shield values in order to help him make the most out of the armor gained from Plunder.",{"t":"Iceblade of Narin accidentally swapped his Armor and Shield values, instead of the Health and Shield values as suggested by the community.","d":1},{"t":"Hydroid Prime:","d":1},{"t":"Health: 650","d":2},{"t":"Shields: 370","d":2},{"t":"Armor: 290","d":2},{"t":"Hydroid:","d":1},{"t":"Health: 365","d":2},{"t":"Shields: 270","d":2},{"t":"Armor: 240","d":2},"Citrine Prime's shoulder details now dissolve when aiming down sights.","Removed the hit SFX on Entropic Eximus shields as it was being played squad-wide. This is a temporary change until we can fix the issue."]},{"title":"Top Fixes","items":["Fixed an elevator exploit resulting in ever-increasing Eximus spawn counts in Zariman Ten Zero missions.",{"t":"UPDATE - September 25 at 3pm ET: Players who earned extreme amounts of Entropic Kuva via this exploit have had the exploited Entropic Kuva removed from their account. Knowing that some players may have received elevated Entropic Kuva due to normal play habits, we have only removed values that could be obtained through extremely intentional exploiting.","d":1},"Fixed being unable to destroy Corrupted Nullifier bubbles by shooting the bubble itself.","Fixed longer transmission SFX being cut off early.","Fixed Citrine Prime's shoulder armor offsets being upside down.","Fixed the Mausolon, Morgha, and Cortege's Alt Fires not charging.","Fixed the Dorrclave's unique trait not functioning properly.","Fixed certain metals appearing flat when tinted black following our Metal Shader changes (notably on the Frost Harka and Kullervo Apostate skins).",{"t":"This change also restored the ability to create pitch black materials on Voidshell skins.","d":1},{"t":"Also fixed some cases of golden Decorations being too yellow following our metal shader changes. Given the variety of decorations in the game, many still remain affected, so we'll be keeping an eye out for reports as we continue to work to address this issue.","d":1},"Fixed the Neo K10 Relic having the Gyre Systems instead of the Gyre Prime Systems.",{"t":"Replacement Script: We'll be replacing all claimed Gyre Systems with the correct Gyre Prime Systems via a script later this week. We'll update this thread with more information once it is complete.","d":1},{"t":"Update - September 25 at 3pm ET: Affected players should see a Gyre Prime Systems blueprint added to their inventories.","d":2},"Fixed cases of players getting both positive and negative values of all rolled Traits when cycling an unlocked Riven.",{"t":"Also fixed rare cases of players being able to roll a positive and negative value of the same trait.","d":1},{"t":"Riven Mod Fixing: This was patched live yesterday (September 23) at around 12pm ET, but some players may have chosen the Riven with the broken stats. For those Riven Mods with a) multiple negative traits or b) a trait that has both a positive and a negative, the incorrect negative traits will be removed in a future hotfix.","d":1},{"t":"Kuva Refund Script: players who cycled a Riven and were presented a broken Riven will have their Kuva refunded via a script, regardless if the broken Riven was chosen. We will update this thread with more information once it is run!","d":1},"Fixed Narin being able to equip a Heavy Weapon while Nurinarim is active."]},{"title":"Performance Issues","items":["Fixed Clients experiencing a large spotload after travelling from the Yuvan Peak to the Chrysalith.","Fixed performance issues related to Narin.","Fixed performance issues sometimes leading to a crash in Yuvan Peak when someone attempts to pull Narin's Iceblade.","Fixed performance issues caused by Aksondol's reload when using Mirage with Hall of Mirrors active."]},{"title":"Mission and Equipment Fixes","items":["Fixed the Mobile Defense terminal having a misaligned interaction prompt if it spawned in the new Melica's Laboratory tile in the Zariman Ten Zero.","Fixed Ivara being able to control her Primary Weapon like a Glaive due to an interaction between Navigator and Wrathful Advance.","Fixed missing vortex SFX in the Ryoku fight in Scoria's Angel missions.","Fixed the cold mist from Aksonol's reload incorrectly triggering Secondary Enervate."]},{"title":"Cosmetic Fixes","items":["Fixes towards GI lighting over-emphasizing Operator/Drifter pores.","Fixed Citrine Prime losing her shoulder piece, skirt, and other prime attachments after equipping the Aphrodita Helmet or a TennoGen helmet.",{"t":"While we are fixing this bug, we will be turning these attachments into an Auxiliary attachment in a future update.","d":1},"Fixed tint colors not applying to the crystal reflections on the Spinele Prime Operator/Drifter accessories.","Fixes towards cloth physics issues on Narin's skirt.","Fixed the Gothica Signa's cloth not being tattered."]},{"title":"Miscellaneous Fixes","items":["Fixed attempting to pull out Narin's Iceblade while in motion resulting in the animation being misaligned.",{"t":"Also fixed missing SFX when attempting to pull out Narin's Iceblade.","d":1},{"t":"Also fixed cases of the VFX being misaligned.","d":1},"Fixed a broken icon and filepath appearing in Cephalon Melica's vendor screen on the Yuvan Peak.","Fixed cases of emoting next to Narin's Iceblade causing players to fall through the map.","Fixed gifting multiple Relic Packs resulting in each pack containing the same Relics.",{"t":"If you were affected by this issue (as the gifter), we ask that you submit a support ticket for further assistance.","d":1},"Fixed various map holes and texture seams in The War Within map.","Fixed minor skybox lighting issues in the remastered The War Within map.","Fixed missing SFX when unlocking a Riven Trait and made various minor polish changes to this screen.","Fixed a player dying after an attempted but failed revive causing their death message to incorrectly state that they were revived.","Fixed missing information in Narin's market blueprint description.","Fixed minor polish issues in Narin's diorama.","Fixed additional cases of Warframes that were released prior to Oraxia not using colorful status icons for their stats in menus.","Fixed a minor typo on the update screen that Gary was unfairly blamed for. Sorry Gary!","Fixed a minor grammatical error in the Iceblade Blessing description.","Fixed cases text not being localized or placeholder descriptions being used on non-English Clients, notably in Narin's market blueprint description and in Melica's Vendor screen.","Fixed various script errors related to Narin's Neote, Hakchum, and Naraemagi.","Fixed a script error caused by Commandeered Ember's Inferno ability in The Perita Rebellion missions.","Fixed a script error related to Banshee's Sound Quake.","Fixed a script error related to Banshee's Sonic Boom.","Fixed a script error related to Temporal Archimedea modifiers.","Fixed an audio crash happening during sound driver reset.","Fixed a crash that could occur when returning from alt tabbing after making a purchase on Steam.",{"p":"For list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1523875-known-issues-iceblade-of-narin/"}]}]}]},{"slug":"44-0-0","version":"44.0.0","kind":"update","title":"Update 44: Iceblade of Narin","url":"https://www.warframe.com/en/patch-notes/pc/44-0-0","forum":"https://forums.warframe.com/topic/1523956-update-44-iceblade-of-narin/","date":"2026-09-23","dateSource":"patch notes","tldr":"New Earth Relay: Yuvan's Peak; Zariman Updates; New Warframe: Narin; New Bow: Nunchasa. 266 fixes, 188 other changes.","fixes":266,"changes":188,"highlights":["New Earth Relay: Yuvan's Peak","Zariman Updates","New Warframe: Narin","New Bow: Nunchasa","New Pistol: Aksondol","Citrine Prime Access","Riven Expansion: Trait Locking (Live) & Riven Splicing (Coming Soon)","Trait Locking (Live)","Riven Splicing (Launching at a Later Date with Glacial Defiance)","New Warframe Augment Mods"],"mentions":[{"name":"Narin","kind":"Warframe","n":53},{"name":"Banshee","kind":"Warframe","n":33},{"name":"Sirius & Orion","kind":"Warframe","n":15},{"name":"Citrine Prime","kind":"Warframe","n":14},{"name":"Jade","kind":"Warframe","n":12},{"name":"Citrine","kind":"Warframe","n":9},{"name":"Grendel","kind":"Warframe","n":7},{"name":"Qorvex","kind":"Warframe","n":7},{"name":"Frost","kind":"Warframe","n":6},{"name":"Aksondol","kind":"Weapon","n":5},{"name":"Sevagoth","kind":"Warframe","n":5},{"name":"Baruuk","kind":"Warframe","n":4},{"name":"Corufell","kind":"Weapon","n":4},{"name":"Excalibur","kind":"Warframe","n":4},{"name":"Hydroid","kind":"Warframe","n":4}],"parts":[{"title":"Update 44: Iceblade of Narin","sections":[{"title":"","items":[{"p":"Image Description: The Iceblade of Narin art features Narin in motion looking towards the frozen monolith at the Yuvan Peak."},{"p":"At the summit of a familiar peak on Earth - the place you first mastered your Void powers - a mysterious frozen monument has taken shape, prompting strange happenings aboard the Zariman and a new threat from the Man in the Wall…"},{"p":"Return to where you were presented with the decision to destroy, control or consume a powerful elixir: Yuvan's Peak! Visit the dark side of Earth and enter a unique hub. At this spectacular mountain summit, you'll find Narin's Crest and Neote, Narin's legendary sword, encased firmly in the ice. Marvel at its wonder and attempt to pull Narin's Iceblade free."},{"p":"Cephalon Melica has also been summoned to Yuvan's Peak, but unfortunately not for a fun field trip. Entropy threatens the Zariman, and Narin's influence on the Peak is key to stopping its spread. Collect Entropic Kuva from Entropic Eximus found on the Zariman, and exchange it with Melica to contain it. In doing so, you'll receive items from her wares, including Narin's blueprints!"},{"p":"Our 66th Warframe, Narin, also descends in swirling eddies in this update! Her blade keen and deadly as an icy wind. She wields ice to heal and defend as deftly as her swift rapier strikes. Trade Entropic Kuva to Cephalon Melica for Narin's blueprints, as well as the blueprints to craft her signature weapons' Nunchasa and Aksondol."},{"p":"The crystalline citadel ascends, Citrine Prime Access is here! Move through the battlefield with refined radiance with Citrine Prime, Steflos Prime, Corufell Prime and her Prime Accessories. Purchase Citrine Prime Access Packs or earn this brilliant gem of a Prime Warframe and her weapons by cracking Relics."},{"p":"Two new Deluxe Skin Collections are here to make the ground shake! Qorvex Basilica and Banshee Threnodia arrive with a collection of cosmetics fit for those looking to strike terror in the most fashionable of ways. Speaking of Banshee, our sound Warframe, has received a full rework to make her a truly lethal presence not only heard but felt on the battlefield."},{"p":"Iceblade of Narin is packed with so much more! Including Riven Trait Locking, new Warframe Augments for Oraxia, Uriel, Frost, and Grendel, new Atragraph Mods for Banshee and Baruuk, new TennoGen, improved hair shaders and metal tinting, Archimedea Parameter & Reward track QOL and so much more!"},{"p":"Image Description: Banshee poses with glowing arms outstretched. To her right from top to bottom are the Warframe logo, Free Banshee Login Reward, and the dates of the promotion of September 23 to October 7."}]},{"title":"Free Login Rewards","items":[{"p":"Log into Warframe from Sept 23rd @ 11:30 AM ET to Oct 7th @ 11:59 PM ET to claim Banshee and one built Forma* for FREE and experience her new Ability Rework for yourself! Learn more about her rework in the dedicated section."},{"p":"*Once the Free Banshee inbox expires, you can still claim the Forma (if you had not already received the Banshee inbox) on login until December 31, 2026."}]},{"title":"Upcoming Content & Events","items":[{"p":"Iceblade of Narin is followed by the listed content below coming in the near future:"},{"p":"Image Description: Six Warframes stand poised for battle within a frosty cave with the Warframe logo and Glacial Defiance: New 6 Player Missions in the foreground. From left to right we can see: Wisp, Rhino, Volt, Excalibur, Mesa, and Mag."},"Glacial Defiance (New 6-Player game mode) - Releasing sometime before or on October 15th",{"t":"To learn more about the Glacial Defiance launch timing and the reasons behind the staggered release, please read our official PSA here: https://forums.warframe.com/topic/1523427-psa-glacial-defiance-release-window/","d":1},"Riven Splicing - Coming with Glacial Defiance launch",{"t":"The item required to perform Riven Splicing, the Riven Splicer, is rewarded from Glacial Defiance. So once the gamemode launches, Splicing will also become available!","d":1},{"p":"Image Description: Epoch Operation: Taubound art that features gold lettering for Taubound and the Warframe logo against a dark backdrop of space."},"Epoch Operation: Taubound - Begins October 15th!",{"t":"Arturos and Zioa have lain dormant long enough: the time to assume control of your Vessel is almost at hand. With new worlds and possibilities beyond the Origin System closer than ever, your window to prepare for the journey to Tau begins now, ahead of a never-before-seen, once in a lifetime Epoch Operation this October. Learn more here: https://www.warframe.com/en/news/epoch-operation-taubound","d":1},{"p":"Update 44 is a Mainline Update!"},{"p":"Meaning that everything the team has been working on since the launch of Update 43: Jade Shadows: Constellations is in this update (with the obvious exception of content that is not ready to be released). It is very likely, as it is with all Mainline updates, that things slip through the cracks so we will be watching for bug reports and feedback in the dedicated Iceblade of Narin subforums to address in follow-up Hotfixes."},{"p":"If any of the terms above are new to you, visit The Warframe Lexicon for Updates to learn more about Warframe's development cycle."}]},{"title":"Download Sizes","items":["PC DirectX 11: ~7.83 GB*","PC DirectX 12: ~8 GB*",{"p":"*Sound Optimization"},{"p":"You may notice a larger download size with this update due to optimization of our sound files. This requires you to download new versions of the files that when patched into your installation will result in a smaller install footprint overall without compromising any audio quality."},{"p":"Image Description: Yuvan Peak sits in tranquility with several pillars adorned by talismans and ice. Somewhat in the distance we can see a Warframe standing near a frozen monolith with a pale blue glow."}]},{"title":"NEW EARTH RELAY: YUVAN'S PEAK","items":[{"p":"Attention students! It's time for a field trip."},{"p":"Cephalon Melica has been summoned to Yuvan's Peak on Earth. This familiar site is now transformed by Narin's influence - her glacial Crest glitters against the snow. Within this frozen monument lies her Iceblade: Neote. Perhaps you'll be the one to pull it free."},{"p":"yuvan peak.mp4 Video Description: GIF showing the rotation effect when selecting the Yuvan Peak node on Earth. The camera pans around Lua and reveals the other side of Earth where Yuvan Peak is the lone visible node."},{"p":"This trip is not all fun, however. Entropic Kuva is seeping into the Zariman, and Yuvan Peak holds the key to help stop its threat."},{"p":"Prerequisites: To access Yuvan's Peak, players must have completed both the Angels of the Zariman and Whispers in the Walls quest."},{"p":"In this new Hub, gain access to the following:"},"New Vendor: Cephalon Melica",{"t":"For more information on her wares, please visit her dedicated section below.","d":1},"Coming Soon: Glacial Defiance (New 6-Player Game Mode)",{"t":"This content is not yet released, but Yuvan's Peak will be where you can start these missions. Learn more about general release window and the reasoning behind the delay: https://forums.warframe.com/topic/1523427-psa-glacial-defiance-release-window/","d":1},"Narin's Iceblade in Narin's Crest",{"p":"Image Description: A closeup of Narin's Crest, a single sword stuck in a frozen pillar. Framing it are two large curved ice structures, a snowy path littered with stones, and vast white clouds in the distance."}]},{"title":"Narin's Crest","items":[{"p":"On Yuvan's Peak, Neote, Narin's Iceblade, can be found frozen solid in a mound of ice, anchored firmly. Who will be the one to pull Neote from Narin's Crest?"},{"p":"Image Description: Narin stands in front of Cephalon Melica on the snowy Yuvan Peak. A \"Cephalon Melica\" context action is visible."}]},{"title":"New Vendor: Cephalon Melica","items":[{"p":"Oh, students! A familiar face is eager to greet you once you have made it to the Yuvan Peak. Concerned with the effects that Entropy is having aboard the Zariman, Cephalon Melica requires your assistance in containing its spread. Collect Entropic Kuva and bring it to Cephalon Melica and she may provide you with knowledge and supplies in exchange."},{"p":"You may chat with Cephalon Melica at either Yuvan Peak or in the Chrysalith (can be accessed through Fast Travel) to browse her Classroom Supplies and see what she offers:"},"Narin's Main and Component Blueprints","Nunchasa's Main and Component Blueprints","Aksondol's Main and Component Blueprints","On Wings of Ice Honoria","Narin Prex Card","New Somachord Tracks:",{"t":"Neote's Dance","d":1},{"t":"Ice Speaker","d":1},"New Captura Scenes:",{"t":"Melica's Laboratory Scene","d":1},{"t":"Yuvan Peak Scene","d":1},"Glacium Sigil","Seonang Ephemera","Tidon Shoulder Medallion","Tidon Chest Medallion","Tidon Leg Medallion","Niveus Sumdali","Niveus Nepheri Skin","Niveus Dark Split-Sword Skin","Niveus Dark Dagger Skin","Niveus Dark Sword Skin","Niveus Paracesis Skin","Niveus Orvius Skin","Niveus Glaxion Skin","Niveus Quellor Skin","Niveus Liset Skin","10,500 Kuva (4 purchase limit per week)"]},{"title":"ZARIMAN UPDATES","items":[{"p":"Image Description: Melica's Lab has a small vertical monitor displaying the Cephalon with a red overlay. Behind it is a large cylindrical machine spanning across multiple levels with various doors and alcoves visible."}]},{"title":"New Tile: Melica's Lab Room","items":[{"p":"Onboard the Zariman, a room previously sealed is now open for you to explore. Melica's Lab features a central machine in a large open floorspace, punctuated by smaller alcoves where Melica conducted a variety of mysterious experiments. Just what was Melica hoping to achieve? This new tile has a random chance to spawn in Zariman missions!"},{"p":"Image Description: Three Entropic Eximus units face us in the Zariman. Red energy glows across different parts of their body while they are encapsulated in a red sphere that seems almost gelatinous."}]},{"title":"New Enemy: Entropic Eximus","items":[{"p":"A new batch of Eximus have invaded the Zariman! Entropic Eximus can spawn in any mission on the Zariman, with a higher spawn rate over other types of Eximus units! A few even show up when fighting Void Angels, so be extra careful when starting that fight!"},{"p":"Entropic Eximus come equipped with a nearly impenetrable shield bubble, tossing destructive orbs at those who are too afraid to get close.The best counter is to slip inside their bubble and take them out from the inside, just be wary as they bring their destructive orbs crashing down around them."},{"p":"Entropic Eximus are more than just a new Eximus type - they are also the only method for obtaining Entropic Kuva!"},{"p":"Image Description: A closeup of the icon for Entropic Kuva. It has a similar shape to regular Kuva but is noticeably blue instead of red and features frozen spikes along its bulbous portion."}]},{"title":"New Resource: Entropic Kuva","items":[{"p":"A dangerous and erratic type of Kuva, acquired solely from Entropic Eximus units in Zariman missions."},{"p":"Collect and exchange it with Cephalon Melica at Yuvan's Peak for wares, including Narin's Blueprints and more!"},{"p":"Image Description: Narin gracefully dances with blade extended and pointing towards Yuvan Peak. Her pose is almost suggestive of channeling a vortex of snow and talismans towards the peak."}]},{"title":"NEW WARFRAME: NARIN","items":[{"p":"Narin descends in swirling eddies, her blade keen and deadly as an icy wind. She wields ice to defend as deftly as her swift rapier strikes."}]},{"title":"Narin's Abilities","items":[]},{"title":"Passive: Sangodae","items":[{"p":"Each stack of Cold Status Effect on enemies increases chance to spawn Sangodae pickup by 1%, granting Cold Damage on Primary and Secondary weapons for 10s. Narin also gains Cold Damage for her abilities."},{"p":"Ability 1: Neote*"},{"p":"Lunge with Narin's ice rapier Neote, inflicting Cold Damage and Cold and Puncture Status Effect on foes directly ahead of her."},{"p":"Gain Ice for each enemy hit."},{"p":"*This is Narin's Helminth ability."}]},{"title":"Ability 2: Naraemagi","items":[{"p":"Recover Shields by absorbing Cold Status Effect from nearby enemies. Gain Overguard if at full Shields."},{"p":"Gain Ice for each enemy hit."},{"p":"Ability 3: Hakchum**"},{"p":"Tap to leap into the air, tap again to land at target location. Applies Cold Damage Vulnerability and Status Effect in a large radius upon landing."},{"p":"Gain Ice for each enemy hit."},{"p":"**This is Narin's Railjack ability."}]},{"title":"Ability 4: Nurinarim","items":[{"p":"Requires full Ice to cast. An ancestral spirit descends upon Narin and she begins sword dancing for continuous nearby damage. Press Attack on the marked targets to launch shattering icy slashes that deplete Armor and Shields. Hitting Frozen enemies causes them to explode, dealing massive radial Cold Damage."}]},{"title":"How to Acquire Narin","items":["Acquire Narin's Main and Components from the Zariman Drop Tables. For the full list of where to find her parts in Zariman missions including drop rates, visit our official drop tables site: https://warframe-web-assets.nyc3.cdn.digitaloceanspaces.com/uploads/cms/hnfvc0o3jnfvc873njb03enrf56.html","Acquire Narin's Main and Component Blueprints from Cephalon Melica's Classroom Supplies by trading Entropic Kuva (earned from Entropic Eximus in Zariman missions).","Purchase Narin from the Market individually or as part of the Narin Bundle.",{"p":"Image Description: Narin's Prex card showcases the rapier-wielder standing left hand akimbo and her frozen blade pointed directly at the ground. In the background the snowy Yuvan Peak can be seen."}]},{"title":"Narin's Prex Card","items":[{"p":"The Iceblade Everlasting. Acquire it from Cephalon Melica's Classroom Supplies!"}]},{"title":"Maximum Loadout Slot Increase","items":[{"p":"With the release of Narin, the maximum number of purchasable Loadout Slots has been increased from 34 to 35."}]},{"title":"NEW BOW: NUNCHASA","items":[{"p":"Narin's signature bow is the north wind's icy messenger. Alt Fire unleashes a charged blizzard arrow that freezes enemies it touches and leaves behind a chilling path."}]},{"title":"How to Acquire Nunchasa","items":["Acquire Nunchasa's Main and Component Blueprints from Cephalon Melica's Classroom Supplies by trading Entropic Kuva (earned from Entropic Eximus in Zariman missions).","Purchase Nunchasa from the Market individually or as part of the Narin Bundle."]},{"title":"NEW PISTOL: AKSONDOL","items":[{"p":"Narin's signature pistols strike with winter's chilling bite. Reloading creates a cloud of freezing mist that inflicts Cold Status Effect, the pulse's range increases with each round reloaded."}]},{"title":"How to Acquire Aksondol","items":["Acquire Aksondol's Main and Component Blueprints from Cephalon Melica's Classroom Supplies by trading Entropic Kuva (earned from Entropic Eximus in Zariman missions).","Purchase Aksondol from the Market individually or as part of the Narin Bundle.",{"p":"Image Description: Citrine Prime poses in resplendent beauty with the Steflos Prime in her right hand and a floating amber in her left. Lustrous blues, ambers, golds, and whites comprise her primed color palette."}]},{"title":"CITRINE PRIME ACCESS","items":[{"p":"Shine on with a diamond's spellbinding purpose with Citrine Prime Access! Lavish Orokin gold complements every perfect cut of this jeweled bastion's signature Prime Weapons and exclusive Prime Accessories, instilling those fortunate enough to witness her luminescence with unshakeable resolve."},{"p":"Make your Arsenal shimmer with instant access and get the Prime items of your choice with Prime Access Packs. Additionally, you can earn Citrine Prime and her signature Prime Weapons in-game by collecting and cracking-open Void Relics!"},{"p":"Image Description: Two Citrine Primes model her prime weapons and accessories. On the left backing us we can see the Steflos Prime and Sphatika Prime Syandana, whereas on the right we see her facing us with the Corufell Prime."}]},{"title":"Citrine Prime","items":[{"p":"The crystalline citadel ascends. Citrine Prime captivates with refined radiance, her brilliant gems set within the finest gold filigree."}]},{"title":"Steflos Prime","items":[{"p":"This rose has gilded thorns. Deal death from even further afar with Citrine Prime's signature shotgun."}]},{"title":"Corufell Prime","items":[{"p":"Corufell Prime's golden vines streamline its transformation for even faster Heavy Attacks."},{"p":"Image Description: Citrine Prime Access Accessories are modelled by Citrine and an Operator. From left to right is the Sphatika Prime Syandana and the Spinele Prime Facial Accessory."}]},{"title":"Citrine Prime Accessories","items":[]},{"title":"Spinele Prime Facial Accessory, Earpiece & Oculus","items":[{"p":"Look sharp with this lavish set of facial accessories for both the Drifter and Operator."}]},{"title":"Sphatika Prime Syandana","items":[{"p":"Citrine Prime's signature Syandana sparkles with a brilliant luster."}]},{"title":"Alumeti Prime Sugatra","items":[{"p":"Adorn your weapon with the splendence of Citrine Prime's signature sugatra."}]},{"title":"Prismatic Gem Prime Decoration","items":[{"p":"A gleaming reminder of Citrine Prime to decorate your Orbiter."}]},{"title":"Citrine Prime Honoria","items":[{"p":"Earn the \"Crystal Bastion\" Honoria by acquiring Citrine Prime, either via Prime Access or by crafting her in the Foundry!"}]},{"title":"Items Moved To Prime Vault","items":[{"p":"Now that Citrine Prime Access is available, the following items have been added to the Prime Vault for a future Prime Resurgence rotation. If you have Relics that contain these items they will remain in your Inventory."},"Xaku Prime","Quassus Prime","Trumna Prime"]},{"title":"Riven Disposition Changes","items":[{"p":"As with each round of Prime Access come updated Riven Disposition numbers - check the full details here: https://forums.warframe.com/topic/1523355-september-2026-riven-dispositions/"}]},{"title":"RIVEN EXPANSION: TRAIT LOCKING (LIVE) & RIVEN SPLICING (COMING SOON)","items":[{"p":"You may have already seen a sneak preview of these new systems in our Dev Workshop. With today's launch, Trait Locking is officially live and Riven Splicing will be coming soon with the release of Glacial Defiance! Read on below for the latest on these systems."},{"p":"Riven Mods (often just called \"Rivens\" for short) were introduced in 2016, and are nearly a decade old now! With this update we've added a new feature for Rivens: Trait Locking! A second new feature will join Glacial Defiance: Riven Splicing. We'll share a little information about Riven Splicing below, for a more detailed preview of the system you can check out our Dev Workshop."}]},{"title":"TRAIT LOCKING (LIVE)","items":[{"p":"One of the primary requests we've received for Riven Mods is to allow players to lock a stat to prevent it from being Cycled. Now, you can do so with a system called Trait Locking!"},{"p":"One trait (stat) can be locked at a time while cycling a Riven, freezing it until the lock is removed or the Cycling menu is closed."},{"p":"There is no cost or item required to lock a trait. Locks can be removed and re-added for free! However, when cycling a Riven Mod with a locked trait, the Kuva cost is doubled. Locking a trait is entirely optional, and Rivens can still be cycled as usual without a lock."}]},{"title":"How to Lock a Riven Trait","items":[{"p":"1. Go to the Mod Segment in your Base of Operations"},{"p":"2. Select the Riven Mod you'd like to cycle and select the \"Cycle Riven\" option"},{"p":"3. Select the \"Lock Trait\" button"},{"p":"Image Description: Screenshot of the Riven Mod UI showing the Soma Argicron Mod. The options for Lock Trait and Cycle for 3,500 Kuva are shown and the cursor is hovering on Lock Trait."},{"p":"4. Select the trait you wish to lock. The locked trait will appear greyed out with a lock icon on the Mod and will also be listed above the \"Lock Trait\" button."},{"p":"Image Description: Screenshot of the Choose A Trait To Lock UI screen. Two traits are displayed as options, the first is a 1.5 times Damage to Grineer, and the second is an increased Critical Chance by 167.2%."},{"p":"Image Description: Screenshot of the Riven Mod UI screen showing the Soma Argircon Mod with a locked trait denoted by a lock icon. Above the Lock Trait option is the currently locked trait of increased Critical Chance by 167.2% and a remove icon next to it."},{"p":"5. Begin cycling your Riven with the locked trait! Notice that once locked, it will not change while cycling."},{"p":"Image Description: Screenshot of the Riven Mod Cycling UI at the Cycle preview screen. We can see that the Riven Mod has a locked trait and the resulting cycled Mod retains the locked trait."},{"p":"It is important to note that a trait needs to be re-locked each time you open this menu, as they are not maintained once the menu has been closed."},{"p":"Cycling a Riven with a locked trait prevents the number of traits on the Mod from changing. This means a Mod with 3 positive traits and 1 negative trait will always cycle into another version with 3 positive traits and 1 negative trait if one of the traits is locked. To cycle into a different number of traits, unlock all traits and cycle again."}]},{"title":"RIVEN SPLICING (LAUNCHING AT A LATER DATE WITH GLACIAL DEFIANCE)","items":[{"p":"Riven Splicing combines two traits on a Riven together to form a new spliced trait which is then locked on the Riven (without consuming a Trait Lock). Riven Splicing will require Riven Splicers, which will be rewarded from Glacial Defiance when it releases sometime before or on October 15 (release window PSA for more info). For more details about Riven Splicing, refer to our Dev Workshop."}]},{"title":"NEW WARFRAME AUGMENT MODS","items":[{"p":"Stats below are shown at Max Rank."}]},{"title":"Oraxia Widow's Brood Augment: Brood's Oversurge","items":[{"p":"Scuttlers are galvanized with Electricity. Hold to direct all active Scuttlers at the aimed target, inflicting 2000 Electricity Damage and Status Effect in a radius."},{"p":"Available in the New Loka and Cephalon Suda's Offerings."}]},{"title":"Uriel Infernalis Augment: Infernum","items":[{"p":"Release Fireballs for 1500 Heat Damage with larger volleys when grabbing Vythelas' Runes during flight. Hits from Fireballs slowly charge Brimstone."},{"p":"Available in The Perrin Sequence and Steel Meridian Offerings."}]},{"title":"Frost Snow Globe Augment: Cold Front","items":[{"p":"Snow Globe is now attached to Frost with a smaller radius while increasing your mobility*. Kills on frozen enemies increase the Globe health by 4% per kill."},{"p":"*Since this Augment impacts Frost's mobility it can also be equipped in the Exilus mod slot!"},{"p":"Available in the Cephalon Suda and Steel Meridian Offerings."}]},{"title":"Grendel Passive Augment: Gastroparesis","items":[{"p":"Each enemy consumed adds 15% Gas Damage to Primary and Secondary weapons."},{"p":"Available in Steel Meridian and Red Veil Offerings."},{"p":"Image Description: Savage Silence and Reactive Storm Atragraph Mods. Both Mods feature a colorful foil aesthetic with the former having a splatter motif while the latter captures Baruuk's motion."}]},{"title":"NEW ATRAGRAPH MODS: BANSHEE & BARUUK AUGMENTS","items":[{"p":"Chromatic Atramentum can now be applied to the following Banshee and Baruuk Augment Mods to give them new Atragraph stylings with art created by the extremely talented Pathidos_Zune."},{"p":"Visit Aspirant Zorba just outside of the Arbiters of Hexis' enclave in Relays (fast travel via quick access wheel also available) to use Chromatic Atramentum to cosmetically upgrade the following Augments:"},"Savage Silence Banshee Augment","Reactive Storm Baruuk Augment",{"p":"As a reminder, Atragraph Mods offer a purely cosmetic effect and in order to create them you must already own the Mod you wish to beautify."}]},{"title":"TENNOGEN: ICEBLADE","items":[{"p":"The overwhelming talent of our community artists is on full display with TennoGen Iceblade. This all-new collection brings several outstanding Customizations to add some opulent flair to your Fashion Frame."},{"p":"Image Description: Excalibur and Rhino, facing and backing us respectively, model new Tennogen items. Excalibur wears the Gothica Signa, while Rhino shows off the Reliquia Syandana and the Vermis Signa."}]},{"title":"Gothica Signa","items":[{"p":"A TennoGen Signa, designed by malaya, Jadie, and Awk'Q-Luz."}]},{"title":"Reliquia Syandana","items":[{"p":"A syandana for your Warframe, designed by lex182 and Therion."}]},{"title":"Vermis Signa","items":[{"p":"A TennoGen Signa, designed by Travelling Merchant and Therion."},{"p":"Image Description: Citrine and Jade model new Tennogen items. Citrine is wearing the Citrine Heliotropia Helmet and Jade is in the Jade Coven Skin."}]},{"title":"Jade Coven Skin","items":[{"p":"A unique skin for the Jade Warframe, designed by blazingcobalt."}]},{"title":"Citrine Heliotropia Helmet","items":[{"p":"A unique helmet for the Citrine Warframe, designed by Ventralhound."}]},{"title":"MARKET ADDITIONS","items":[{"p":"Image Description: Narin poses with some of the weapons and accessories of the Narin Bundle with the Yuvan Peak in the background. She is wearing the Baridegi Helmet and Gangrim Ephemera while wielding her signature dual pistols the Aksondol."}]},{"title":"Narin Bundle","items":[{"p":"Embody the spirit of the winter's storm. Narin's piercing rapier dances amidst the howling blizzard, flying on swift wings to bring protection and devastation."},{"p":"This bundle contains the following items, which can all be purchased separately:"}]},{"title":"Narin","items":[{"p":"Narin descends in swirling eddies, her blade keen and deadly as an icy wind. She wields ice to defend as deftly as her swift rapier strikes."}]},{"title":"Narin Baridegi Helmet","items":[{"p":"This alternate helmet for Narin evokes an otherworldly flower of frost, accentuating her finesse and grace."}]},{"title":"Nunchasa","items":[{"p":"Narin's signature bow is the north wind's icy messenger. Alt Fire unleashes a charged blizzard arrow that freezes enemies it touches and leaves behind a chilling path."}]},{"title":"Aksondol","items":[{"p":"Narin's signature pistols strike with winter's chilling bite. Reloading creates a cloud of freezing mist that inflicts Cold Status Effect on enemies that enter it and expands per round reloaded."}]},{"title":"Durumi Syandana","items":[{"p":"The wish for a long life is carried upon the noble wings of Narin's signature syandana."}]},{"title":"Isageum Signa","items":[{"p":"A circlet from ancient times, its ornamentation signifying wisdom and strength."}]},{"title":"Gangrim Ephemera","items":[{"p":"May a chill descend upon you with the frozen embrace of Narin's signature ephemera."}]},{"title":"Kalsawi Emote","items":[{"p":"A skillful sword dance."}]},{"title":"Icebound Neote Decoration","items":[{"p":"A recreation of Narin's icy crest and rapier, forever entombed aboard your Orbiter."},"Gifting Bonus: Gift this item to another player and receive this Gifting Bonus in return.",{"p":"Image Description: Qorvex Basilica stands flanked by fluttering allies through the Belfri Ephemera. Grey stone and cement contrast against orange energy lines and green metallic accents, especially seen in his devilish horns."}]},{"title":"Qorvex Basilica Collection","items":[{"p":"Drive off the presence of evil. Qorvex Basilica's monstrous shape strikes terror into those who would terrorize others."},{"p":"This collection contains the following items, which can all be purchased separately:"}]},{"title":"Qorvex Basilica Skin","items":[{"p":"Avert the gaze of evildoers with the intricately carved spires of Qorvex Basilica. His grim shadow is a symbol of protection for his allies."}]},{"title":"Mandonel Chythedra Skin","items":[{"p":"The Mandonel archgun, chiseled from the same ancient stone as Qorvex Basilica."}]},{"title":"Garkulek Syandana","items":[{"p":"Qorvex Basilica's signature syandana perches on your shoulders, keeping a sharp eye over all."}]},{"title":"Belfri Ephemera","items":[{"p":"Beckon Qorvex Basilica's fluttering fellows to your side with his signature ephemera."},{"p":"Image Description: Banshee Threnodia poses within a forest as the fog and light create a serene backdrop. Her dramatic shoulder piece mirrors a similar aesthetic to her helmet as azure patterns softly glow throughout her body."}]},{"title":"Banshee Threnodia Collection","items":[{"p":"Lament the spirits of the dead, and for those whose time is now here. The veil between worlds has fallen, and Banshee Threnodia strides forth in all her gaunt glory."},{"p":"This collection contains the following items, which can all be purchased separately:"}]},{"title":"Banshee Threnodia Skin","items":[{"p":"Banshee Threnodia's stark visage is an inexorable omen of death. Her mournful apparition brings despair to the wicked, her song the dirge of defeat."}]},{"title":"Gast Sentinel Accessories","items":[{"p":"An eerily twisted set of accessories for your sentinel pet. Includes the Gast Sentinel Mask, Wings and Tail."}]},{"title":"Banshee Sonatus Glyph","items":[{"p":"Cadaverous beauty calls to souls in the dead of night. A glyph for your profile created by community artist Mischka."},{"p":"Image Description: The Community Art Pack VI Glyphs are displayed across two rows. In the top row from left to right are Frost, Narin, Citrine, and the bottom row is Octavia and Sevagoth."}]},{"title":"Community Art Pack VI","items":[{"p":"Awaiting us at the summit of Earth's ice peak is the newest Warframe Narin. Her ice is not only strong, but beautiful to behold! Just like these glyphs in this new Community Art Pack!"},"Community Frost Glyph by FrostyNovaPrime.","Community Narin Glyph by Pertti Lancer.","Community Citrine Glyph by Shivecu.","Community Octavia Glyph by Izeda Datroi.","Community Sevagoth Glyph by DarikaArt.",{"p":"We are continuing our series of bundles - Community Art Packs! These packs focus on various Warframes and characters, with art crafted in the style of community artists."},{"p":"Learn more about the artists who created the Glyphs, with work-in-progress images, in our article here."},{"p":"Image Description: Banshee blasts surrounding enemies with her arms outstretched sending them flying. A soft light is emitted from her hands providing the only light source in the dark room she stands in."}]},{"title":"BANSHEE REWORK","items":[{"p":"Banshee may not be at the top of your Loadout list, but those who have mastered her kit are able to deal a significant amount of damage in-mission. While not the flashiest pick, she can turn any weapon into something truly lethal - our goal is to maintain that lethality, while adding a few quality of life lifts to her Abilities. The following changes aim to make her kit feel fluid and impactful, while staying true to her identity as a sound-based Warframe."}]},{"title":"Passive","items":[{"p":"Banshee's Passive is helpful to a sect of players who value stealth, but largely has little effect in most missions. We are keeping her hush mechanic, but adding a little extra value that feels thematically appropriate for our sound-based Warframe."},"Banshee's abilities pierce the ears of nearby enemies. Casting abilities applies maximum Puncture Status on foes within 10m.","Banshee's weapon noises are hushed."]},{"title":"First Ability - Sonic Boom","items":[{"p":"Sonic Boom is an excellent survival tool for Banshee, but its ragdoll mechanic does not synergize well with other elements of her kit. The following changes help improve its synergy, and improve Banshee's overall survivability."},"Sonic Boom is now cast one-handed and no longer roots Banshee in place.","Removed Ragdoll from affected enemies - now pushes them back and stuns them.",{"t":"The ragdoll did not synergize well with Sonar as it made it harder to target the weakpoints.","d":1},"Increased Impact damage from 50 to 250.","Sonic Boom now reduces 70% of Armor, scaling with Ability Strength up to 100%.",{"t":"This mechanic was originally tied to Sonic Fracture, but is now part of her base kit.","d":1},"Sonic Boom now breaks resource containers and breakable decorations.","Sonic Boom now deals a guaranteed Impact Status Effect.","Renamed the \"Strength\" stat to \"Push Force\", as it affects how strongly Sonic Boom will push enemies."]},{"title":"Sonic Fracture Augment","items":["Renamed to \"Sonic Siphon\".","Banshee gains Armor for 20s if an enemy is hit by Sonic Siphon, up to a cap of 1500 Armor.",{"t":"Armor does not need to be stripped for this bonus Armor to apply!","d":1},"Recasting Sonic Siphon will refresh the Bonus Armor duration if an enemy is struck by the cast.",{"p":"Sonic Boom SFX no fade.mp4"}]},{"title":"Second Ability - Sonar","items":[{"p":"Sonar turns many weapons into a powerhouse in the right hands, but requires a lot of spam casting to reach its full potential. In addition, it offers little synergy with existing Weak Point enhancements as Sonar's Weak Spots are considered a separate mechanic. These changes address common player feedback, while also giving the ability a light quality of life lift."},"Sonar's Weak Spots are now considered Weak Points, giving them synergy with a variety of Mods, Arcanes, and more.","Sonar now prioritizes unmarked parts of the body for its Weak Spots to help with Weak Spot legibility.",{"t":"The reticle now turns red when shooting at the Weak Spots, just like other Weak Points.","d":1},"Casting Sonar no longer roots Banshee in place.","Updated SFX when hitting a Weak Spot."]},{"title":"Resonance Augment","items":["Unchanged."]},{"title":"Third Ability - Silence","items":[{"p":"Silence is a powerful Ability, but its impact on the battlefield is not always clear to players. The following changes help improve the visibility of its effects, with a few quality of life touches!"},"Silence can now be recast to reset its duration and reapply the Stun.","Casting Silence no longer roots Banshee in place.","Improved VFX on enemies to make it clearer they are affected by Silence."]},{"title":"Savage Silence Augment","items":["Unchanged."]},{"title":"Fourth Ability - Sound Quake","items":[{"p":"Sound Quake is an iconic part of Banshee's kit, but it struggles to synergize with her other Abilities. Our goal with the following changes is to make Sound Quake fit more fluidly into Banshee's playstyle, while retaining the nostalgic elements that are emblematic of her kit."},"Sound Quake is no longer channelled. Casting the ability creates an area of effect with a duration of 25 seconds.","Resonating Quake fans may be confused by this change - we are swapping the mechanics of the Augment and the base Ability to make Sound Quake synergize better with the rest of Banshee's kit.","Banshee is briefly invulnerable when casting Sound Quake.","Enemies receive guaranteed Blast Status Effects while in Sound Quake's area of effect, which reduces based on distance from the center.","Increased casting animation speed to make it more fluid.","Sound Quake now breaks containers within its entire area of effect, not just the 5 metres around the epicenter."]},{"title":"Resonating Quake Augment","items":["Renamed to \"Gaseous Quake\".","Gaseous Quake is now a channelled Ability, which takes on the mechanic of Banshee's old Sound Quake.","Banshee is rooted in place to channel Gaseous Quake, which deals additional Gas Damage and Status Effects to enemies in the area of effect.","Gaseous Quake's damage is multiplied every second during cast, up to a cap.",{"t":"Energy drain also increases every second during casting.","d":1},"Gaseous Quake's area of effect now persists for a short duration after channelling ends.","Improved Line of Sight now applies to Gaseous Quake.","Updated VFX and SFX to reflect this new gassy styling of the Ability.",{"p":"Banshee Rework_Sound Quake + Gaseous Quake_V4 no fade.mp4"}]},{"title":"OPERATOR/DRIFTER IMPROVEMENTS","items":[]},{"title":"Hair Shader Improvements","items":[{"p":"We've improved the quality of our hair shaders with the goal of having richer colors and better visuals. Here's what the team's efforts have resulted in and what you can expect:"},"Black hair is a much \"truer\" black, and less a \"mid grey\"","Colored hair is deeper and more accurate to selected color","White hair looks more white without losing depth","Sheen is stronger but balanced with underlying color","Added a slight rimlight on hair for \"scattering\"",{"p":"While these changes are a major overall lift to hair shaders, you may have to make some adjustments to find your preferred look once more. At the same time, you may enjoy experimenting with the shaders and achieving looks that might not have been possible before, so have fun exploring new options!"},{"p":"Image Description: Composite image of a live build and dev build screenshot showcasing the difference in sheen and color on an Operator's black hairstyle. In the live build the black hair has a grey tone compared to the dev build which has a deeper black."},{"p":"Note: All color channels are set to the \"blackest\" black from the Smoke palette!"},{"p":"Image Description: Composite image of a live build and dev build screenshot showcasing the difference in a deep red hair color on an Operator. In the live build the deep red appears lighter than the selected color whereas the dev build is more accurate."},{"p":"Image Description: Composite image of a live build and dev build screenshot showcasing the difference in highlights in an Operator's hairstyle. The dev build changes feature the dimensions of the bright colors."},{"p":"Image Description: Composite image of a live build and dev build screenshot showcasing the difference in visual fidelity of hair on an Operator with blonde and pink hair. The live build's hair appears more muted while the dev build has a richer gradient in colors adding more depth."},{"p":"These changes also apply to Kubrow fur!"},{"p":"Image Description: Composite image of a live build and dev build screenshot showcasing the difference in fur presentation on a Kubrow. In the live build the greys and blacks appear gray along with the blue being brighter than the dev build where each color is richer and deeper."},{"p":"As a general note, we've also made a handful of small improvements to Operator and Drifter cosmetics and hair texture. We've also improved tint options to certain hairstyles that were previously not very customizable (ex: Short Sidecut, Kaya's Hairstyle)."},{"p":"While in the pursuit of improving the shaders, we also acknowledge the effort that is dedicated to customizing your Operator and Drifter. So we'll be watching for your feedback on these changes. Thank you, Tenno!"}]},{"title":"Vitiligo Complexion Changes","items":[{"p":"Image Description: Screenshot of the Drifter Features UI menu with the vitiligo complexion, Complexion B-17 selected. Two additional options are present, Markings Coverage and Invert Markings."},{"p":"With this update we are changing the way that the vitiligo complexion, Complexion B-17, functions. Previously, the skin tone selected via Complexion Tint would apply across the entire skin and this would lead to unexpected tones or the erasure of vitiligo in some tone choices."},{"p":"Now Complexion Tint applies only to melanated areas which allows for a better tinting overall and greater respect for the tone selected. Through the addition of two new features we have expanded your ability to customize your skin tone with vitiligo."},"Markings Coverage: Lets you adjust the degree to which the vitiligo pattern is present (i.e. the dispersion of melanin)",{"t":"Note: In order for this option to become available, you must first select a complexion tint.","d":1},"Invert Markings: Lets you swap the current melanated vs lack of melanin regions within the vitiligo pattern",{"p":"Sequence 02.mp4 Video Description: GIF of the Drifter Features UI showing the effect of changing the Markings Coverage slider on the vitiligo pattern. The Invert Markings toggle is then turned on and off to show the swap in melanated and non-melanted areas."},{"p":"We hope these changes allow you to better shape and express your Operator/Drifter in the way you would like!"}]},{"title":"QUALITY OF LIFE (QOL) CHANGES","items":[]},{"title":"Weak Point Standardization","items":[{"p":"With our changes to Banshee's Sonar, we are working on a wider standardization of Weak Points. There are a variety of Abilities and enhancements that trigger \"On Headshot\", but enemies have a variety of weak points outside of just their heads (if they even have a head, depending on the enemy). As a result, we are working to convert all \"On Headshot\" triggers to be \"On Weakpoint\" instead. This is a large undertaking considering the vast array of Incarnons, Mods, Arcanes, Unique Traits, and more, so we're prioritizing the most popular enhancements to start."},{"p":"Converted the following triggers from \"On Headshot\" to \"On Weakpoint\":"},"Longbow Sharpshot","Argon Scope","Hydraulic Crosshairs","Galvanized Crosshairs","Galvanized Scope","Primary Deadhead","Secondary Deadhead","Arcane Precision","Arcane Pistoleer","Sharpshooter","Harrow's Thurible, Covenant and Lasting Covenant Augment",{"p":"In addition, we have converted Helios' Detect Vulnerability Precept to apply Weak Points instead of weak spots so it matches Banshee's updated Sonar."},{"p":"We'll continue this effort in future updates!"}]},{"title":"Metal Tint Improvements","items":[{"p":"Similar to our hair shaders, there's been a longstanding issue with dark tinted metals appearing grey. We have fixed this for Iceblade of Narin by making changes to the encoding to achieve richer and more saturated metals. Where the current system has a difficult time honoring your chosen tint on metal channels, this new one should more accurately reflect the selected color."},{"p":"Image Description: Composite image of a live build screenshot and dev build screenshot showcasing the metal tint differences for Frost. Metal regions around the arms, chest, and abdomen are a deeper and richer blue in the dev build."},{"p":"Image Description: Composite image of a live build screenshot and dev build screenshot showcasing the metal tint differences for Caliban. His red metal accents are more saturated in the dev build."},{"p":"Image Description: Composite image of a live build screenshot and dev build screenshot showcasing the metal tint differences for Garuda. Garuda's red metal tints are deeper and richer."},{"p":"Image Description: Composite image of a live build screenshot and dev build screenshot showcasing the metal tint differences for Gara. Gara's metal frame in the dev build looks richer and deeper."},{"p":"On this morning's pre-launch livestream, pitch black metals were shown to be achievable across all metals on the test build. This is unintended and will be removed in our first hotfix. We apologize! We are however still looking to maintain it specifically for the Voidshell Ayatan Elegance Material, which is currently not functioning as it was prior to the update, something we are looking to fix in the future. We apologize for the fashionframe inconvenience!"},{"p":"As fellow fashionframe enjoyers ourselves, we know that customizing is a universally important element to the Warframe experience, so we will be watching for your feedback on the changes. Thank you, Tenno!"}]},{"title":"The Perita Rebellion Mine Rework","items":[{"p":"While traversing the battlefield of The Perita Rebellion, you may have encountered small interactable mines which pose environmental hazards. We have made a few changes to these mines to prevent accidental activation, reduce aiming complexity, and to encourage using melee rather than shooting them."},{"p":"Mines will now:"},"No longer spawn on top of each other and cannot spawn inside of the larger mines from the Clear the Minefield Order","Have a light that blinks to identify that it is a mine and the light's blinking increases the closer your proximity to the mine","Rise up from the ground into melee attack height once a player enters within their activation proximity","Prioritize targets based on where your crosshair is pointing when attempting to melee them"]},{"title":"General QOL","items":["Updated the Zariman Ten Zero's mission drop tables so that Aeolak and Hespar component blueprints appear in every Rotation, instead of just Rotation C.",{"t":"Also changed Galeforce Dawn to drop from all Rotations of Void Armageddon instead of only Rotation C.","d":1},"Grendel Changes:",{"t":"Reduced the decay rate of enemies in Grendel's gut by 50%.","d":1},{"t":"Managing the amount of enemies in Grendel's gut is essential for part of his kit, so this helps swallowed enemies last longer before he has to Feast again.","d":2},{"t":"Grendel's Regurgitate now does bonus damage based on the enemy's Max Health instead of their current health in his Gut.","d":1},"Swapped Hydroid and Hydroid Prime's Shield and Armor values following community feedback.",{"t":"Hydroid:","d":1},{"t":"Shields: 240 (was 365)","d":2},{"t":"Armor: 365 (was 240)","d":2},{"t":"Hydroid Prime:","d":1},{"t":"Shields: 290 (was 650)","d":2},{"t":"Armor: 650 (was 290)","d":2},{"t":"The addition of Hydroid's Plunder ability during his 2023 rework reoriented his kit towards health-based survivability. This change leans further into emphasizing Hydroid's strengths in a way that makes sense for him.","d":1},"The following resources can now be fed to Helminth for Secretions:",{"t":"Pheromones: Beating Heartstrings","d":1},{"t":"Biotics: Scuttler Husks","d":1},{"t":"Calx:","d":1},{"t":"Temporal Dust","d":2},{"t":"Fergolyte","d":2},{"t":"Fate Pearls","d":2},{"t":"Bile:","d":1},{"t":"Ignia","d":2},{"t":"Maphica","d":2},{"t":"Oxides:","d":1},{"t":"Agnovidisc","d":2},{"t":"Laudavi","d":2},{"t":"Servoris","d":2},"The following Perita resources can now be donated to your Clan Vault and are also eligible for Clan Vault Resource Bonus:",{"t":"Agnovidisc","d":1},{"t":"Laudavi","d":1},{"t":"Servoris","d":1},"Updated the list of eligible enemies for the Vessel challenges in the Sands of Inaros quest:",{"t":"Denial Bursa: all Bursa variants (not just Denial) now count for this challenge","d":1},{"t":"Brood Mother: added Deimos and Uranus Proxima variants","d":1},{"t":"Crewman: added Railjack and Narmer variants","d":1},{"t":"Juggernaut: added Deimos, Demolisher, and Behemoth variants","d":1},{"t":"Hyekka Master: added Nightwatch variant","d":1},{"t":"Manic: added Manic Bombard and Nightwatch variants","d":1},{"t":"Railgun Moa: added Railjack variants","d":1},{"t":"Seeker: added Kuva, Nightwatch, Tusk, and Narmer variants","d":1},{"t":"Volatile Runner: added Deimos variants","d":1},"Added the amount of currently owned Fergolyte and a progression element to the Prince contribution menu UI.","Resource description tool tips now appear while hovering over the warning icon that indicates when you lack the required resource to purchase an item from a vendor.",{"t":"Since this is where players are likely to mouseover, we figured it would be helpful to show them what the resource is and where to get it.","d":1},"Improved spawn location logic for players using the /unstuck command."]},{"title":"MANDARIN VOICE OVER EXPANSION","items":[{"p":"We've made two big changes to both Mandarin voice over lines and subtitles:"}]},{"title":"1. Improved Existing Lines","items":[{"p":"We made the following improvements based on player feedback to the existing 12,000 lines to enhance the overall experience:"},"Improved the translations and subtitles so that they better match the VO","Improved context and emotion in voice performances","Added missing voice lines","Improved technical quality",{"p":"The above was also applied to our approach with the new lines we've implemented for this update (listed below)."}]},{"title":"2. Added new Mandarin VO & Subtitles","items":[{"p":"Mandarin VO and accompanying subtitles are now available in the following areas of the game:"},"Quests:",{"t":"Awakening","d":1},{"t":"Vor's Prize","d":1},{"t":"The Teacher","d":1},{"t":"Saya's Vigil","d":1},{"t":"Vox Solaris","d":1},{"t":"Waverider","d":1},{"t":"Patient Zero","d":1},{"t":"Once Awake","d":1},{"t":"A Man of Few Words","d":1},{"t":"The Limbo Theorem","d":1},{"t":"The New Strange","d":1},{"t":"Archwing","d":1},{"t":"Stolen Dreams","d":1},{"t":"Howl of the Kubrow","d":1},{"t":"The Duviri Paradox (including intro cinematic)","d":1},"Hubs & Missions",{"t":"The Plains of Eidolon","d":1},{"t":"Cetus","d":1},{"t":"Galleon of Ghouls","d":1},{"t":"Fortuna","d":1},{"t":"Duviri","d":1},"General:",{"t":"Lotus lines for early game missions","d":1},{"t":"Orbiter","d":1},{"t":"Nightwave","d":1},{"t":"Junctions","d":1},{"t":"Relays","d":1},{"t":"Leverian","d":1},{"t":"Lunaro","d":1},{"t":"Mastery Rank Tests","d":1},{"p":"For the areas not listed above, where Mandarin VO is not available, the game will default to the English audio with Simplified Chinese subtitles."}]},{"title":"How to Enable Mandarin VO","items":[{"p":"As a reminder, players on the Simplified Chinese Client can swap between Mandarin and English Voice Over in the Audio Language settings of the launcher."},{"p":"Launcher video version.mp4 Video Description: GIF showing the Warframe Launcher in Mandarin. The Settings gearwheel is clicked and then in the section for Audio Language the cursor moves to click the dropdown menu. The language is changed from English to Mandarin and then the Ok button is clicked to implement the change."}]},{"title":"ADDITIONS","items":["Added over 60 new Perita-themed Dojo Decorations.","Added support for the following currencies on our website and Steam:",{"t":"Singapore (SGD)","d":1},{"t":"New Zealand (NZD)","d":1},{"t":"Norway (NOK)","d":1},{"t":"Switzerland (CHF)","d":1},{"t":"India (INR)","d":1},{"t":"Chile (CLP)","d":1},{"t":"Peru (PEN)","d":1},{"t":"South Africa (ZAR)","d":1},{"t":"Hong Kong (HKD)","d":1},{"t":"Saudi Arabia (SAR)","d":1},{"t":"United Arab Emirates (AED)","d":1},{"t":"Costa Rica (CRC)","d":1},{"t":"Israel (ILS)","d":1},{"t":"Kazakhstan (KZT)","d":1},{"t":"Qatar (QAR)","d":1},{"t":"Uruguay (UYU)","d":1},{"t":"Vietnam (VND)","d":1},"Added various new Honoria.",{"t":"Available from Roathe's wares in La Cathédrale:","d":1},{"t":"|NAME| Clionadh - 50 Javlok Capacitor","d":2},{"t":"|NAME| Berserk Crucible - 200 Entrati Lanthorn","d":2},{"t":"Rewarded to those to completed Trials before they were retired:","d":1},{"t":"The Law of Retribution: Retributor |NAME|","d":2},{"t":"Nightmare Law of Retribution: |NAME| Vay Hek's Nightmare","d":2},{"t":"The Jordas Verdict: |NAME| The Final Verdict","d":2},{"t":"Completed both Trials: |NAME| Tried and True","d":2},"Added \"Quick Buy\" under the Featured Market tab.",{"t":"Here your most recent 10 consumable/repurchaseable purchased items will appear. This is in addition to your 3 most recent appearing in the top-right of the Market UI for quick buy.","d":1},{"p":"Image Description: Screenshot of a blurred Market UI with a highlighted focus on the Quick Buy option under the Featured tab. To the right of the image is a small drop down showing the Quick Buy items of an Exilus Warframe Adapter, a Veiled Riven Cipher, and an Orokin Reactor."},"Added Oraxia to the Invert Tap/Hold Abilities list in the settings."]},{"title":"CHANGES","items":[]},{"title":"Archimedea Parameter & Reward Track Changes","items":[{"p":"Archimedea is changing! A variety of changes are coming to the choices a Tenno makes before starting an Archimedea (both Deep Archimedea and Temporal Archimedea, including their Elite versions) mission."}]},{"title":"Arsenal Bonuses","items":[{"p":"Warframes and Weapons alike will be granted an Arsenal Boost for matching their respective Individual Parameters! The buff received will be the same for each parameter, meaning regardless which Primary Weapon you choose, the boost is the same! Pick the Weapon or Warframe that works best with each boost for maximum efficiency!"},{"p":"Image Description: Screenshot of the Deep Archimedea UI screen showing the Individual Parameters, Missions, Research Points Track, and Current Loadout. Specific elements of the Individual Parameters are highlighted that match the current loadout."}]},{"title":"Reward Track Changes","items":[{"p":"We're moving around a few of the rewards at the top end of the Elite Archimedea Reward Tracks, and adding a new reward!"},"A new reward is added at 34 points, consisting of Vosfor or Pix Chips, for Deep Archimedea or Temporal Archimedea respectively","The Legendary reward at 34 points has been moved to 37 points","The final reward at 37 points has been moved to 40 points",{"p":"Image Description: Composite image of before and after the update to Archimedea's Research Points Reward Track. In the after image we can see a change in the rewards at 34 and 37 points and the addition of a reward at 40."}]},{"title":"Warframe Research Point Changes","items":[{"p":"Studious Tenno may have noticed that the 40 points now required for maximum rewards is higher than the current maximum! Worry not, we're also increasing the amount of points from using one of the 3 Warframes under Individual Parameters - they will now grant 3 Research Points per mission, up from 1! This raises the maximum amount of points in one Elite Archimedea mission to 43."},{"p":"The highest tier reward (at 40 points) will now be obtainable without one Individual Parameter (other than Warframe), and the Legendary reward is achievable whilst leaving behind two Individual Parameters!"}]},{"title":"Additional Personal Modifiers","items":[{"p":"Six new Personal Modifiers have been added to the rotation to keep you on your toes!"},"Infected Wounds: Gain a Toxin Status Effect every time you take damage.","Anemic Shields: Maximum shield and overshield will not exceed 500.","Shortened Reach: Ability range reduced by 50%","No Pets Allowed: Companions are disabled.",{"t":"Note: When playing Khora, this does not disable Venari.","d":1},"Channeled Greed: While a channeled ability is active, maximum shields and overshields are reduced each second. 10s cooldown to fully recover.","Low Yield: Blast radius of weapons with radial attacks set to 3m",{"p":"Plus one change to an existing Personal Modifier:"},"Framecurse Syndrome: Activating an Ability inflicts 50 damage and 150 shield damage upon you.",{"t":"Added the damage to shields","d":1}]},{"title":"Personal Modifier Buckets","items":[{"p":"To ensure no combination of Personal Modifiers are too difficult, we've also split them into 4 buckets, and one Modifier will be selected from each bucket per week."},{"p":"Due to Archimedea Modifiers being selected at the beginning of the week, this will first occur on the next weekly reset at: September 28, 2026 at Midnight UTC."}]},{"title":"Group One","items":["Ability Overload","Dropped Guard","Dull Blades","Framecurse Syndrome","Hypersensitive","Knifestep","Low Yield","Secondary Wounds","Undersupplied"]},{"title":"Group Two","items":["Abbreviated Abilities","Channeled Greed","Constricted","Energy Exhaustion","Powerless","Shortened Reach"]},{"title":"Group Three","items":["Ammo Deficit","Gear Embargo","No Pets Allowed","Transference Distortion"]},{"title":"Group Four","items":["Anemic Shields","Fractured Armor","Infected Wounds","Lethargic Shields","Permanent Injury","Untreatable"]},{"title":"Fixes","items":["Fixed Restricted Respawns not applying the 2 seconds penalty to Last Gasp in Deep Archimedea."]},{"title":"The War Within Quest Art Remaster","items":[{"p":"We've made several improvements to the levels in The War Within Quest to elevate this crucial chapter for the Tenno. The environment art, lighting and skyboxes have been updated in the Golden Maw and Mountain Pass sections to create a more realistic and dramatic experience."},{"p":"Image Description: Composite image of a before and after screenshot of a cave in The War Within Art Remaster. The after image shows the improvements in lighting, visual fidelity, level design, and environmental details."},{"p":"Image Description: Composite image of a before and after screenshot of a cave in The War Within Art Remaster. The after image shows the improvements in lighting, visual fidelity, level design, and environmental details."},{"p":"Image Description: Composite image of a before and after screenshot of a cave in The War Within Art Remaster. The after image shows the improvements in lighting, visual fidelity, level design, and environmental details."},{"p":"You can view the changes yourself by visiting the updated War Within Choice Captura Scene or by replaying The War Within quest via the Codex."}]},{"title":"General Changes","items":["Sirius & Orion can now be rolled as an option in Duviri.",{"t":"This Warframe was originally disabled so the team had more time to address Duviri-specific bugs for them. We've fixed what we are aware of, but we'll be monitoring for additional reports after this update!","d":1},"Necramech Slots have been retired!",{"t":"Moving forward, players will only be able to own one of each of the Necramechs (Voidrig & Bonewidow). Those who already owned multiple before this update will keep them.","d":1},{"t":"We will be running a script sometime after the update has launched to refund players who had purchased Necramech Slots. We will update you once the script has completed! We will update you once the script has completed!","d":1},"Umbra now has a proper boss-type health bar in a certain stage of The Sacrifice quest.",{"t":"This change makes it easier to see how much of his shields have been depleted.","d":1},{"t":"Also fixed cases of his Shields appearing greyed out when he reappears later in the same stage.","d":1},"Temple's Rhythm Guard Augment will no longer reduce Temple's Overguard if their current Overguard exceeds the Augment's cap.","Citrine's Preserving Shell now applies to Companions.","Added highlighting to the End of Mission screen to indicate each stat's top player.","Trading Chat is now hidden for players whose Mastery Rank is not high enough to trade (MR 2).","Improved the visibility of the Side Objective marker VFX in Duviri.",{"t":"Also fixed objective markers in Duviri not updating to point to the next objective until the player is close to the next target.","d":1},"Reduced the draw SFX on Dread following community feedback.","Improved enemy navigation and spawn points in various tilesets.","The High graphics quality preset now sets Anisotropic Filtering to 8x (previously was 4x).","Updated death VFX for Specters summoned via the Gear Wheel.","Dojo Transporter names are no longer restricted to alphanumeric characters.",{"t":"Allowed characters now match Tributa decorations.","d":1},"Removed the minimize button on the launcher on SteamDeck as it would leave players without the ability to bring it back.","Removed Truth's Flame from Auto Install eligibility.",{"t":"The curse element of the mod is not new player friendly, so we've removed it from auto install to prioritize other more generally useful mod options.","d":1},"Updated the textures of the Sentient Brachiolyst, Symbilyst, Conculyst and Typholyst."]},{"title":"PERFORMANCE & OPTIMIZATIONS","items":["Improved performance in Höllvania missions.","Improved performance issues related to Surge Eximus' electricity attacks on lower-performance machines.","Optimized the DirectX shader install and memory footprint.","Optimized memory usage when running DirectX 11.","Optimized shader memory and install-size.","Made modest optimization to light culling speed in open landscapes.","Made systemic micro-optimizations to rendering.","Made systemic micro-optimizations to many script interfaces.","Made optimizations to FSR3 implementation to make it compatible with DirectX 11.","Made minor HUD optimizations.","Optimized spawner destruction.","Fixed small hitch after picking up Sirius & Orion's Prex card.","Fixed hitch after opening Smokefingers wares for the first time in Fortuna.","Fixed a hitch when viewing the Vena Gemini Skin in the Market.","Fixed a combination of Punch Through & Fire Rate causing significant performance issues with certain weapons (or with Cyte's Seek).","Fixed a large hitch occuring when switching to the Zariman Dormizone Captura Scene from another Captura Scene.","Fixed hitching that occurs when a Sevagoth or Sevagoth Prime Specter casts Exalted Shadow.","Fixed performance issues caused by pickups spawned by Uriel's Gulphagor.","Fixed a performance issue that could occur if the H-09 Efervon Tank was shot with high fire rate weapons","Fixed rare case of Clients performance being affected while playing Undercroft."]},{"title":"FIXES","items":[]},{"title":"Top Fixes","items":["Fixed the bonus damage from Cyte-09's Resupply packs not being affected by Ability Strength if picked up from the ground.","Fixed Archon Amar becoming permanently invulnerable if Health drops below 30% during his clone ability in The New War Quest, preventing players from progressing.","Fixed Arctic Eximus not using their base abilities like other Eximus.","Fixed Operators not using correct customizations on player Profiles.","Fixed Thumper and Eidolon limbs not taking the correct amount of damage when struck by the Voidrig's Arquebex.","Fixed various issues related to Challenge completion not registering, resulting in players missing the related Honoria (where applicable).",{"t":"Players affected by this issue should be able to complete the Challenge again, or see it registered for non-repeatable challenges (ex: Squad Goals).","d":1},{"t":"Those with missing Honoria should see them in their accounts upon login.","d":1},"Fixed additional cases of inactive enemies disappearing in Netracell missions.","Fixed Operator and Drifter heads not properly tracking to camera movement.","Fixed Sirocco's perfect reload mechanic not working outside of Duviri."]},{"title":"Sirius & Orion Fixes","items":["Fixed Clients being able to stack Arcane Concentration infinitely by swapping between Sirius & Orion.","Fixed the inactive Son being able to kill you in the Simulacrum as Sirius & Orion if friendly fire is turned on.","Fixed Sirius & Orion respawning in different locations by making respawns for both Sons happen at the active Son's location.","Fixed having abilities locked if you timed your swap of Sons right as you passed through a streaming tunnel into an Open Landscape.","Fixed players being placed in the wrong location when switching Sons prior to entering a teleport volume.","Fixed a rare case where switching between Sirius & Orion at the start of a Höllvania mission would cause the player to be invincible.","Fixed the inactive Son floating in mid-air while loading into a Höllvania mission from the Höllvania Central Mall.","Fixed Sirius & Orion spawning in the middle of the ship instead of the front when starting a Railjack mission.","Fixed the Arsenal being inaccessible if Transference is used while in the Simulacrum and Sirius & Orion's Celestial Clash is active.","Fixed Tenacious Bond's Critical Damage buff being inconsistently applied during Celestial Clash.","Fixed other players not seeing your chosen Son when using Sirius & Orion in Hubs.",{"t":"The inactive Son will now also appear in Hubs or the Orbiter and run around with you.","d":1},"Fixed swapping between Sons while entering a Nullifier bubble causing the Inactive Son's abilities to be permanently disabled.","Fixed Sirius & Orion's Jade Stars VFX positioning being too low while flying around in Archwing.","Fixed allied NPCs (companions, etc) often getting stuck trying to path to player after jumping as Sirius & Orion.","Fixed the Inactive Son forgetting how to jump, causing them to sometimes get stuck on terrain.","Fixed a loss of function after dashing into a Submersible Archwing volume while Celestial Clash is active.","Fixed Sirius & Orion triggering the Arsenal context action instead of the Take Mod Segment action in The Teacher quest leading to a progression stop.","Fixed Sirius & Orion incorrectly having full access to their equipped weapons after modding the Thornbak in The Teacher quest."]},{"title":"Equipment Fixes","items":["Fixed other players not being able to see the Bubonico and Coda Bubonico's firing animations.","Fixed the Onslaught Matrix Mod infinitely stacking if you complete Railjack missions without returning to the Orbiter.","Fixed the Stug Incarnon stacking Secondary Enervate by switching weapons before detonation.","Fixed the Athodai and Athodai Prime's Alt-Fire's zoom distance changing based on your frame rate.","Fixed Garuda experiencing a Heavy Landing after releasing hold to cast Dread Mirror while airborne.","Fixed Chroma's emissive color always defaulting to Heat at mission start, regardless of color selected.","Fixed Jade's Symphony of Mercy increasing the damage of Railjack armaments.","Fixed Haalvu's barrels not performing their idle animation correctly when first loading into a mission.","Fixed Mass Vitrify not refreshing Splinter Storm if airborne and falling.","Fixed Inaros being able to collect pickups while in his Sarcophagus passive.",{"t":"Since the UI is disabled during this state, this was causing confusing scenarios such as not seeing the Reactant pickup tracker in Relic missions and missing important UI cues for mission objectives.","d":1},"Fixed the Stug's charge time being bypassed if the input was changed.","Fixed Yareli with the Venato Prime equipped resulting in Beast Companions dealing Tau Status Effects from their Melee attacks while she is on Merulina.","Fixed the Venka Prime becoming briefly invisible after reviving.","Fixed Helminth infused Jade Stars not triggering for Yareli while on Merulina.","Fixed the Far Offset Camera Position setting causing Nova to immediately go through her Wormhole upon cast.","Fixed Kullervo's Wrathful Advance causing sudden rapid camera movement when used with the Syam, Corufell, Vinquibus, or Tenet Agendus.","Fixed Oraxia's Webbed Embrace being deployed mid-air when aiming at her feet if the game client's frame rate is 30 or lower.","Fixed Inaros being targeted by enemies while Invisible if Sandstorm is active.","Fixed the Burston Incarnon Evolution III Challenge being completed by the use of secondary weapons.","Fixed Nyx jumping immediately after Assimilate ends resulting in her being unable to double jump for the remainder of the mission.","Fixed the Ore Radar from Oxylus' Scan Matter Precept being overridden by the equipped Mining Laser.","Fixed Clients using Grendel's Pulverize sinking when entering submersible zones in ball form.","Fixed Razor Mortar's impact SFX being too loud.","Fixed Grendel's Regurgitate VFX not adjusting to stats.","Fixed Temple being unable to earn charge for Lizzie after completing subsequent Railjack missions."]},{"title":"Mission Fixes","items":["Fixed Warframe Auras applying to Drifter in Duviri.","Fixed Marrowtick Grapples providing infinite Status immunity.",{"t":"We recently discovered that grappling to a Marrowtick would provide immunity to all Status Effects for the remainder of your time in The Perita Rebellion. This fix maintains the temporary immunity as intended, but removes the unintended permanent status immunity.","d":1},"Fixed cases of Clients being unable to complete the race objective in the Descendia.","Fixed Clients getting stuck in an infinite loading loop if the Host closes the game during loading a Railjack mission.","Fixed Clients seeing the Karotic Signa's VFX linger in the location it is found after being obtained.","Fixed a progression stop in the Duviri Shrine Puzzle objective if players are pulled away mid-puzzle to a side objective (ex: Kullervo encounter or a side Undercroft portal).","Fixed Komi transmissions in Duviri being heard by all players even if they were not playing.","Fixed cases of Scaldra Harbingers teleporting to new locations in Solstice Square missions in Höllvania.","Fixed animation issues if the player is grabbed by the Ropalolyst while on an Atomicycle.","Fixed a loss of function if Transference is activated upon entering an Archwing gameplay zone in Railjack missions.","Fixed Extraction appearing to be available after 1 Dig in Arbitration Excavation missions (despite not actually being able to extract until 2 Digs are completed).","Fixed Mobile Defense terminals in the Zariman losing some textures when activated.","Fixed cases of pickups disappearing if held while using an Archwing Launcher (notably the Thrax Toxin in Plague Star bounties).","Fixed held jump inputs causing Wall Jumping to break.",{"t":"This bug has in the past caused confusion for some players during the Advanced Movement tutorial.","d":1},"Fixed Front Artillery dealing zero damage to Grineer Crewships if the engines are struck while disabled.","Fixed cases of Offerings progress incorrectly stopping until another enemy enters its radius in Shrine Defense missions.","Fixes towards Nidus' Ravenous not moving with the elevator in Ascension.",{"t":"Note: some of the ability VFX still linger in its casting location.","d":1},"Fixed Corpus Amalgam enemies getting stuck inside terrain in Io (Jupiter) missions.","Fixed the wrong entry animation being shown when boarding a Grineer Crewship in Railjack missions.","Fixed only loading into the Outpost tileset when starting The Index from the Dojo or a Relay.","Fixes towards Titania not riding Orokin or Derelict elevators while in her Razorwing form.","Fixed the Ember Specter's Inferno being able to target invisible players in Saturn Junction.","Fixed a rare case of the door opening animation not playing in Isolation Vault Bounties in Deimos.","Fixed a rare case of the Frictionless (friction is greatly reduced for Tenno) Penance in Descendia not ending properly.","Fixed Kuva Defectors getting stuck while attempting to make their way to Med Boosters in Defection missions.","Fixed Mesa Junction boss' first attack disarming player despite being out of range."]},{"title":"Uranus Proxima Fixes","items":["Fixed the markers on the cargo needing to be destroyed in the Scoria's Angel mission not properly fading while aiming.","Fixed the Last Mission Results from the pause menu not appearing after completing The Kuva Wytch and Scoria's Angel missions.","Fixed inactive hack console panels glowing orange (as if it's being hacked) in the Scoria's Angel and Kuva Wytch missions.","Fixed cargo boxes having collision after being shot off of the ship, causing Railjack to bounce off of them in the Scoria's Angel mission.","Fixed personal Railjack's tints not being respected if they were set to default when doing The Kuva Wytch or Scoria's Angel missions.","Fixed Captains in The Kuva Wytch sometimes spawning as a headless Ember.","Fixed Ryoku not attacking boarding parties in The Kuva Wytch Railjack missions.","Fixed being able to see through the floor in The Kuva Wytch mission while flying around in Titania's Razorwing.","Fixed dying and respawning in the Railjack segment of Uranus Proxima missions causing player usernames to be replaced with Crew names.","Fixed players occasionally spawning in space after the Orowyrm transition in The Kuva Wytch thereby halting progression."]},{"title":"Cosmetic Fixes","items":["Fixed the Drippy Sugatra not moving as expected when moving your Warframe in the Arsenal.","Fixed the Nepheri's glowing VFX persisting despite changing weapon skins.","Fixed Vena's Gemini Skin's jacket appearing deformed in some areas.","Fixed the Wirematrix Ephemera incorrectly applying its VFX pattern to other light sources and flickering when equipped on the Drifter.","Fixed certain Ephemeras (ex: TennoCon 2021, Waveform, Wirematrix, Dog Days) changing Follie's default energy color.","Fixed Signas appearing in certain quest cutscenes.","Fixed Vena's Hairstyle not fully respecting player tints in its Market diorama.","Fixed Yareli's tints temporarily being reset upon mounting Merulina if Zenurik is her active Focus School.","Fixed being able to create an unholy chimera of Operator and Drifter after swapping between the two in the Backroom Focus menus.","Fixed Mesa Heirloom missing Peacemaker aim VFX if tints are set to default.","Fixed the Zygiella Ephemera using the Warframe's energy tint.","Fixed the Vena and Ryoku Gemini Skins using on-kill voice lines when petting Companions.","Fixed a missing rifle animation in Mesa's Agile Animation set.","Fixed Hildryn's reload animation being broken for dual pistols.","Fixed offset issues with the Jotunheim Syandana on Wisp and the Marie Gemini Skin.","Fixed minor cloth and fitment issues on various Operator and Drifter suits.","Fixed the Maulleus Hammer Skin's animation not spinning the full 360 degrees.","Fixed the Kaithe summoned by Dagath's Noble Animation set incorrectly showing wings on summoning."]},{"title":"UI Fixes","items":["Fixed the Tektolyst Artifact Upgrade screen causing sorting to be reset in other menus.","Fixed the Boon Selection UI overlapping with the rewards popup if you choose a boon too quickly.","Fixed Nokko's Reroot Rampage not specifying a unit of measurement in the Explosion Radius stat.","Fixed Uriel having broken animations in the Pause menu if it is opened while Infernalis is active.","Fixed Arbitration Drones not displaying damage numbers if hit by a chained beam weapon (i.e. the Tenet Cycron).","Fixed Warframes released prior to Oraxia not having the updated UI icons for Status in their Upgrade and Ability Menus.","Fixed Lato appearing twice when in the Lato Incarnon Genesis UI for The Circuit.","Fixed formatting of large numbers in certain places in the UI.","Fixed the Drifter Customization Menu UI being incorrectly offset when using a controller in the Duviri Paradox quest.","Fixed Chat Link not displaying stats on Incarnon weapons with Mods equipped.","Fixed a rare case of Clients seeing a controller button instead of the Power Cell icon during Excavation on the Orb Vallis.","Fixed Menu UI overlapping when the Operator Remaster popup appears while a player has a high priority Inbox message waiting.","Fixed player waypoints in Dojos not being removed for squad members when removed by the owner.","Fixed improper wrapping of the reward reset text in the Weekly Initiatives section of the Clan Menu UI for various languages.","Fixed enemy faction displaying incorrectly when there are multiple missions on the same node.","Fixed the initial pop-up for donating decorations and resources to the Clan Vault in the Dojo asking players for the amount they want to \"sell\" instead of \"contribute\".","Fixed using the Chat settings gearwheel causing screens to overlap while looking at another screen such as the Market or Navigation.","Fixed player names not being correctly displayed in the hover popup of the Inbox UI.","Fixed the Chat UI filter label incorrectly displaying a filter code instead of the applied filter label.","Fixed a loss of function upon re-entering the Customize HUD Colors menu after changing a tint.","Fixed the wrong Revive button callout after dying during a Railjack mission.","Fixed the Acrid incorrectly having a second damage stats section in the Arsenal UI.","Fixed Sonicor displaying incorrect Status Chance in the Arsenal.","Fixed Nightwave Act complete pop-ups sometimes not appearing after a series of Nightwave Act notifications.","Fixed a rare case of a default Excalibur falling through the Market screen after idling on a Market search that provided no results.","Fixed a rare case of players being unable to see anything on the Buy Platinum screen in the Market.","Fixed cases of stacking exit confirmation popups when closing the Epic client.","Fixed the All tab remaining highlighted the Mods Trading Menu after toggling Hide Equipped.","Fixed additional cases of being able to equip forbidden equipment combinations via the Navigation Loadout menu.","Fixed cases of new Alerts, Invasions or other events not appearing in real time while idling in the Navigation Menu.","Fixed offset VFX when Polarizing a Mod Slot using Forma.","Fixed Railjack Battle Mods not displaying stat information when Fused via the Plexus console in the Orbiter.","Fixed tabs being misaligned in the Invite screen when using a controller.","Fixed the \"Install a Focus Lens\" pop-up re-appearing after swapping between the Focus Upgrade menu and Arsenal.","Fixed your Warframe's icon in the Arsenal not updating after changing skins (most notably with Gemini Skins).","Fixed HUD popup indicating Energy is being received still occurring while player is AFK (UI only issue).","Fixed Inventory grid overlap with search and sort controls in UI.","Fixed UI hang after clicking the left arrow in the chat window."]},{"title":"Quest Fixes","items":["Fixed memory fragments from the Silver Grove quest not being unlocked in the Codex after quest completion.","Fixed Veso's Shield Drone getting stuck when crossing the halfway between spawn areas in the first stage of The New War quest.","Fixed a rare case of the Operator/Drifter being unable to redirect the Lotus' beam during a stage of The New War quest.","Fixed crates and resource deposits spawning into walls/floor in the Jade Shadows: Constellations quest.","Fixed a smoke VFX in the Jade Shadows: Constellations quest missing the machine it is emitted from.","Fixed a hologram in the Jade Shadows: Constellations quest being off-center.","Fixed custom HUD elements appearing during a transition between stages in The Old Peace quest if the equipped Warframe has a custom HUD.","Fixed enemy Chroma having difficulties targeting the player in The New Strange quest.","Fixed the Side Offset camera position being too close to the Archwing during a specific stage in The War Within quest.","Fixed subtitles in the Sleeping in the Cold Below section of the Call of the Tempestarii quest having a black background after a line break.","Fixed a rare case of spawning in Teshin's cell if players hit a teleport volume while in Transference during The Teacher quest.","Fixed a progression stop caused by the Operator having their Warframe loadout instead of their Amp while in The War Within quest.","Fixed the timing of Vor's Prize post-quest transmissions.","Fixed rare cases of players getting stuck in The Teacher quest with not enough Stormbringer Mods to dissolve."]},{"title":"Level Design & Environment Fixes","items":["Fixed the Zanuka Arena Simulacrum having areas where players could fall out of bounds.","Fixed a small gap in the ceiling wall of Uranus Defense tile, which could cause players to become stuck.","Fixed the terrain in the Grineer Settlements tileset having some disconnected ground sections.","Fixed the terrain near an excavator site in the Duviri Circuit being see through.","Fixed some Solaris Workers walking into objects or getting stuck during their patrols.","Fixed texture flickering on various walls of Vena's capital ship in the Kuva Wytch mission.","Fixed bad reflections and flickering on glass in the Captain Vor boss fight mission.","Fixed a floating lamp next to the spawn point in Cetus.","Fixed texture flickering issues in Marie's Room Captura Scene.","Fixed the Deck 12 doors appearing duplicated and flickering when passing through them.","Fixed several map holes in the H-09 Efervon Tank Assassination second phase arena.","Fixed a floating crate in the Plains of Eidolon.","Fixed a portion of the floor in a Corpus Ship tile missing collision, allowing players to fall through.","Fixed aggressive flickering when approaching a specific window in a Corpus Outpost tile.","Fixed a map hole in the second stage of the H-09 Efervon Tank arena.","Fixed flickering on a Spy Vault door in the Grineer Settlement tileset.","Fixed a Somachord spawning in the environment in the Infested variant of the Grineer Asteroid tileset.","Fixed an erroneous decoration blocking one of the hallways into the Dry Dock.","Fixed a lighting issue next to the Vessel platform in the Dry Dock.","Fixed being able to get stuck exiting Submersible Archwing in a specific Grineer Sealab tile.","Fixed missing environment details on small moving cover pillars in an Orokin Moon tile.","Fixed texture flickering inside of Corpus ship in Railjack missions.","Fixed texture flickering in the Corpus Ship tileset.","Fixed a hole in the Plains of Eidolon map above The Seethe.","Fixed erroneous object in one of the Dry Docks doorways.","Fixed map hole in Sargas Ruk's arena."]},{"title":"Miscellaneous Fixes","items":["Fixed the camera unintentionally spinning after exiting the Customize Controller Menu screen.","Fixed the Paris Abra Skin needing to be owned to be chatlinkable.","Fixed some Auxiliary items not being chatlinkable.","Fixed Lettie's eyes in Transmissions looking up instead of forward.","Fixed the cursor speed being slower on higher resolutions when using the D-Pad of the controller.","Fixed the downed SFX (heartbeat) looping endlessly after loading into a different level.","Fixed line break issues in the launcher text when set to Traditional or Simplified Chinese.","Fixed being able to make progress towards \"Hai-Luk's Wholesaler\" Honoria (awarded for catching 10 different Rare of Legendary fish) with non-rare fishes.","Fixed Baruuk Prime's arms clipping through his legs during the Meditation Emote.","Fixed outlines being added to Dojo Tributa decorations while TAA is enabled.","Fixed not completing the Counter Intelligence challenge despite solving a Cipher within 5 seconds.","Fixed a function loss when creating an account via Steam on the Steam Deck resulting in no account being created.","Fixed the game client only recognizing the first controller if multiple controllers are active.","Fixed Melee weapons having Electricity VFX applied when wielded by Volt.","Fixed Kaithe wings being duplicated during Duviri loading screens.","Fixed Vena using the incorrect transmissions when she is a member of your Crew.","Fixed incorrect stats in Nako Xol's Codex entry.","Fixed the Bladeswarm Lich's Codex entry using the incorrect icon.","Fixed a rare case of the Drifter being invisible in the Höllvania Central Mall.","Fixed missing Amp and restricted movement when using Transference in the Orbiter Captura Scene.","Fixed being unable to sell an Aura Mod if it was equipped on Sevagoth's Shadow while Sevagoth was subsumed to the Helminth.","Fixed inadvertently fusing multiple copies of a Mod if a player spams the confirmation button on a controller.","Fixed icons in Captura text boxes being transparent black regardless of the tint settings.","Fixed the Velox Prime's firing VFX being misaligned while on a K-Drive or Merulina.","Fixed various minor spelling errors and inconsistencies across game text.","Fixed Tenet Ferrox's reload SFX playing when jumping with it equipped.","Fixed the Grineer Galleon Scene being foggier than the actual tileset.","Fixed the Conquera 2025 Community Fusion Display appearing backwards in its diorama.","Fixed Dante holding Noctua upside down in his Ability diorama.","Fixed Surge Eximus missing ground and lightening VFX after the first attack.","Fixed damage number customization pop up showing up after The Teacher quest instead of after dealing tons of damage as intended.","Fixed camera motion continuing while previewing a decoration.","Fixed intro cutscene playing when loading into the Deepmines Caves Captura scene.","Fixed some tree decorations having incorrect wind overrides in the Dojo.","Turned down Ortholyst's death SFX.","Fixed Tenno and Zariman glass decorations flickering when partially covered.","Fixes towards \"Auto\" upscaler quality setting for DirectX 12.","Fixed game only recognizing the first connected controller and not a second with Steam Input.","Fixed Zephyr's Airburst missing VFX for Clients.","Fixed Fables & Frontiers rank titles not being localized.","Fixed sinking through floor after deploying Med-Tower Air Support.","Fixed Tauron Strikes animations being misaligned.","Fixed loss of function when attempting to trade if they have Personal Platinum.","Fixed players being able to equip a Riven Mod without completing its challenge first.","Fixed Arcane Pistoleer having a file path description.","Fixed Clients getting a \"session unavailable\" popup when loading into a Dojo from another player's Orbiter.","Fixed being able to place decorations on top of floor medallions in the Transference room in the Orbiter/Drifter Camp.","Fixed a bug where Voracious Metastasis continued healing after its duration ended.","Fixed player camera causing decorations to not be placeable in Base of Operations.","Fixed bug with Specter death VFX."]},{"title":"Crashes & Script Error Fixes","items":["Introduced a more robust fix for Surge Eximus causing Clients to crash if spawned as certain units.","Fixed a script error related to Sirius & Orion in the Grineer Sealab tileset.","Fixed crash when spawning Bloodfrenzy enemies in the Simulacrum.","Fixed script error in Descendia.","Fixed a script error related to the Squad Vote Menu.","Fixed a crash related to NVIDIA PhysX.","Fixed a script error when picking up Amphors in Alchemy missions.","Fixed a rare crash when transitioning from a Hub/Dojo to a mission.","Fixed a crash when exiting the game after changing the Orbiter's Scene.","Fixed a crash when joining a mission in progress from the Sanctum Anatomica.","Fixed a crash related to the Techrot Babau's tentacle ability.","Fixed a crash in a Steel Path Perita Rebellion mission if the Prime Vanguard was the chosen Recall target.","Fixed a case of the Client crashing if they swapped between Sirius & Orion during a mission loading cinematic.","Fixed an edge case where returning after minimizing or alt-tabbing may crash on the Epic client.","Fixed a script error related to Unariu Focus Abilities.","Fixed a script error caused by enemies dying in The Perita Rebellion missions.","Fixed a script error related to Enigma discs in Duviri.","Fixed a script error when crafting the Jahu Gargoyle during a replay of The Whispers in the Walls quest.","Fixed script error in Descendia.","Fixed script error when equipping a weapon.","Fixed a script error related to Uriel's Infernalis Ability.","Fixed a script error related to casting Wellspring and then Jade Stars in Railjack missions.",{"p":"For list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1523875-known-issues-iceblade-of-narin/"}]}]}]},{"slug":"43-5-4","version":"43.5.4","kind":"hotfix","title":"Amir's Shockwave: Hotfix 43.5.4","url":"https://www.warframe.com/en/patch-notes/pc/43-5-4","forum":"https://forums.warframe.com/topic/1520771-amir%E2%80%99s-shockwave-hotfix-4354/","date":null,"dateSource":null,"tldr":"10 fixes.","fixes":10,"changes":0,"highlights":[],"mentions":[{"name":"Baruuk","kind":"Warframe","n":1},{"name":"Yareli","kind":"Warframe","n":1}],"parts":[{"title":"Amir's Shockwave: Hotfix 43.5.4","sections":[{"title":"Fixes","items":["Fixed lighting in the Backroom causing various metallic items to appear significantly darker than before.","Fixed Yareli being unable to initiate Last Gasp if Merulina had died before Last Gasp was triggered.","Fixed Surge Eximus becoming braindead after being Silenced mid-sprint.","Fixed Tempera Amp Skin causing Operator Amps with an Alt-Fire to sometimes not respond to Alt-Fire inputs or the Fire Manual Trigger Weapons Continuously toggle.","Fixed DJ Shockwave's transmissions and radio broadcasts being a little too loud.","Fixed performance issues caused by Arthur's Exalted Blade and Quincy's Neutralizer in the special Fables & Frontiers mission.","Fixed performance issues related to Surge Eximus electricity attacks.","Fixed Daiku and Daiku Prime's animations being broken with certain bow skins equipped.","Fixed a script error when customizing loadouts.","Fixed a crash related to Baruuk's Elude.",{"p":"For list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1519687-known-issues-amirs-shockwave/"}]}]}]},{"slug":"43-5-3","version":"43.5.3","kind":"hotfix","title":"Amir's Shockwave: Hotfix 43.5.3","url":"https://www.warframe.com/en/patch-notes/pc/43-5-3","forum":"https://forums.warframe.com/topic/1520640-amir%E2%80%99s-shockwave-hotfix-4353/","date":null,"dateSource":null,"tldr":"Surge Eximus. 13 fixes, 5 other changes.","fixes":13,"changes":5,"highlights":["Surge Eximus"],"mentions":[{"name":"Athodai Prime","kind":"Weapon","n":1},{"name":"Banshee","kind":"Warframe","n":1},{"name":"Hildryn","kind":"Warframe","n":1},{"name":"Vectis","kind":"Weapon","n":1}],"parts":[{"title":"Amir's Shockwave: Hotfix 43.5.3","sections":[{"title":"Changes","items":["Nightwave Radio now plays from the Nightwave console in the Backrooms if the Nora Night Volume slider is not set to zero.","Updated the description of Athodai Prime's unique trait Overdrive to specify it triggers on weakpoint kills (previously said headshot).","Ally Gemini Skin voice lines are now affected by the Enemy & Ally Combat Volume slider in the Advanced Sound Effects Mixer.","Improved handling of corrupt shader caches, which could result in crashing."]},{"title":"Surge Eximus Changes & Fixes","items":["Surge Eximus' electricity ability now has a maximum casting range of 50m.","Fixed additional cases of Surge Eximus units causing Clients to crash in Uranus Proxima and Deep Mines missions.","Fixed the Surge Eximus' electricity ability not being affected by Banshee's Silence.","Fixed the Surge Eximus' electricity ability dealing damage across two ticks instead of one.",{"t":"The actual damage output from the electric shocks is unchanged.","d":1},"Fixed Surge Eximus being able to target invisible players."]},{"title":"Top Fixes","items":["Fixed Tempera Amp Skin causing Drifter Amps with an Alt-Fire to sometimes not respond to Alt-Fire inputs or the Fire Manual Trigger Weapons Continuously toggle.",{"t":"Also fixed misaligned VFX when firing.","d":1},{"t":"Known Issue: This issue persists for Operators with the Tempera Amp Skin equipped. We recommend using a different Amp skin for the time being if you are affected.","d":1},"Fixed Hildryn being able to stack Void Relic opening Ability Strength buffs if it was triggered while she was in Aegis Storm.","Fixed the Vectis (Prime) not having a fully reloaded magazine after exiting Incarnon Form."]},{"title":"Fixes","items":["Fixed being able to drag tints into a Signa's X and Y axis setting in the Appearance menu.","Fixed metallic elements in the Backrooms appearing black for systems with low graphics settings.","Fixed various minor decoration issues in Höllvandeim, including a poster not displaying properly, and Lettie's seat missing her lumbar support pillow.","Fixed being unable to place Dojo Decorations in the portal's dissolve range of the Courtier's Bliss and Harbinger's Pass Dojo Rooms.","Fixed Kubrows and Kavats having a duplicate listing of their default fur pattern.","Fixed a crash when interacting with the KIM system.",{"p":"For list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1519687-known-issues-amirs-shockwave/"}]}]}]},{"slug":"43-5-2","version":"43.5.2","kind":"hotfix","title":"Amir's Shockwave: Hotfix #2","url":"https://www.warframe.com/en/patch-notes/pc/43-5-2","forum":"https://forums.warframe.com/topic/1520019-amir%E2%80%99s-shockwave-hotfix-4352/","date":null,"dateSource":null,"tldr":"13 fixes, 3 other changes.","fixes":13,"changes":3,"highlights":[],"mentions":[{"name":"Cyte-09","kind":"Warframe","n":1},{"name":"Vinquibus","kind":"Weapon","n":1}],"parts":[{"title":"Amir's Shockwave: Hotfix #2","sections":[{"title":"Changes","items":["Removed the blocking volume around the Fables & Frontiers table in the Dominion of Höllvandeim Scene."]},{"title":"Top Fixes","items":["Fixed various Amps with Alt-Fire sometimes not responding to Alt-Fire inputs or to the Fire Manual Trigger Weapons Continuously toggle.","Fixed more Surge Eximus units causing Clients to crash, notably in missions in the Albrecht's Laboratories tileset.","Fixed damage of multiple Electric Ammo Packs from Cyte-09's Resupply stacking with another.","Fixed the Raptor fight not progressing after dropping an explosive Power Cell into a Gravity Conveyor while in Transference.","Fixed Clients not hearing the Surge Eximus' ability SFX."]},{"title":"Fixes","items":["Fixed DJ Shockwave's Radio transmissions in the Orbiter not being randomized.","Fixed the POM-2 not displaying an exclamation mark if there are new Fables & Frontiers KIM messages.","Fixed another case of being able to equip the Vinquibus in only one weapon slot, or equip disallowed weapons on Companions.","Fixed duplicate Höllvandeims appearing in the Fast Travel wheel after entering and exiting the Protoframes category.","Fixed a script error when interacting with Eidolon Lures in the Plains of Eidolon if the mission was joined in progress.","Fixed a rare script error in The Descendia that resulted in The Shrine Defense mode not working properly.","Fixed a crash related to Moa Companions."]},{"title":"Performance Changes & Fixes","items":["Further improved handling of corrupt shader caches in DirectX 11.","Made systemic micro-optimizations to DirectX 11 rendering.","Fixed spotloading when using a Kubrow or Kavat in Höllvania missions.",{"p":"For list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1519687-known-issues-amirs-shockwave/"}]}]}]},{"slug":"43-5-1","version":"43.5.1","kind":"hotfix","title":"Amir's Shockwave: Hotfix 43.5.1","url":"https://www.warframe.com/en/patch-notes/pc/43-5-1","forum":"https://forums.warframe.com/topic/1519795-amir%E2%80%99s-shockwave-hotfix-4351/","date":"2026-08-12","dateSource":"patch notes","tldr":"10 fixes.","fixes":10,"changes":0,"highlights":[],"mentions":[{"name":"Cronus","kind":"Weapon","n":1},{"name":"Sirius & Orion","kind":"Warframe","n":1},{"name":"Talons","kind":"Weapon","n":1},{"name":"Xaku","kind":"Warframe","n":1}],"parts":[{"title":"Amir's Shockwave: Hotfix 43.5.1","sections":[{"title":"Fixes","items":["Fixed Clients crashing when encountering certain Surge Eximus units.","Fixed the Cronus Blueprint only dropping once from the Vor fight.",{"t":"Now it's a guaranteed drop each time you defeat Vor.","d":1},"Fixed Sirius' Light Sanctuary VFX being invisible for players with Particle Quality set to Low (or on platforms without access to this setting).","Fixed Vena not using her Talons and targeting enemies as an on-call Crew member.","Fixed some cases of \"Fable Master\" appearing instead of the intended \"Fablemaster\" in Amir's Fables & Frontiers.","Fixed Amir forgetting to clean up a few items from the internet cafe when setting up for Höllvandeim in the Höllvania Central Mall.","Fixed minor performance issues related to Orion's Black Hole's VFX.","Fixed Orion's Astral Shell ability's VFX sometimes appearing white upon recast.","Fixed various script errors related to Sirius & Orion's Celestial Clash.","Fixed a script error related to Xaku's The Lost ability.",{"p":"For list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1519687-known-issues-amirs-shockwave/"}]}]}]},{"slug":"43-5-0","version":"43.5.0","kind":"update","title":"Update 43.5: Amir's Shockwave","url":"https://www.warframe.com/en/patch-notes/pc/43-5-0","forum":"https://forums.warframe.com/topic/1519695-update-435-amirs-shockwave/","date":"2026-08-12","dateSource":"patch notes","tldr":"Fables & Frontiers: Running Late (Mini Kim Adventure); Nightwave Mix: Amir's Shockwave; Baruuk Shaoshi Collection; Tennogen: Fables & Frontiers. 104 fixes, 100 other changes.","fixes":104,"changes":100,"highlights":["Fables & Frontiers: Running Late (Mini Kim Adventure)","Nightwave Mix: Amir's Shockwave","Baruuk Shaoshi Collection","Tennogen: Fables & Frontiers","Memetica Glyph Pack III","Performance & Optimizations"],"mentions":[{"name":"Sirius & Orion","kind":"Warframe","n":16},{"name":"Baruuk","kind":"Warframe","n":10},{"name":"Jade","kind":"Warframe","n":7},{"name":"Kullervo","kind":"Warframe","n":5},{"name":"Oraxia","kind":"Warframe","n":5},{"name":"Harrow","kind":"Warframe","n":3},{"name":"Mesa","kind":"Warframe","n":3},{"name":"Nokko","kind":"Warframe","n":3},{"name":"Scindo","kind":"Weapon","n":3},{"name":"Glaive","kind":"Weapon","n":2},{"name":"Grimoire","kind":"Weapon","n":2},{"name":"Guandao","kind":"Weapon","n":2},{"name":"Sevagoth","kind":"Warframe","n":2},{"name":"Wisp","kind":"Warframe","n":2},{"name":"Arca Plasmor","kind":"Weapon","n":1}],"parts":[{"title":"Update 43.5: Amir's Shockwave","sections":[{"title":"","items":[{"p":"Image Description: A closeup of Amir's face in front of an electrified microphone in the opposite orientation of Nora Night's. A crackling border encloses the Amir's Shockwave logo as blue and purple arcs of electricity frame the image and Amir's headset."},{"p":"Get ready for a shakeup like you've never heard before! Amir Beckett of The Hex is cutting through the airwaves (and across space and time) to bring you a double-dose of 1999-themed content. Not only has he hacked Nora's airways by hosting his own remixed edition of a Nightwave Mix called Amir's Shockwave replete with never-before-seen Rewards, but he's also joining the rest of his Hex teammates for a unique KIM narrative adventure, Fables & Frontiers: Running Late. Read on to learn more!"},{"p":"Transcend the chaos of battle, Tenno… This interim update also delivers the Baruuk Shaoshi Collection! Featuring the Baruuk Shaoshi Skin, Rathan Sword & Shield Skin, Liania Signa and Neviti Ephemera. Get your hands on the new TennoGen: Fables & Frontiers, featuring six new creations from community artists - including the first TennoGen pieces for Kullervo and Oraxia, two brand new Signas, and more."},{"p":"This interim update also includes many changes and fixes (including code!). Some pesky issues such as frozen enemies despawning in Netracell missions, and Nokko's Reroot Rampage not triggering Archon Continuity or having its first bounce dealing damage have been addressed. We have also added a plethora of quality of life changes for the Nightwave system to make Acts more engaging and removed some longstanding pain points. We also have a dedicated Amir's Shockwave sub-forum to collect your feedback and bug reports to address in follow-up Hotfixes where we can."},{"p":"If any of the terms above are new to you, visit The Warframe Lexicon for Updates to learn more about Warframe's development cycle."}]},{"title":"Download Sizes","items":[{"p":"PC DirectX 11: ~248.94 MB"},{"p":"PC DirectX 12: ~250.68 MB"},{"p":"Image Description: Amir smirks while looking at us as he juggles three different dice in his left hand. Behind him is a large tabletop game setup complete with game pieces, dice, maps, and sheets. In the foreground is the logo for Fables & Frontiers."}]},{"title":"FABLES & FRONTIERS: RUNNING LATE (MINI KIM ADVENTURE)","items":[{"p":"Magic! Mayhem! Mystery! Play with Amir as your Fablemaster and the rest of the Hex in a six-day mini KIM text adventure of the popular table top roleplaying game! But be warned, all may not be well in Höllvandeim… Log into the KIM and join the Fables & Frontiers: Running Late campaign!"},{"p":"NOTE: This is a permanent addition to the KIM system! It is not tied to Amir's Shockwave Nightwave Mix rotation, meaning it can be experienced at any time once the prerequisites have been met."}]},{"title":"Prerequisites","items":[{"p":"In order to unlock Fables & Frontiers group chat in the KIM, you must have the following:"},"Complete The Hex Quest & The Hex Finale","Reach Rank 5 (Pizza Party) with The Hex Syndicate","Reach Chemistry Rank 5 (Close) with Amir in the KIM system"]},{"title":"How to Begin","items":[{"p":"Before embarking on the KIM Fables & Frontiers: Running Late adventure, you must first create your character sheet! Here's how:"},"Once you have completed all of the listed prerequisites, travel to Höllvania Central Mall from the POM-2 map.","Make your way up to the second floor of the mall to the \"Höllvandeim\" room (read dedicated section to learn more).",{"t":"You can fast travel to Höllvandeim from the pause menu and from the quick access wheel.","d":1},"Ring the bell on the table to call in Amir - he'll appear with much speed and urgency!","Interact with Amir to put together a character sheet via dialogue options. You'll choose your character class and their weaponry/abilities!","Return to the POM-2 to begin the campaign in the KIM! Once you have completed your character sheet and Amir has run off to prepare the campaign, you can return to your POM-2 to begin the campaign in the KIM system.",{"p":"Image Description: Höllvandeim - a decorated room evoking magic and mystery with desks set up for participants. From left to right we can see the fablemaster's table with their screen, rule book and notes, then the main table complete with a large map, game pieces and seating for six people."}]},{"title":"Höllvandeim","items":[{"p":"Located on the second floor of the Höllvania Central Mall you will find what was once the cafe has been taken over completely by Amir and rebranded it as \"Höllvandeim\" for his campaign. Gotta love a Fable Master that really prioritizes player immersion! Wonder where he got all the Höllars for these decorations…"},{"p":"Ring the Bell to Summon Amir!"},{"p":"A service bell sits on the table near the Fablemaster's station - ring it to summon Amir to the table! The man will appear with great speed and urgency at your call."},{"p":"Image Description: Amir stares off into the distance as he stands behind a desk with a pizza box used as his fablemaster screen. To the right in the foreground is a service bell placed atop an upside down popcorn bucket of sorts."},{"p":"Interact with Amir to gain access to his wares and other things we won't spoil at this time!"},{"p":"NOTE: Amir leaves the Arcade downstairs when rung to Höllvandeim and returns once you leave the room. If he's downstairs, simply ring the bell again to call him back up. Alternatively, you can jump to him upstairs (using the Höllvandeim option) or downstairs (using the Protoframe, Amir option) using the quick access wheel. Such speed!"},{"p":"Amir's Fables & Frontiers Store"},{"p":"Amir has many Fables & Frontiers goodies and more available for Standing with the Hex in Höllvandeim! Ring the bell to summon him upstairs and peruse his wares."},{"p":"For the sake of not spilling all the beans on the kind of mayhem you may get yourself into in the campaign, we chose to not list out each and every unique item in the shop in detail. You'll just have to complete the campaign to see for yourself!"},"Fables & Frontiers character Glyphs, one for each Hex member, by community artist ZliDe","Character Sheet Posters, one for each Hex member, by community artist Brighan","Fables & Frontiers Character Posters, one for each Hex member, by community artist Brighan","Several decorations based on the Fables & Frontiers adventure","Several Glyphs featuring foes you may encounter in the Fables & Frontiers adventure","A new Somachord track by On-lyne titled \"Running Late\"",{"p":"Image Description: Promotional poster for On-lyne's new track Running Late with the members running. From left to right are: Harddrive, Packet, Zeke, Drillbit, and DJ RoM."},"A Fables & Frontiers-themed Somachord track titled \"A Byte-sized Adventure\"","Running Late Album Cover Display and Promo Poster","Dominion of Höllvandeim Captura Scene","The following returned rewards from Nightwave Mix Vol. 8:",{"t":"Big Bytes Pizza Sigil","d":1},{"t":"Nightwave Livery","d":1},{"t":"Lillian Floof","d":1},{"t":"Jillian Floof","d":1},{"t":"Battlecry Ink","d":1},{"t":"Boltor Kubrow Armor","d":1},{"t":"Tammpet Sugatra","d":1},{"t":"Aoi Origami Glyph","d":1},{"t":"Liset Domestik Drone","d":1},"And so much more!!"]},{"title":"What to Expect","items":[{"p":"Amir is the Fablemaster, the man at the helm responsible for organizing the campaign and writing the story! He is hosting his latest campaign \"Running Late\" entirely from a new KIM group chat with you and the Hex, which is available to access from the new Fables & Frontiers Batch tab."},{"p":"Image Description: Screenshot of the KIM UI with the Fables & Frontiers Batch tab selected. An unread message from H16h V0l7463 reads \"HEY HEY ALL!!\"."},{"p":"You and the Hex will join the group chat and play as your Fables & Frontiers characters:"},"Arthur plays as Cedric Dawnsong","Aoi plays as Morohime Ichigeki","Eleanor plays as Sanguina Kallisti","Lettie plays as Ixchel Balam","Quincy plays as Lord Reyland Kingsacre",{"p":"Image Description: Screenshot of the Kinemantik Instant Messenger showing the initial conversation from the Fables & Frontier campaign."},{"p":"There are six days of adventuring ahead of you, with one session available per day. Amir needs time to plan out what the adventurers will encounter next, so check back after the Daily Reset (0:00 UTC) to continue the story with the Hex!"},{"p":"This is intended to be a fun role-playing adventure, and for that reason there is no Chemistry earned from the conversations had in the Fables & Frontiers group chat."},{"p":"Somewhere along the way in your adventure with the Hex, you will encounter a new enemy… the Surge Eximus! This speedy Eximus unit targets foes with a triple strike of devastating Electric Damage. But where oh where did it come from…"}]},{"title":"Rewards","items":[{"p":"Completing the Fables & Frontiers campaign will reward you with the following:"},"Fables & Frontiers: Running Late Poster (Inbox reward)",{"p":"Image Description: Poster depicting members of The Hex as a party of fantastical characters such as a Warlock, Knight, and Sorcerer. Looming over them in an ominous manner appears to be Amir."},{"t":"Cover art for the Fables & Frontiers: Running Late adventure. Artwork by community artist Nikki Dawes.","d":1},"Access to Replay KIM Campaign",{"t":"Like all other KIM batches, you can reset your memories with Fables & Frontiers from the Digital Grimoire to replay the adventure! You may also do this by talking to Amir. Doing so will erase all conversation history from the Fables & Frontiers batch and allow you to take another stab at the campaign.","d":1},{"p":"Image Description: Screenshot of the Digital Grimoire UI with Amir's Shockwave Fables & Frontiers selected. The option to reset your memories is shown with a yellow Commit button visible."},{"t":"After resetting your memories you may choose to replay your experience by selecting the same character as before, or you can explore the campaign through the lens of a different character by choosing another one instead.","d":1},{"t":"Please note that resetting your memories will temporarily remove access to Amir's Fables & Frontiers Store until you talk to him and create a character sheet.","d":1},{"p":"Image Description: A closeup of Amir's face in front of an electrified microphone in the opposite orientation of Nora Night's. A crackling border encloses the Amir's Shockwave logo as blue and purple arcs of electricity frame the image and Amir's headset."}]},{"title":"NIGHTWAVE MIX: AMIR'S SHOCKWAVE","items":[{"p":"BEGINS TODAY @ 11:30 AM ET"}]},{"title":"New Nightwave Tier Rewards","items":[{"p":"With Amir's Shockwave, complete Nightwave acts to net these new (and returning) tier rewards."},{"p":"Like previous editions of Nightwave, we have duplicate protection for items you already own. You will be compensated with Amir's Shockwave Creds instead of the previous unlocked reward."},{"p":"Augment Mod Stats shown at Max Rank."},{"p":"Image Description: The Drifter poses next to an Atomicycle while wearing the Kaneshell Atomicycle Regalia. The orange and black biker suit is accentuated with a white trim on the helmet. Note: The Barracuda Atomicycle Livery pictured is not included in the Regalia."}]},{"title":"Kaneshell Atomicycle Regalia","items":[{"p":"Slide into this biker outfit of the new millenium. Fitted for the Drifter and Operator. Includes the jacket, helmet, leggings and sleeves."}]},{"title":"Teisatz Oculus","items":[{"p":"A stylish piece of new age tech with over 9000 different features."}]},{"title":"Globakk Syandana","items":[{"p":"Only the most highly trained - or highly reckless - Scaldra dare to wear this portable Efervon container."}]},{"title":"Come Here Emote","items":[{"p":"An encouraging display for a beloved companion."},{"p":"Equip this emote using the Gear Wheel tab in the Arsenal."}]},{"title":"Entropic Color Palette","items":[{"p":"A selection of colors for when the usual upbeat charm just won't do."}]},{"title":"Submeower Decoration","items":[{"p":"Don't ask where the power cord goes."}]},{"title":"Prototype Shock Coils (EFV-8 MARS)","items":[{"p":"Adds +90% Electric Damage, and shots have a 20% base chance to apply extra Electric status independent of modded damage types"}]},{"title":"Overpressured Rounds (EFV-5 JUPITER)","items":[{"p":"Rifle kills add 120% Falloff Distance and decrease Spread for next attack with Buckshot. Buckshot kills restore 50% of the current Magazine."}]},{"title":"Drippy Floof","items":[{"p":"In case of waterworks, this cuddly Drippy Floof is here to help."}]},{"title":"Drippy Keychain Sugatra","items":[{"p":"Show off your drip with this drippy Drippy Sugatra."}]},{"title":"Drippy Dog Days Glyph","items":[{"p":"The K.O.L. Summer update includes this new Drippy to help you cool off and enjoy your summer."}]},{"title":"90's Kid Honoria","items":[{"p":"|NAME| 90's Kid"}]},{"title":"Cred Offerings Store Updates","items":[{"p":"Amir's takeover brings many updates to the Cred Offerings Store! Earn Amir's Shockwave Creds from the reward tiers and trade them in for both new and returning items. Let's take a look at some of the new revisions and adjustments below."}]},{"title":"Permanent Cred Offerings","items":[{"p":"The following rewards are now available at all times in the Cred Offerings Store - in other words, they are no longer part of the store rotations and are now permanent fixtures in the store. These are in addition to the existing permanent offerings, which remain unchanged."},"New to Cred Offerings: Nightwave Landing Craft Blueprint & Components (Engines, Avionics & Fuselage)",{"p":"Image Description: A Landing Craft ship with winged components on each side and two small \"tails\" angled outwards at the back. It features a deep purple body, light green emissives, and orange energy with a high gloss shine."},{"t":"We first introduced the Nightwave Landing Craft in Nightwave Series 3: Glassmaker and from there was rotated back into various Nightwave Mixes tier rewards. Instead of continuing to add it as a tier reward, we have instead decided to add its Blueprint and Components as a permanent addition to the Cred Offerings shop.","d":1},"Aura Mods",{"t":"Corrosive Projection","d":1},{"t":"Dead Eye","d":1},{"t":"Dreamer's Bond","d":1},{"t":"EMP Aura","d":1},{"t":"Enemy Radar","d":1},{"t":"Energy Siphon","d":1},{"t":"Holster Amp","d":1},{"t":"Infested Impedance","d":1},{"t":"Loot Detector","d":1},{"t":"Physique","d":1},{"t":"Pistol Scavenger","d":1},{"t":"Rejuvenation","d":1},{"t":"Rifle Amp","d":1},{"t":"Rifle Scavenger","d":1},{"t":"Shield Disruption","d":1},{"t":"Shotgun Scavenger","d":1},{"t":"Sniper Scavenger","d":1},{"t":"Sprint Boost","d":1},{"t":"Steel Charge","d":1},"Warframe Mods",{"t":"Deceptive Bond","d":1},{"t":"Power of Three","d":1},{"t":"Prism Guard","d":1},{"t":"Purifying Flames","d":1},{"t":"Purging Slash","d":1},{"t":"Recharge Barrier","d":1},{"t":"Rumbled","d":1},{"t":"Singularity","d":1},"Weapon Blueprints",{"t":"Ceramic Dagger Blueprint","d":1},{"t":"Dark Dagger Blueprint","d":1},{"t":"Dark Sword Blueprint","d":1},{"t":"Glaive Blueprint","d":1},{"t":"Heat Dagger Blueprint","d":1},{"t":"Heat Sword Blueprint","d":1},{"t":"Jaw Sword Blueprint","d":1},{"t":"Pangolin Sword Blueprint","d":1},{"t":"Plasma Sword Blueprint","d":1},"Weapon Skins Blueprints",{"t":"Arca Plasmor Solstice Skin Blueprint","d":1},{"t":"Atomos Solstice Skin Blueprint","d":1},{"t":"Atterax Desert-Camo Skin Blueprint","d":1},{"t":"Burston Solstice Skin Blueprint","d":1},{"t":"Cedo Daybreak Skin","d":1},{"t":"Corinth Solstice Skin Blueprint","d":1},{"t":"Cycron Solstice Skin Blueprint","d":1},{"t":"Dual Keres Solstice Skin Blueprint","d":1},{"t":"Dual Zoren Dagger-Axe Skin Blueprint","d":1},{"t":"Exergis Shock-Camo Skin Blueprint","d":1},{"t":"Falcor Shock-Camo Skin Blueprint","d":1},{"t":"Fragor Brokk Skin Blueprint","d":1},{"t":"Fulmin Solstice Skin Blueprint","d":1},{"t":"Galatine Solstice Skin Blueprint","d":1},{"t":"Glaive Daybreak Skin","d":1},{"t":"Gram Solstice Skin Blueprint","d":1},{"t":"Grinlok Desert-Camo Skin Blueprint","d":1},{"t":"Guandao Solstice Skin Blueprint","d":1},{"t":"Guandao Synoid Skin Blueprint","d":1},{"t":"Hek Desert-Camo Skin Blueprint","d":1},{"t":"Heuris Polearm Skin","d":1},{"t":"Ignis Solstice Skin Blueprint","d":1},{"t":"Karak Desert-Camo Skin Blueprint","d":1},{"t":"Lenz Solstice Skin Blueprint","d":1},{"t":"Marelok Desert-Camo Skin Blueprint","d":1},{"t":"Nukor Daybreak Skin","d":1},{"t":"Plinx Shock-Camo Skin Blueprint","d":1},{"t":"Pyrana Synoid Skin Blueprint","d":1},{"t":"Rubico Synoid Skin Blueprint","d":1},{"t":"Scindo Dagger-Axe Skin Blueprint","d":1},{"t":"Scindo Manticore Skin Blueprint","d":1},{"t":"Scindo Solstice Skin Blueprint","d":1},{"t":"Tatsu Solstice Skin Blueprint","d":1},{"t":"Tonkor Desert-Camo Skin Blueprint","d":1},"Wolf Beacon"]},{"title":"New Cred Offerings","items":[{"p":"We've added the following items into the Cred Offerings store rotations:"},"DJ Shockwave Sigil - A sigil commemorating when Amir took over the airwaves as DJ Shockwave.","DJ Shockwave Glyph - A glyph awarded to those who tuned in to Amir's takeover of the airwaves.","Frakta Shoulder Guard","Drifter Keeler Suit","Drifter Keeler Hood","Drifter Keeler Pants","Drifter Keeler Sleeves","Daybreak Emote","Daybreak Shoulder Plates","Daybreak Chest Plate","Daybreak Leg Plates","Vile Discharge (Embolist)","Sentient Surge (Ocucor)","Leaded Gas (Vesper 77)","Biotic Rounds (AX-52)"]},{"title":"General Cred Offerings Changes","items":["6 Weapon Augment Mods are now guaranteed in each rotation.","Added the following new sorting tabs to the store UI:",{"t":"Recovered Artifacts","d":1},{"t":"Contains permanent store resources (Kuva, Nitain Extract, Orokin Reactor/Catalyst, etc.) and blueprints (Nightwave Landing Craft & Vauban).","d":2},{"t":"Weapons & Weapon Cosmetics","d":1},"Removed a duplicate Clip Delegation from the Cred Offerings rotation."]},{"title":"New Nightwave Acts","items":["Daily Acts:",{"t":"Whole Arsenal - Get a kill with your Primary, Secondary and Melee weapons within 10 seconds.","d":1},{"t":"Artist - Customize a piece of equipment's colours.","d":1},"Weekly Acts:",{"t":"To Ashes - Dissolve an Arcane for Vosfor.","d":1},{"t":"Bow Offense - Kill 150 enemies with a Primary Bow.","d":1},{"t":"Rifle Offense - Kill 150 enemies with a Primary Rifle.","d":1},{"t":"Sniper Offense - Kill 150 enemies with a Primary Sniper Rifle.","d":1},{"t":"Shotgun Offense - Kill 150 enemies with a Primary Shotgun.","d":1},{"t":"Void Net - Collect 30 Void Traces.","d":1},"Elite Weekly Acts:",{"t":"Elementary, My Dear - Complete 3 successful Conversions in the Alchemy game mode.","d":1},{"t":"Going Down - Defeat Roathe in Descendia.","d":1},{"t":"Hold the Mushrooms - Collect 6 mushrooms from the Deepmines.","d":1},{"t":"Battle Hardened - Complete the Perita Rebellion with 6 or more orders completed.","d":1},{"t":"Spider Hunt - Complete an Isleweaver Duviri Mission.","d":1},{"t":"Treasure from the Past - Complete a Netracell.","d":1}]},{"title":"Nightwave Act Updates","items":[]},{"title":"Act Changes","items":["The Hunt is On (Daily)",{"t":"Previously: Find 5 Syndicate Medallions","d":1},{"t":"Changes:","d":1},{"t":"Increased required Syndicate Medallions from 5 to 10","d":2},{"t":"Changed from Daily to Weekly","d":2},"Earth/Venus/Zariman Bounty Hunter (Weekly)",{"t":"Previously:\"Complete x/3 different Bounties…\" on Earth/Venus or \"Complete x/4 different Bounties in the Zariman\".","d":1},{"t":"Changes:","d":1},{"t":"No longer requires different Bounties","d":2},{"t":"Changed Zariman Act from Weekly to Elite Weekly","d":2},"Now Boarding (Weekly)",{"t":"Previously: Complete 3 different K-Drive races in Orb Vallis on Venus or in Cambion Drift on Deimos","d":1},{"t":"Change: Reduced required K-Drive races from 3 to 1","d":1},"Eternal Guardian (Weekly)",{"t":"Previously: Complete 2 Void Armageddon missions","d":1},{"t":"Changes:","d":1},{"t":"Progress counts 2 Armageddon round completions instead of mission completions","d":2},{"t":"Changed from Weekly to Elite Weekly","d":2},"High Ground (Weekly)",{"t":"Previously: Complete 3 Void Flood Missions","d":1},{"t":"Changes:","d":1},{"t":"Progress counts 12 Ruptures Sealed rather than missions completions","d":2},{"t":"Changed from Weekly to Elite Weekly","d":2},"Finely Tuned (Weekly)",{"t":"Previously: Play 2 different Shawzin songs in Duviri","d":1},{"t":"Changes:","d":1},{"t":"Now only requires player to play 1 Shawzin song","d":2},{"t":"Updated the description to specify that it requires the Shawzin activity, not the Emote.","d":2},"Cache Hunter (Weekly)",{"t":"Previously: Find 6 caches across any Sabotage missions","d":1},{"t":"Changes:","d":1},{"t":"Caches found in non-sabotage missions will count towards progress","d":2},{"t":"Updated description and tip to make locations of eligible Caches clearer to players","d":2},"Perplexed (Elite Weekly)",{"t":"Previously: Complete 3 puzzles in Duviri","d":1},{"t":"Changes:","d":1},{"t":"Reduced puzzles from 3 to 1","d":2},{"t":"Changed from Elite Weekly to Weekly","d":2},"Day Trader (Elite Weekly)",{"t":"Previously: Win 3 wagers in a row without letting the enemy score in one match of The Index","d":1},{"t":"Changes:","d":1},{"t":"Removed the \"without letting the enemy score\" stipulation","d":2},{"t":"This Act is no longer locked behind The Glast Gambit quest as it is not required to access The Index","d":2},"Elite Explorer (Elite Weekly)",{"t":"Previously: Complete 8 Railjack Missions","d":1},{"t":"Change: Reduced mission requirements from 8 to 6","d":1},"Fallen Angel (Elite Weekly)",{"t":"Previously: Kill 5 Void Angels in The Zariman","d":1},{"t":"Change: Reduced Void Angels from 5 to 3","d":1}]},{"title":"Act Removals","items":[{"p":"Removed the following Railjack Acts:"},"Confiscated - Hijack a Crewship from the Enemy","Friendly Fire - While piloting Hijacked Crewship, destroy 3 enemy fighters",{"p":"These were removed as they were difficult to complete while playing in a Squad as it required you to essentially compete against your teammates to hijack a Crewship and kill enemies."}]},{"title":"Quality of Life Changes","items":["Recovering an Act now prioritizes Acts that are not locked.","Updated various Acts to be locked behind Quest/Junction/etc. requirements.",{"t":"The main reason for this effort is to play off of the Recovered Act change listed above. Prioritizing unlocked Acts means little if the Act recovered is still uncompletable. We've done our best to select minimum Lock criteria to access the content for the Act, to maintain flexibility where possible.","d":1},{"t":"Vox Solaris:","d":1},{"t":"Conservationist","d":2},{"t":"Now Boarding","d":2},{"t":"Venus Bounty Hunter","d":2},{"t":"Venus Fisher","d":2},{"t":"Venus Miner","d":2},{"t":"Howl of the Kubrow:","d":1},{"t":"Loyalty","d":2},{"t":"Duviri Paradox:","d":1},{"t":"Beast Slayer","d":2},{"t":"Horsin' Around","d":2},{"t":"Skeletons in the Closet","d":2},{"t":"I Decree","d":2},{"t":"Stolen Dreams:","d":1},{"t":"Animator","d":2},{"t":"The Archwing:","d":1},{"t":"Explorer","d":2},{"t":"Flawless","d":2},{"t":"Elite Explorer","d":2},{"t":"The New Strange:","d":1},{"t":"Test Subject","d":2},{"t":"Sanctuary Researcher","d":2},{"t":"Heart of Deimos:","d":1},{"t":"Vault Raider","d":2},{"t":"Feed the Beast","d":2},{"t":"Mirror, Mirror (also requires MR 3)","d":2},{"t":"Mastery Rank 3:","d":1},{"t":"Supporter","d":2},{"t":"Angels of the Zariman:","d":1},{"t":"Fallen Angel","d":2},{"t":"Mars Junction:","d":1},{"t":"Unlock Relics (and Elite version)","d":2},{"t":"Eris Junction:","d":1},{"t":"Vital Arbiter","d":2},"Updated various Act tips to help clarify how to complete them.","The Antiquarian Act now indicates what Relic types have already been unlocked.","Improved Weekly Act scheduling so there should be no more repeating Weekly Nightwave Acts (excluding the Permanent Weeklies) in a series.",{"p":"Image Description: Baruuk Shaoshi poses with his Rathan Sword & Shield, and Neviti Ephemera as if preparing to fight within the Sanctum Anatomica. Emanating from his morningstar-like sword, buckler-like shield, and stole-like ephemera is an almost spectral purple energy."}]},{"title":"BARUUK SHAOSHI COLLECTION","items":[{"p":"Transcend the chaos of battle. Baruuk Shaoshi's mystic runes show him the path to peace."},{"p":"This bundle contains the following items, which can all be purchased separately:"}]},{"title":"Baruuk Shaoshi Skin","items":[{"p":"Fear the gaze of Baruuk Shaoshi's mystic eye. His martial mastery, honed over long ages of defending sacred ground, is once again brought to bear against all enemies of peace."}]},{"title":"Rathan Sword & Shield Skin","items":[{"p":"Baruuk Shaoshi's signature Sword & Shield skin evokes the ancient arms carried by sacred guardians, those who embraced the balance between defense and attack."}]},{"title":"Liania Signa","items":[{"p":"The dignified drape of Baruuk Shaoshi's signature Signa is the mark of a warrior committed to defending peace - by any means necessary."}]},{"title":"Neviti Ephemera","items":[{"p":"Encircled by harmonious energy, the shifting balance of conflict reveals itself in Baruuk Shaoshi's signature ephemera."}]},{"title":"TENNOGEN: FABLES & FRONTIERS","items":[{"p":"Six new creations from community artists have arrived, including the first TennoGen pieces for Kullervo and Oraxia, two brand new Signas, and more!"},{"p":"Image Description: From left to right are three new Tennogen items: Oraxia Agamva Helmet, Haemadys Mask, and the Kullervo Ascophilia Skin."}]},{"title":"Kullervo Ascophilia Skin","items":[{"p":"A brand new Skin & Alt Helmet for Kullervo, designed by Erneix."}]},{"title":"Oraxia Agamva Helmet","items":[{"p":"A brand new Alt Helmet for Oraxia, designed by led2012."}]},{"title":"Haemadys Mask (Operator/Drifter)","items":[{"p":"An Infested mask, designed by Vhynnz."},{"p":"Image Description: Two new Tennogen items are shown - the Harrow Profitas Skin and the Centurio Signa."}]},{"title":"Harrow Profitas Skin","items":[{"p":"A Corpus inspired Skin & Alt Helmet for Harrow, designed by malaya, Jadie and Noxxr."}]},{"title":"Centurio Signa","items":[{"p":"A TennoGen Signa, designed by Lubox."}]},{"title":"Acheta Signa","items":[{"p":"A TennoGen Signa, designed by blazingcobalt and Ritens."},{"p":"Image Description: The Memetica Glyph Pack III glyphs are displayed across two rows and three columns. From left to right in the top row are Absolute Cinema, Arthur in the Fridge, and Chassis. While the second row shows Dump It, Kalymos Cone, and Lotus Change of Plans."}]},{"title":"MEMETICA GLYPH PACK III","items":[{"p":"A bundle of glyphs highlighting the very serious history of Warframe, created by Community artist ibumuc."},"Absolute Cinema Glyph","Arthur In The Fridge Glyph","Chassis Glyph","Dump It Glyph","Kalymos Cone Glyph","Lotus Change of Plans Glyph",{"p":"If you missed these glyphs during our TennoCon 2026 Memetica Twitch Drops Campaign in June & July, they are now live in the market to grab! They can be purchased for 90 Platinum in the bundle, or 20 Platinum per Glyph."}]},{"title":"ADDITIONS","items":["New Drippy UI Theme and Background are available to purchase from the \"Customize UI Theme\" options.",{"p":"Image Description: Screenshot of the new Drippy UI theme and background with Baruuk Shaoshi kneeling. The theme evokes a wet feeling with a rainy background, blue ripples that have a Drippy submerged near the center, and a splash of light red graffiti and two Drippies flanking Baruuk."},{"t":"To access: Open pause menu, select Options, select the Interface tab, select Customize UI Theme.","d":1},"Added an X Axis for Signa placement!",{"p":"Image Description: Composite image of two screenshots showing the Mesa Heirloom Signa being placed on Wisp. On the left shows the X-offset with a vertical double-sided arrow indicating the direction the signa may be moved. On the right shows the Y-offset showing the horizontal direction."},"Added Drifter versions of the Wolf Hood and the Umbra Hooded Scarf.",{"t":"Players who already owned the Operator version should see the Drifter version in their accounts upon login.","d":1},"Added various Fishing Stats to player profiles.","Added new Honoria for completing certain Challenges:",{"t":"|NAME| Leaves No Witnesses","d":1},{"t":"|NAME| The Demolitionist","d":1},{"t":"|NAME| Angel of Death","d":1},{"t":"|NAME| Plague Doctor","d":1},{"t":"|NAME| It Will Kill","d":1},{"t":"Restless |NAME|","d":1},{"t":"|NAME| Was Never Here","d":1},{"t":"|NAME| Will Do Anything For Money","d":1},{"t":"|NAME| Death from Above","d":1},{"t":"|NAME| Parazon Runner","d":1},"Added new Honoria to Roathe in exchange for various resources:",{"t":"|NAME| Cryomancer","d":1},{"t":"|NAME| Head Cracker","d":1},{"t":"|NAME| It's All Relative","d":1},{"t":"|NAME| Master of Minds","d":1},{"t":"Doctor |NAME|","d":1},{"t":"|NAME| Conscientious Objector","d":1},"Added new Honoria rewarded upon completing The Hex Quests:",{"t":"The Hex: Marty |NAME| McFlea","d":1},{"t":"The Hex Finale: Pizza Time for |NAME|","d":1},"Added a Personal Decorations option to the Dojo Room Console screen."]},{"title":"CHANGES","items":[]},{"title":"Sirius & Orion Changes","items":["Sirius & Orion's Jade Stars now uses (improved) Line of Sight.",{"t":"With our buffs to it earlier this summer, Jade Stars has become an exponentially popular Helminth ability due to its interactions with far-reaching Damage over Time abilities like Saryn's Spores. Our goal is to keep Jade Stars feeling powerful and impactful, but avoid situations where it can continually wipe the map without actually seeing the enemies it's killing (ie standing in a corner and triggering Jade Stars on repeat).","d":1},"Sirius & Orion's Celestial Clash now deals guaranteed Status Effects depending on which Son is Clashing.",{"t":"Sirius deals Heat Damage with a guaranteed Heat Status Effect.","d":1},{"t":"Orion deals Slash Damage with a guaranteed Slash Status Effect.","d":1},"Sirius & Orion will no longer swap to the Primary Son when using an item from the Gear Wheel"]},{"title":"General Changes","items":["Weapons with locked Explosion Radius now display a lock icon on that stat in the Arsenal.","Improved the flow when starting the Chimera Prologue from the Codex if you have another Active Quest.",{"t":"Previously, a certain interaction would not trigger if a different quest was set to Active. Now, starting the Chimera Prologue will clear all Active Quests so the interaction can occur.","d":1},"Enemy Highlights now apply to the Targets in the Mastery Rank 6 and Legendary Rank 6 tests.",{"t":"Also improved the visibility of lines between the targets in these tests.","d":1},"Resetting settings to Defaults now offers players the option to reset All Settings to default, or just the current Tab's settings.","Improved the dodge hint in the final segment of The Old Peace quest.","Railjack reticles are now solid white to improve their visibility.","Removed an incorrect Electric Shield ability tip for Volt.","Removed flashing VFX from Void Fissures in-mission to address photosensitivity concerns.","Made adjustments to the Commandeered Prime spawn SFX and mine explosion SFX in The Perita Rebellion.","The \"Mission Tutorial Transmissions\" toggle now applies to transmissions in Persto Survival and Hell-Scrub missions.","Background transmissions, such as Ordis chatter or start chart notifications, are now muted when viewing the Inbox."]},{"title":"PERFORMANCE & OPTIMIZATIONS","items":["Optimized in-game chat servers to handle larger numbers of players.","Fixed a minor hitch when joining a mission with a Sirius & Orion present."]},{"title":"FIXES","items":[]},{"title":"Top Fixes","items":["Fixed the Vectis Incarnon Form benefitting from Primed Chamber on every shot.","Fixed Nokko's Reroot Rampage Augment not triggering Archon Continuity.","Fixed Silken Stride's buff persisting after exiting the Ability if Oraxia does not have a Secondary Weapon equipped.","Fixed Incarnon Challenge progress being reset upon swapping to a channeled Exalted Weapon.","Fixed Nokko's Reroot Rampage's first bounce dealing no damage.","Fixed cases of Frozen enemies despawning in Netracell missions.","Fixed a method of being able to trigger Mirror Defense waves to start sooner than intended in Tyana Pass."]},{"title":"Sirius & Orion Fixes","items":["Fixed Cephalon Simaris blocking abilities based on the Inactive Son's casts in Sanctuary Onslaught missions.","Fixed swapping between Sons while entering a Nullifier Bubble resulting in the Secondary Son permanently losing access to his Abilities.","Fixed function loss caused by using Transference mid-Clash during Celestial Clash.",{"t":"Now Transference is prevented until the animation is completed.","d":1},"Fixed Sirius & Orion being able to sustain Void Fissure buffs for longer than the intended duration.","Fixed cases of pickups not being collected after swapping between Sons in Celestial Clash.","Fixed Sirius & Orion remaining permanently invulnerable due to an interaction with the Atomicycle.","Fixed a case of Sirius & Orion being able to equip the Vinquibis in only one weapon slot.","Fixed Arcane Concentration stacking multiple times for Clients with poor connection when equipped on Sirius & Orion.","Fixed Inactive Son running out of Heavy Weapon ammo resulting in their Melee weapon being disabled.","Fixed a loss of function when swapping between Sirius & Orion right before entering Submersible Archwing.","Fixed Sirius & Orion being able to become permanently stuck after dodging Vena's spike ability with Celestial Clash in The Kuva Wytch mission.","Fixed the Arsenal's Vehicles tab not displaying properly when accessed as Sirius & Orion in a Hub.","Fixed swapping to the Secondary Son resulting in Sirius & Orion being able to bypass the Noodletron-only restriction in Floaty of Fury Alerts.","Fixed cases of HUD buff icons not refreshing properly for Sirius & Orion.","Fixed Orion wielding a Melee weapon in non-combat areas (Base of Operations, Relays, etc.) if he has no Primary or Secondary equipped.","Fixed the Secondary Son's Secondary Weapon using the Appearance Config A instead of B.","Fixed Orion appearing in the background of the Loadout menu after swapping to a loadout with Sirius & Orion equipped."]},{"title":"Mission Fixes","items":["Fixed the possibility of getting a function loss when getting teleported to the Orowyrm fight during Duviri Experience activities.","Fixed Clients loading into an empty mission following a host migration while loading into a Scoria's Angel mission.","Fixed the Void Hole's explosion SFX being out of sync in Railjack missions.","Fixed cases of players being able to bypass Vena fight stages if they deal enough damage in a short window.","Fixed additional cases of Inaros and Sevagoth not being teleported if they are in their special death state during a transition in Uranus Proxima missions.","Fixed cases of Vena having a yellowish hue instead of the intended red in the final stage of her boss fight in The Kuva Wytch mission.","Fixed Ryoku's smoke bomb VFX missing for Clients in The Kuva Wytch mission.","Fixed flickering VFX on the Asteroid Field in The Kuva Wytch mission.","Fixed enemies remaining in the boss arena after Vena is defeated in The Kuva Wytch mission. Now any remaining living foes should be killed when she is.","Fixed allies being able to body block the \"Collect Artifact\" context action in The Kuva Wytch mission.","Fixed cases of being able to skip the Exterminate objective in The Kuva Wytch mission.","Fixed being able to use the Omni Recall with very specific timing during Uranus Proxima missions.","Fixed missing SFX when Vena is hacking in the Scoria's Angel mission.","Fixed allied Scaldra Eradicators sometimes dealing friendly fire with their grenades.","Fixed the Scrofa Attack Drone's hitbox not covering the majority of its body.","Fixed House Lavan Components not properly applying their unique trait if triggered via the Archwing Slingshot in Railjack missions."]},{"title":"UI Fixes","items":["Fixed waypoints lingering on the screen when an Ally's Companion is downed.","Fixed issues related to the \"Hide Equipped\" toggle in the Trading menu.","Fixed the weapon HUD disappearing after unequipping a Mining Laser or Scanner via the Gear Wheel.","Fixed cases of offered items extending off of the screen after using the \"select all\" option in the Trading Menu. This was a UI-only issue!","Fixed the \"Repeat Mission\" input bringing players to a broken Node selection pop-up in the Navigation screen.","Fixed Styanax Prime's diorama incorrectly listing Blueprint Details.","Fixed a loss of function when attempting to purchase Platinum via a flow of actions originating from the Arsenal Upgrade screen.","Fixed entering a Uranus Proxima mission with a personal Railjack resulting in the Squad HUD using the names of Ryoku or Vena's Crew. (This was a UI-only issue).","Fixed partial function loss when opening and exiting Chat Settings while in the Foundry.","Fixed Claw Mods being sorted into the Melee category instead of the Beast category.","Fixed being unable to upgrade Titania's Dex Pixia via the Loadout selection dropdown in the Navigation menu.","Fixed the squad overlay appearing in the Amp Customization screen.","Fixed the Equipment screen using the term Operator when the Drifter is equipped.","Fixed Sun & Moon appearing in the Uranus Junction end of mission screen, despite it being a reward from The Duviri Paradox.","Fixed the number on the Void Fissure tab in the Navigation menu not updating properly when swapping between Normal and Steel Path.","Fixed the Dojo Teleporter menu not respecting capitalization choices of players."]},{"title":"Quest Fixes","items":["Fixed a missing cinematic when returning to The Drifter Camp in The New War quest.","Fixed the incorrect HUD appearing briefly when loading into a mission in The Old Peace quest.","Fixed two Lotuses appearing in The Dark Refractory during The Old Peace quest.","Fixed placeholder text appearing in a pop-up during The Teacher quest.","Fixed a duplicate Vena and Ryoku appearing in their ending boss fight cutscenes in the Jade Shadows: Constellations quest.","Fixed cases of Stalker using the incorrect weapon during a cutscene in the Jade Shadows: Constellations quest.","Fixed rare cases of the Mission Fail screen appearing when transitioning from a mission in the Heart of Deimos quest.","Fixed a missing confirmation prompt when exiting the Operator customization in The Second Dream quest.","Fixed fast travelling to Palladino in the Iron Wake causing progression issues in the Chains of Harrow quest."]},{"title":"Cosmetic Fixes","items":["Fixed being unable to equip Amp Skins on the Mote Amp and Sirocco.","Fixed Garuda's Talons never being holstered when equipped as a Melee weapon in-mission.","Fixed Gemini Skin faces being deformed when swapping between Loadouts equipped with Gemini Skins in the Navigation screen.","Fixed various Emblem offsets on the Dante Tytonis Skin.","Fixed various Sugatra offsets on the Xoris Elixis Skin.","Fixed various leg armor offset issues on the Ryoku Gemini Skin, Vena Gemini Skin, and on Kullervo.","Fixed various chest armor offset issues on the Mesa Heirloom Skin, Voruna Medeina Skin, Drifter Goth Suit, Drifter Chymerist Suit, and Vena Gemini Skin.","Fixed various shoulder armor offset issues on Khora and Wisp.","Fixed various Daurus Prime armor set offset issues.","Fixed Mesa Heirloom's Syandana clipping through her legs with the Valkyr Carnivex Noble Animation equipped.","Fixed customizing Merulina resulting in Yareli briefly not using an animation set.","Fixed the Tealtrian Ephemera not properly applying Energy tints.","Fixed Octavia Prime's skirt not being removed when equipping the default Octavia skin.","Fixed an issue where selecting an Operator/Drifter Complexion Tint before it was fully initialized resulting in it applying at full Tint Vibrancy instead of the default of 0.05."]},{"title":"Misc. Fixes","items":["Fixed the Sanctum Anatomica becoming inaccessible when replaying a Quest.","Fixed the Archwing Articula decoration breaking if the equipped Loadout is deleted.","Fixed changing Dojo Dry Dock polychrome colors also affecting the Vessel.","Fixed walkways in the Dry Dock not being affected by Polychrome.","Fixed being unable to chatlink the Exploration Poster.",{"t":"Also fixed issues with its Market Diorama positioning.","d":1},"Fixed a lingering blocking volume in the Orb Vallis after completing the Jade Shadows: Constellations quest.","Fixed the Backroom using custom Camera Position settings after returning from a mission.","Fixed minor typos in a Hex chat and in Mother's bounty subtitles.","Fixed being unable to chatlink various Operator and Drifter suit pieces.","Fixed a file path in the Bladeswarm Nullifier Crewman Codex entry.","Fixed Sevagoth's Lullaby continuing to play after exiting its Market Diorama."]},{"title":"Crashes & Script Error Fixes","items":["Fixed a crash upon reviving as Sirius & Orion.","Fixed a crash upon returning to the Dry Dock with Vena in your Railjack Crew.","Fixed a script error in the Operator/Drifter Customization menu.","Fixed a script error related to Frost's Snow Globe.","Fixed a script error in Archwing Pursuit missions.","Fixed a script error when dropping an explosive Power Cell into a Gravity Conveyor while on Merulina during the Raptors assassination mission.","Fixed a script error when browsing through cosmetics in the Arsenal.","Fixed an edge case in the market where having the market open while an item is being retired caused a script error.","Fixed a script error related to the Orphix's anti-Warframe aura.","Fixed a rare crash for players that lingered in Relays or Hubs for 24+ hours.","Fixed a script error when subsuming an Ability or installing an Archon Shard in Sirius & Orion.","Fixed a script error related to Railjack component research.","Fixed a script error when killing a Grineer Roller while transitioning from an Open Landscape to the Hub.",{"p":"For list of known issues that are on our radar, visit our dedicated thread:"},{"p":"https://forums.warframe.com/topic/1519687-known-issues-amirs-shockwave/"}]}]}]},{"slug":"43-0-8","version":"43.0.8","kind":"hotfix","title":"Mesa Heirloom: Hotfix 43.0.8","url":"https://www.warframe.com/en/patch-notes/pc/43-0-8","forum":"https://forums.warframe.com/topic/1516479-mesa-heirloom-hotfix-4308/","date":"2026-07-13","dateSource":"patch notes","tldr":"1 other change.","fixes":0,"changes":1,"highlights":[],"mentions":[],"parts":[{"title":"Mesa Heirloom: Hotfix 43.0.8","sections":[{"title":"","items":[{"p":"Our TennoLive 2026 Relay gave players the ability to customize their Vessel as we set sights on Tau. While the Relay is now retired for another year, this hotfix brings Vessel customization for all Tenno!"}]},{"title":"Additions","items":["Added Vessel customization to all Dry Docks (including those in Dojos).",{"p":"For list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1509550-known-issues-jade-shadows-constellations/"}]}]}]},{"slug":"43-0-7","version":"43.0.7","kind":"hotfix","title":"Mesa Heirloom: Hotfix 43.0.7","url":"https://www.warframe.com/en/patch-notes/pc/43-0-7","forum":"https://forums.warframe.com/topic/1516048-mesa-heirloom-hotfix-4307/","date":"2026-07-11","dateSource":"patch notes","tldr":"Mesa Heirloom Skin; Mesa Heirloom Duster; Mesa Heirloom Signa; Mesa Heirloom Regulators Skin. 56 fixes.","fixes":56,"changes":0,"highlights":["Mesa Heirloom Skin","Mesa Heirloom Duster","Mesa Heirloom Signa","Mesa Heirloom Regulators Skin","Mesa Heirloom Color Palette","Mesa Heirloom Sigil","Mesa Heirloom Glyph","Mesa Heirloom Prex Card","Sirius & Orion","Uranus Proxima"],"mentions":[{"name":"Sirius & Orion","kind":"Warframe","n":12},{"name":"Mesa","kind":"Warframe","n":7},{"name":"Destreza","kind":"Weapon","n":2},{"name":"Jade","kind":"Warframe","n":2},{"name":"Protea","kind":"Warframe","n":2},{"name":"Sevagoth","kind":"Warframe","n":2},{"name":"Excalibur Umbra","kind":"Warframe","n":1},{"name":"Inaros","kind":"Warframe","n":1},{"name":"Nidus","kind":"Warframe","n":1},{"name":"Nokko","kind":"Warframe","n":1},{"name":"Obex","kind":"Weapon","n":1},{"name":"Primary Compression","kind":"Arcane","n":1},{"name":"Tenet Envoy","kind":"Weapon","n":1},{"name":"Voruna","kind":"Warframe","n":1}],"parts":[{"title":"Mesa Heirloom: Hotfix 43.0.7","sections":[{"title":"","items":[{"p":"MESA HEIRLOOM COLLECTION"},{"p":"LAUNCHES ON ALL PLATFORMS @ 11 A.M. ET"},{"p":"Saunter into the fray and send outlaws to their graves with the Mesa Heirloom Collection. Let her Regulators echo a ballad beneath the high-noon sun."}]},{"title":"Mesa Heirloom Skin","items":[{"p":"The legendary gunslinger. The notorious heartbreaker. Better call the undertaker, 'cause Mesa Heirloom just sauntered into town."}]},{"title":"Mesa Heirloom Duster","items":[{"p":"Mesa Heirloom's signature duster."},{"p":"You may also set the Auxiliary attachment option to None to remove the duster."}]},{"title":"Mesa Heirloom Signa","items":[{"p":"Mesa Heirloom's signature Signa reveals a dazzling hidden side to the vagabond enforcer."}]},{"title":"Mesa Heirloom Regulators Skin","items":[{"p":"Mesa Heirloom's signature Regulators."}]},{"title":"Mesa Heirloom Color Palette","items":[{"p":"A rodeo of colors honoring Mesa's legacy."}]},{"title":"Mesa Heirloom Sigil","items":[{"p":"Mesa Heirloom's sigil warns outlaws their time has come."}]},{"title":"Mesa Heirloom Glyph","items":[{"p":"These guns don't miss."}]},{"title":"Mesa Heirloom Prex Card","items":[{"p":"The notorious gunslinger."}]},{"title":"Top Fixes","items":["Fixed cases of Clients desyncing during Sirius & Orion's Celestial Clash, which could cause Clients to be ineligible for Relic Rewards in Void Fissures, and other effects.","Fixed cases of Clients teleporting to previous locations during Sirius & Orion's Celestial Clash.","Fixed Primary Compression not reducing explosive range and increasing damage for the Tenet Envoy while aiming down sights.","Fixed dying as the Secondary Son resulting in Sirius & Orion having no Secondary Weapon after reviving.","Fixed cases of players in a special state (Last Gasp, Protea's Temporal Anchor, Sevagoth's Shadow, etc.) not being teleported by objective countdown timers in Uranus Proxima missions.",{"t":"Known issue: This issue still occurs for Inaros in his special death state.","d":1},"Fixed instances of players getting stuck in mission load until restart.","Improved handling of crashes caused by running out of memory.","Fixed the Imperator Vandal receiving a duplicate entry in player Profiles.","Fixed the Secondary Son of Sirius & Orion being able to bypass weapon restrictions in Sortie missions."]},{"title":"Sirius & Orion Fixes","items":["Fixed the Mausolon not consuming ammo when equipped by the Secondary Son.","Fixed the Secondary Son being able to enter a Warframe-restricted area, and therefore a cinematic in the Angels of the Zariman quest.","Fixed swapping to Sirius & Orion from a Warframe with an Exalted weapon resulting in that Exalted Weapon's icon appearing next to the Secondary Son's name in the Arsenal.","Fixed Sirius & Orion being tiny in the Jordan Golem Assassinate extraction cinematic if you extracted as the Secondary Son.","Fixed cases of Sirius & Orion getting kicked out immediately after entering Points of Interest in Railjack missions.","Fixed the Vehicles tab not properly displaying in the Base of Operation's Arsenal if it was swapped to from Orion.",{"t":"Known Issue: this still occurs when accessing the Arsenal in different Hubs.","d":1},"Fixed the Secondary Son appearing in a cinematic during The Old Peace quest.","Fixed a certain cinematic fading out to a permanent black screen in The Old Peace quest if Sirius & Orion are equipped.","Fixed minor diorama issues in Sirius & Orion's Ability screens.","Fixed Sirius & Orion having the incorrect Scythes equipped during a segment in the Jade Shadows: Constellations quest.","Fixed various chest armor offset issues on Sirius & Orion.","Fixing a script error for Sirius & Orion when casting Well of Life."]},{"title":"Uranus Proxima Fixes","items":["Fixed the Vena or Ryoku's fight not starting if a squadmate is dead upon entering the Boss Fight room in Uranus Proxima missions.","Fixed cases of fog being incredibly bright on low-spec machines in Uranus Proxima missions.","Fixed cases of the Vault's door remaining open during the Mawbound Director fight, resulting in players being able to get stuck outside the room.","Fixed players being locked outside of the Sister fight in The Kuva Wytch missions if they died before it was triggered and revived after it had started.","Fixed cases of the Megacoil powercell counter not updating in the second stage of the Ryoku fight.","Fixed Necramechs not being disabled after Host Migration in Uranus Proxima missions.","Fixed Uranus Proxima missions not ending if players run out of revives or the Railjack suffers a catastrophic failure (that is not repaired in time).","Fixed Vena missing a hacking animation in Scoria's Angel missions.","Fixed borrowed Railjack using a player's equipped Tactical Mods after a Host Migration.","Fixed a case of Excalibur Umbra falling out of the map if they entered the Ramsled while in Transference during Scoria's Angel missions.","Fixed cases of waypoints not appearing for Clients in the \"Destroy Captured Ice Blocks\" objective in The Kuva Wytch mission.","Fixed Ryoku missing his smoke VFX upon disappearing in The Kuva Wytch mission.","Fixed a lighting issue in The Kuva Wytch.","Fixed Sisters using Transmissions that were not context appropriate in Uranus Proxima missions.","Fixed performance issues caused by Bladeswarm enemies.","Fixed a script error related to an enemy ability in Uranus Proxima missions.","Fixed a crash for Clients at the end of the Ramsled section of the Scoria's Angel mission."]},{"title":"Fixes","items":["Fixed the Base Damage added from the Destreza Incarnon's Evolution I and II not being reflected in the Arsenal stats. (This was a UI-only issue).","Fixed toggling \"Hide Equipped' in the Mods menu of the Trading screen resulting in the menu resetting to the All tab.","Fixed a progression stop in The Old Peace quest if you kill enemies too quickly during a certain segment.","Fixed the Glast Gambit quest becoming progression stopped if a specific situation happened while the Warframe was in a special state (ex: Nokko's Reroot, Sevagoth's Shadow, etc.).","Fixed sending a Protoframe a birthday message from the 1999 Calendar bringing players to the Hex KIM screen instead of the Protoframe who is celebrating their birthday.","Fixed Radiation Barrels spawning in the Corpus Ship tileset following its remaster.","Fixed the Obex and Destreza's Incarnon dioramas being too zoomed in.","Fixed an infinite mission countdown occurring after using the \"Visit Maroo\" option in the Ayatan Treasures screen while already in Maroo's Bazaar.","Fixed Latrox Une and Jarkar Lar's introductory transmissions not playing in-mission.","Fixed the ghostly Drifter disappearing after changing your Drifter's appearance in The New War quest.","Fixed players not seeing all newly-unlocked events and nodes until relog after completing the Vor's Prize quest.","Fixed offset issues with the Daurus Prime armor set on Voruna's Voidshell skin.","Fixed leaking VFX on a Jade idle animation.","Fixed a script error related to Mystic Bond.","Fixed a script error related to Transference.","Fixed a script error related to unmanned Dargyns in the Plains of Eidolon.","Fixed a script error related to Nidus' Link.","Fixed a script error related to Protea's Dispensary.",{"p":"For list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1509550-known-issues-jade-shadows-constellations/"}]}]}]},{"slug":"43-0-6","version":"43.0.6","kind":"hotfix","title":"Jade Shadows: Constellations: Hotfix 43.0.6","url":"https://www.warframe.com/en/patch-notes/pc/43-0-6","forum":"https://forums.warframe.com/topic/1514654-jade-shadows-constellations-hotfix-4306/","date":null,"dateSource":null,"tldr":"Steel Essence Acquisition in Steel Path Railjack; PC Exclusive. 13 fixes, 3 other changes.","fixes":13,"changes":3,"highlights":["Steel Essence Acquisition in Steel Path Railjack","PC Exclusive"],"mentions":[{"name":"Jade","kind":"Warframe","n":2},{"name":"Obex","kind":"Weapon","n":1},{"name":"Sirius & Orion","kind":"Warframe","n":1}],"parts":[{"title":"Jade Shadows: Constellations: Hotfix 43.0.6","sections":[{"title":"Steel Essence Acquisition in Steel Path Railjack","items":["Steel Path Railjack missions now reward 2 Steel Essence upon mission completion.",{"t":"Removed Steel Essence from Eximus drop tables in Steel Path Railjack missions.","d":1},{"t":"With the introduction of Steel Path Railjack, we added Steel Essence to Eximus drop tables since Acolytes cannot reliably spawn in Railjack missions. This system unfortunately did not meet our goals: space-only \"casual\" Railjack missions saw little in terms of Steel Essence acquisition, while savvy players were able to acquire significant amounts of Steel Essence in endless Railjack missions with the right amplified setup. Our aim is to serve all Railjack players, so we're changing our approach with this hotfix!","d":1}]},{"title":"Top Fixes","items":["Fixed Sirius & Orion's attacks no longer triggering Jade Stars.",{"t":"Also reduced the SFX of Sirius' Jade Stars.","d":1},"Fixed Combat Discipline not triggering when equipped on Sirius.","Fixed Sirius's Coronal Ejection only dealing one Heat Status effect regardless of its modded Status Chance.","Fixed the Obex Incarnon \"Rapid Conclusion\" Evolution treating Mercy and Finisher kills separately, causing stacks to reset from eligible kills.","Fixed enemies flying out of the map in Archwing Interception missions, causing players to not be able to complete the mission."]},{"title":"PC Exclusive Changes and Fixes","items":["Improved handling of shader corruption.","Improved defenses against drawing with broken shaders.","Fixed the launcher's mute button not saving preferences on future game launches."]},{"title":"Fixes","items":["Fixed the Mawbound Director not dealing any damage in The Kuva Wytch mission.","Fixed cases of borrowed Railjacks not being at full health at the start of Uranus Proxima missions.","Fixed the Scoria's Angel mission being progression stopped if players enter the Ramsled with a dead squadmate.","Fixed Clients rejoining into space if a host migration occurred right after boarding the Scoria Angel in its Uranus Proxima mission.","Fixed a script error in Uranus Proxima missions.","Fixed a script error in the Arsenal.","Fixed a script error related to the KIM system.",{"p":"For list of known issues that are on our radar, visit our dedicated thread: https://forums.warframe.com/topic/1509550-known-issues-jade-shadows-constellations/"}]}]}]}]};
